Title: You&#39;re importing a component that imports react-dom/server.
Body: <p>I am having the following error when I use the react-email package in my next.js project the problem is caused by the Tailwind component so when I comment it out it works but since I want to apply some classes to style my email any way I can get around  this would be appreciated, thanks in advance!</p>
<pre><code>Failed to compile
./node_modules\@react-email\tailwind\dist\index.mjs
ReactServerComponentsError:

You're importing a component that imports react-dom/server. To fix it, render or return the content directly as a Server Component instead for perf and security.
Learn more: https://nextjs.org/docs/getting-started/react-essentials

Maybe one of these should be marked as a client entry &quot;use client&quot;:
  ./node_modules\@react-email\tailwind\dist\index.mjs
  ./email\contact-form-email.tsx
  ./actions\sendEmail.ts

</code></pre>
<p>contact-form-email.tsx</p>
<pre><code>import React from 'react'
import {
    Html,Body,Head,Heading,Hr,Container,Preview,Section,Text
} from '@react-email/components';
// import {Tailwind} from '@react-email/tailwind'

type ContactFormEmailProps = {
    message: string;
    email: string;
}

export default function ContactFormEmail({message,email}: ContactFormEmailProps) {
  return (
    &lt;Html&gt;
    &lt;Head /&gt;
    &lt;Preview&gt;New message from your portfolio website&lt;/Preview&gt;
    {/* &lt;Tailwind&gt; */}
        &lt;Body className=&quot;bg-gray-100 text-black&quot;&gt;
            &lt;Container&gt;
                &lt;Section className=&quot;bg-white borderBlack my-10 px-10 py-4 rounded-md&quot;&gt;
                    &lt;Heading className=&quot;leading-tight&quot;&gt;You received the following message from the contact form.&lt;/Heading&gt;
                    &lt;Text&gt;{message}&lt;/Text&gt;
                    &lt;Hr /&gt;
                    &lt;Text&gt;The sender's email is: {email}&lt;/Text&gt;
                &lt;/Section&gt;
            &lt;/Container&gt;
        &lt;/Body&gt;
    {/* &lt;/Tailwind&gt; */}
    &lt;/Html&gt;
  )
}

</code></pre>

