&lt;/ContentPage&gt;
</code></pre>
<h2>MainPage.xaml. cs</h2>
<pre><code>using SQLite;
using System.Diagnostics;
using System.Collections.ObjectModel;

namespace SOTest;

public partial class MainPage : ContentPage
{

