<p>The app gets categories from an API and shows a list of different cards. I am using FlutterFlow for the whole project but this part was not generated.</p>
<p>Code:</p>
<pre><code>class _CategoriesWidgetState extends State&lt;CategoriesWidget&gt; {
  late CategoriesModel _model;

  final GenreProvider genreProvider = new GenreProvider();
  final scaffoldKey = GlobalKey&lt;ScaffoldState&gt;();

  @override
  void initState() {
    super.initState();
    _model = createModel(context, () =&gt; CategoriesModel());

    _model.textController ??= TextEditingController();
  }

  @override
  void dispose() {
    _model.dispose();

    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return FutureBuilder&lt;List&lt;Genre&gt;&gt;(
      future: genreProvider.getAllGenres(),
      builder: (context, snapshot) {
        if (snapshot.hasData) {
          final genres = snapshot.data;
          return Scaffold(
            key: scaffoldKey,
            backgroundColor: Color(0xFFF1F4F8),
            appBar: AppBar(
              backgroundColor: Color(0xFFB4FFA8),
              automaticallyImplyLeading: false,
              actions: [
                FlutterFlowIconButton(
                  borderColor: Colors.transparent,
                  borderRadius: 30.0,
                  borderWidth: 1.0,
                  buttonSize: 60.0,
                  icon: Icon(
                    Icons.person,
                    color: Colors.black,
                    size: 30.0,
                  ),
                  onPressed: () async {
                    await Navigator.push(
                      context,
                      MaterialPageRoute(
                        builder: (context) =&gt; UserConfigWidget(),
