Title: How to implement Drag And Drop between multiple ListViews with automatic Scrolling.
Body: <p>I am trying to implement drag and drop between multiple listviews in flutter and am fairly a new comer to flutter.</p>
<p>Below is the demo video of what I am trying to do and what is actually happening:-</p>
<p><a href="https://i.stack.imgur.com/VSsn7.gif" rel="nofollow noreferrer"><img src="https://i.stack.imgur.com/VSsn7.gif" alt="Demo Video of the App" /></a></p>
<p>The basic idea is as follows:-</p>
<ol>
<li>The items will be dragabble between the listviews for this I have used the Draggable and DragTarget Widgets and this part works fine as can be seen in DragDropItem below.</li>
<li>If the drag reaches top or bottom of the ListView the items will scroll automatically. For this I used Listener because it doesn't compete in the GestureArena so was the natural choice. But during my searches I came across a fact that <strong>Listener needs a TapDown Event to work</strong> which is true in the first Listview but not in the others.</li>
<li>There is a second problem here - the print statements are printing out the position of the first ListView(the one where the drag originates). This leads me to conclude that the other contexts are inactive at the moment but I am not sure why.</li>
<li>The listviews will be nested 3 levels deep. So, BoardView and DragDropLists can't be used.</li>
</ol>
<p>I have implemented the code as follows -</p>
<ol>
<li>I have used a horizontal listview containing vertical listviews.</li>
<li>I have created a widget named DragDropItem which is nothing but LongPressDraggable and DragTarget put together.</li>
<li>I have put a listview wrapped with listener widget in a widget of its own to avoid having to use a global key (Global keys are not making any difference in any case).</li>
<li>In the onMove callback of the listener I have put in some print statements to show what is going on.</li>
</ol>
<p>I am listing below the codes:</p>
<pre><code>// ignore_for_file: must_be_immutable

import 'package:draggable_listview/drag_drop_item.dart';
import 'package:flutter/material.dart';

class DragScrollableList extends StatelessWidget {
  final ScrollController _controller = ScrollController();
  bool _isDragging = false;

  DragScrollableList({super.key});

  @override
  Widget build(BuildContext context) {
    return Listener(
      onPointerMove: (event) {
        if (!_isDragging) {
          print('Is not Dragging');
          return;
        }
        print('Is Dragging');
        var renderObject = context.findRenderObject() as RenderBox;

        var size = renderObject.size;
        var renderOffset = renderObject.localToGlobal(Offset.zero);
        var dragOffset = renderObject.localToGlobal(event.localPosition);

        if (dragOffset.dx &gt; renderOffset.dx &amp;&amp;
            dragOffset.dx &lt; renderOffset.dx + size.width &amp;&amp;
            dragOffset.dy &gt; renderOffset.dy &amp;&amp;
            dragOffset.dy &lt; renderOffset.dy + size.height) {
          _controller.animateTo(dragOffset.dy + 100,
              duration: const Duration(milliseconds: 200), curve: Curves.ease);
        }

        print('ListView Size: $size');
        print('ListView Offset: $renderOffset');
        print('Drag Offset: $dragOffset');
      },
      child: ListView.builder(
        controller: _controller,
        itemCount: 30,
        itemBuilder: (context, index) =&gt; DragDropItem(
          onDragEnded: () =&gt; _isDragging = false,
          onDragStarted: () =&gt; _isDragging = true,
          value: 'Item $index',
          child: ListTile(
            title: Text('Item $index'),
          ),
        ),
      ),
    );
  }
}
</code></pre>
<pre><code>import 'package:flutter/material.dart';

class DragDropItem&lt;T extends Object&gt; extends StatelessWidget {
  final Widget _child;
  final T _value;
  final bool _vertical;

  final VoidCallback? _onDragStarted;
  final VoidCallback? _onDragEnded;

  const DragDropItem({
    super.key,
    required Widget child,
    required T value,
    bool vertical = true,
    VoidCallback? onDragStarted,
    VoidCallback? onDragEnded,
  })  : _onDragEnded = onDragEnded,
        _onDragStarted = onDragStarted,
        _vertical = vertical,
        _child = child,
        _value = value;

  @override
  Widget build(BuildContext context) {
    Widget draggable = LayoutBuilder(builder: (context, constraints) {
      return LongPressDraggable&lt;T&gt;(
        data: _value,
        maxSimultaneousDrags: 1,
        childWhenDragging: Opacity(
          opacity: 0.5,
          child: _child,
        ),
        feedback: Material(
          elevation: 4.0,
          child: ConstrainedBox(
            constraints: constraints,
            child: _child,
          ),
        ),
        onDragCompleted: () =&gt; _dragEnded(),
        onDragEnd: (details) =&gt; _dragEnded(),
        onDragStarted: () =&gt; _dragStarted(),
        // onDragUpdate: _onDragUpdate,
        onDraggableCanceled: (velocity, offset) =&gt; _dragEnded(),
        child: _child,
      );
    });
    return DragTarget&lt;T&gt;(
      builder: (
        BuildContext context,
        List&lt;T?&gt; candidateData,
        List&lt;dynamic&gt; rejectedData,
      ) {
        if (_vertical) {
          return Column(
            children: &lt;Widget&gt;[
              AnimatedSize(
                duration: const Duration(milliseconds: 100),
                child: candidateData.isEmpty
                    ? Container()
                    : Opacity(
                        opacity: 0.0,
                        child: _child,
                      ),
              ),
              candidateData.isEmpty ? draggable : _child
            ],
          );
        } else {
          return Row(
            children: &lt;Widget&gt;[
              AnimatedSize(
                duration: const Duration(milliseconds: 100),
                child: candidateData.isEmpty
                    ? Container()
                    : Opacity(
                        opacity: 0.0,
                        child: _child,
                      ),
              ),
              candidateData.isEmpty ? draggable : _child
            ],
          );
        }
      },
      onAccept: (data) =&gt; _dragEnded(),
      // onAcceptWithDetails: _onAcceptWithDetails,
      // onLeave: (data) =&gt; _dragEnded(),
      // onMove: _onMove,
      onWillAccept: (data) {
        if (data != null &amp;&amp; _value != data) {
          return true;
        }
        return false;
      },
    );
  }

  void _dragEnded() {
    if (_onDragEnded == null) {
      return;
    }
    _onDragEnded!();
  }

  void _dragStarted() {
    if (_onDragStarted == null) {
      return;
    }
    _onDragStarted!();
  }
}
</code></pre>
<pre><code>import 'dart:ui';

import 'package:flutter/material.dart';

import 'drag_drop_item.dart';
import 'drag_scrollable_list.dart';
import 'draggable_list.dart';

void main() {
  runApp(const MyApp());
}

class MyCustomScrollBehavior extends MaterialScrollBehavior {
  @override
  Set&lt;PointerDeviceKind&gt; get dragDevices =&gt; {
        PointerDeviceKind.touch,
        PointerDeviceKind.mouse,
        // etc.
      };
}

class MyApp extends StatelessWidget {
  const MyApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      scrollBehavior: MyCustomScrollBehavior(),
      title: 'Flutter Demo',
      theme: ThemeData(
        primarySwatch: Colors.blue,
      ),
      home: const MyHomePage(title: 'Flutter Demo Home Page'),
    );
  }
}

class MyHomePage extends StatefulWidget {
  const MyHomePage({super.key, required this.title});

  final String title;

  @override
  State&lt;MyHomePage&gt; createState() =&gt; _MyHomePageState();
}

class _MyHomePageState extends State&lt;MyHomePage&gt; {
  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text(widget.title),
      ),
      body: ListView.builder(
        itemCount: 5,
        scrollDirection: Axis.horizontal,
        itemBuilder: (BuildContext context, int index) {
          return DragDropItem(
            value: List.generate(30, (index) =&gt; 'Item $index'),
            vertical: false,
            child: SizedBox(
              width: 300.0,
              child: DragScrollableList(),
            ),
            // child: const DraggableList(
            //   maxHeight: 2500.0,
            //   maxWidth: 350.0,
            // ),
          );
        },
      ),
    );
  }
}
</code></pre>
<p>So, can I make the listener listen to pointer events even if it doesn't receive on tap down first? If not can I achieve my objective some other way?</p>
<p>Any help on the subject is appreciated. Thanks in advance.</p>

Title: ERROR encountered only below iOS 17 devices &quot;Thread 1: EXC_BAD_ACCESS (code=1, address=0x0)&quot;.
Body: <p>I've just updated my XCode to version 15, and I encountered this error (only iOS versions below 17) </p>
<pre><code>Thread 1: EXC_BAD_ACCESS (code=1, address=0x0)
</code></pre>
<p>code that shows this error (PathMonitorConectivityProvider.swift):</p>
<p>When I ran my code from XCode (the iOS device version is iOS 16.4), an exception occurred in the below code.</p>
<pre><code>import Foundation
import Network

@available(iOS 12, *)
public class PathMonitorConnectivityProvider: NSObject, ConnectivityProvider {

  private let queue = DispatchQueue.global(qos: .background)

  private var _pathMonitor: NWPathMonitor?

  public var currentConnectivityType: ConnectivityType {
    let path = ensurePathMonitor().currentPath
    // .satisfied means that the network is available
    if path.status == .satisfied {
      if path.usesInterfaceType(.wifi) {
        return .wifi
      } else if path.usesInterfaceType(.cellular) {
        return .cellular
      } else if path.usesInterfaceType(.wiredEthernet) {
        // .wiredEthernet is available in simulator
        // but for consistency it is probably correct to report .wifi
        return .wifi
      } else if path.usesInterfaceType(.other) {
        return .other
      }
    }
    return .none
  }

  public var connectivityUpdateHandler: ConnectivityUpdateHandler?

  override init() {
    super.init()
    _ = ensurePathMonitor()
  }

  public func start() {
    _ = ensurePathMonitor()
  }

  public func stop() {
    _pathMonitor?.cancel()
    _pathMonitor = nil
  }

  @discardableResult
  private func ensurePathMonitor() -&gt; NWPathMonitor {
    if (_pathMonitor == nil) {
      let pathMonitor = NWPathMonitor()
      pathMonitor.start(queue: queue)
      pathMonitor.pathUpdateHandler = pathUpdateHandler
      _pathMonitor = pathMonitor
    }
    return _pathMonitor!
  }

  private func pathUpdateHandler(path: NWPath) {
    connectivityUpdateHandler?(currentConnectivityType)
  }
}
