#TIMELIMIT      15
#DEREF          never

# TLS certificates (needed for GnuTLS)
TLS_CACERT      /etc/ssl/certs/ca-certificates.crt
</code></pre>
<p>Other details of my environment:</p>
<pre><code># dotnet --info
