Title: Changing element ID after animation causes error &quot;Multiple inserted views in matched geometry group Pair&lt;String, ID&gt;(first: &quot;B&quot;, second: &quot;.
Body: <p>I have a scroll view that contains elements, and I use a matched geometry effect to animate an element above the screen when it is clicked (kind of creating a new view on top). I have to change the IDS in the matched geometry modifier, and this solution details why: <a href="https://stackoverflow.com/a/76795258/18070009">https://stackoverflow.com/a/76795258/18070009</a>. But in doing so, I raise the warning below.</p>
<p>Does anyone know why this occurs and how I can fix it?</p>
<p>The warning:</p>
<p><code>Multiple inserted views in matched geometry group Pair&lt;String, ID&gt;(first: &quot;B&quot;, second: SwiftUI.Namespace.ID(id: 3543)) have isSource: true, results are undefined.</code></p>
<p>The code:</p>
<pre><code>struct NewsReplyView: View {
    @Namespace var namespace
    @State var text: String = &quot;&quot;
    @State var selected: String = &quot;&quot;
    @State var show = false
    @State var loaded = false
    @State var arr = [&quot;1&quot;, &quot;2&quot;, &quot;3&quot;, &quot;4&quot;, &quot;5&quot;]
    var body: some View {
        ZStack {
            VStack{
                ForEach(arr.indices) { i in
                    RoundedRectangle(cornerRadius: 20).frame(width: 100, height: 100)
                        .id(arr[i])
                        .onTapGesture {
                            withAnimation(.spring()){
                                show.toggle()
                                selected = arr[i]
                                DispatchQueue.main.asyncAfter(deadline: .now() + 0.3) {
                                    loaded = true
                                }
                            }
                        }
                //changing here causes warning 
                        .matchedGeometryEffect(id: loaded ? &quot;A&quot; : selected, in: namespace)
                }
            }.opacity(show ? 0.0 : 1.0)
            if show {
                VStack{
                    RoundedRectangle(cornerRadius: 20).frame(width: 100, height: 100)
                        .id(selected)
             //changing here causes warning 
                        .matchedGeometryEffect(id: loaded ? &quot;B&quot; : selected, in: namespace) 
                    Spacer()
                    if loaded {
                        HStack{
                            TextField(&quot;&quot;, text: $text)
                                .onSubmit {
                                    UIApplication.shared.sendAction(#selector(UIResponder.resignFirstResponder), to: nil, from: nil, for: nil)
                                }
                            Button {
                                withAnimation(.spring()){
                                    loaded = false
                                    DispatchQueue.main.asyncAfter(deadline: .now() + 0.1) {
                                        withAnimation(.spring()){
                                            show.toggle()
                                        }
                                    }
                                }
                            } label: {
                                Image(systemName: &quot;xmark.circle.fill&quot;)
                            }
                        }
                    }
                }
            }
        }
    }
}
</code></pre>

