        CredentialsProvider({
            name: &quot;credentials&quot;,
            credentials: {
                email: { label: &quot;Email&quot;, type: &quot;email&quot;, placeholder: &quot;&quot;},
                password: { label: &quot;Password&quot;, type: &quot;password&quot;, placeholder: &quot;&quot;}
