Title: Is there a way to reinitialize jQuery?.
Body: <h2>Question</h2>
<p>JQuery is initialized on <code>import</code>. If <code>window</code> and <code>window.document</code> exist (and <code>module</code> doesn't), JQuery saves the references and uses them thereafter.</p>
<p>Is there a way I can &quot;reinitialize&quot; or &quot;reset&quot; JQuery after it's been <code>import</code>ed to give it a different reference to <code>window</code> and <code>document</code>?</p>
<h2>A failing testcase part 1</h2>
<h3>Project Structure</h3>
<pre><code>.
├── .eslintrc.json
├── .prettierrc
├── index.spec.js
├── package.json
├── README.md
├── spec/
│   └── support/
│       ├── jasmine-spec.json
│       ├── logger.js
│       ├── slow-spec-reporter.js
│       └── type-check.js
├── template1.html
└── template2.html
</code></pre>
<h3>./index.spec.js</h3>
<pre><code>import { JSDOM } from 'jsdom';

describe('jquery', () =&gt; {
  it('uses the currently available document', async () =&gt; {
    const { document: template1Document, jquery: template1Jquery } = await parseHtml('template1.html');
    expect(template1Document.querySelector('p').textContent).toEqual('Hello world');
    expect(template1Jquery.find('p').text()).toEqual('Hello world');

    const { document: template2Document, jquery: template2Jquery } = await parseHtml('template2.html');
    expect(template2Document.querySelector('p').textContent).toEqual('Goodbye world');
    expect(template2Jquery.find('p').text()).toEqual('Goodbye world'); // !!! 
    // Expected 'Hello world' to equal 'Goodbye world'.
  });
});

async function parseHtml(fileName) {
  const dom = await JSDOM.fromFile(fileName, {
    url: 'http://localhost',
    runScripts: 'dangerously',
    resources: 'usable',
    pretendToBeVisual: true,
  });
  const window = dom.window;
  const document = window.document;

  globalThis.window = window;
  globalThis.document = document;

  const dynamicImport = await import('jquery');

  const $ = dynamicImport.default;

  return {
    document: document,
    jquery: $(`html`),
  };
}

</code></pre>
<h3>./template1.html</h3>
<pre><code>&lt;!doctype html&gt;
&lt;html lang=&quot;en&quot;&gt;
  &lt;head&gt;
    &lt;meta charset=&quot;utf-8&quot; /&gt;
    &lt;title&gt;template1.html&lt;/title&gt;
  &lt;/head&gt;
  &lt;body&gt;
    &lt;p&gt;Hello world&lt;/p&gt;
  &lt;/body&gt;
&lt;/html&gt;

</code></pre>
<h3>./template2.html</h3>
<pre><code>&lt;!doctype html&gt;
&lt;html lang=&quot;en&quot;&gt;
  &lt;head&gt;
    &lt;meta charset=&quot;utf-8&quot; /&gt;
    &lt;title&gt;template2.html&lt;/title&gt;
  &lt;/head&gt;
  &lt;body&gt;
    &lt;p&gt;Goodbye world&lt;/p&gt;
  &lt;/body&gt;
&lt;/html&gt;

</code></pre>
<p>This is an excerpt of the code, but you can find <a href="https://github.com/DanKaplanSES/jsdom-sandbox/tree/reinit-jquery-so" rel="nofollow noreferrer">a complete github repository</a> here.</p>
<p>It's not enough to reinitialize one or some of the <code>import</code>ed jquery's, all the jquery references need to be reinitialized. For example, if a production file starts with <code>import jQuery from 'jquery'</code>, that <code>jQuery</code> needs to be a reference to the reinitialized jquery. This is hard to explain so I'll show what I mean with another failing testcase:</p>
<h2>A failing testcase part 2</h2>
<h3>Project Structure</h3>
<pre><code>.
├── .eslintrc.json
├── .prettierrc
├── index.spec.js
├── package.json
├── prod-code.js
├── README.md
├── spec/
│   └── support/
│       ├── jasmine-spec.json
│       ├── logger.js
│       ├── slow-spec-reporter.js
│       └── type-check.js
├── template1.html
├── template2.html
└── test-setup.js
</code></pre>
<h3>./index.spec.js</h3>
<pre><code>import * as testSetup from './test-setup.js';
import * as prodCode from './prod-code.js';

describe('jquery', () =&gt; {
  it('dynamic imports affect static imports template1', async () =&gt; {
    await testSetup.parseHtmlWithDynamicImport('template1.html');

    const { document: template1Document, jquery: template1Jquery } =
      await prodCode.parseHtmlWithJQueryStaticImport('template1.html'); // !!!
    // Error: jQuery requires a window with a document
    expect(template1Document.querySelector('p').textContent).toEqual(
      'Hello world'
    );
    expect(template1Jquery.find('p').text()).toEqual('Hello world');
  });

  it('dynamic imports affect static imports template2', async () =&gt; {
    await testSetup.parseHtmlWithDynamicImport('template2.html');

    const { document: template2Document, jquery: template2Jquery } =
      await prodCode.parseHtmlWithJQueryStaticImport('template2.html'); // !!!
    // Error: jQuery requires a window with a document
    expect(template2Document.querySelector('p').textContent).toEqual(
      'Goodbye world'
    );
    expect(template2Jquery.find('p').text()).toEqual('Goodbye world');
  });
});

</code></pre>
<h3>./test-setup.js</h3>
<pre><code>import { JSDOM} from 'jsdom'

export async function parseHtmlWithDynamicImport(fileName) {
    const dom = await JSDOM.fromFile(fileName, {
      url: 'http://localhost',
      runScripts: 'dangerously',
      resources: 'usable',
      pretendToBeVisual: true,
    });

    const dynamicImport = await import('jquery');
    const $ = dynamicImport.default(dom.window);
    return {
      document: dom.window.document,
      jquery: $(`html`),
    };
  }

</code></pre>
<h3>./prod-code.js</h3>
<pre><code>import { JSDOM } from 'jsdom';
import jQuery from 'jquery';

export async function parseHtmlWithJQueryStaticImport(fileName) {
  const dom = await JSDOM.fromFile(fileName, {
    url: 'http://localhost',
    runScripts: 'dangerously',
    resources: 'usable',
    pretendToBeVisual: true,
  });


  return {
    document: dom.window.document,
    jquery: jQuery(`html`),
  };
}

</code></pre>
<h3>./template1.html</h3>
<pre><code>&lt;!doctype html&gt;
&lt;html lang=&quot;en&quot;&gt;
  &lt;head&gt;
    &lt;meta charset=&quot;utf-8&quot; /&gt;
    &lt;title&gt;template1.html&lt;/title&gt;
  &lt;/head&gt;
  &lt;body&gt;
    &lt;p&gt;Hello world&lt;/p&gt;
  &lt;/body&gt;
&lt;/html&gt;

</code></pre>
<h3>./template2.html</h3>
<pre><code>&lt;!doctype html&gt;
&lt;html lang=&quot;en&quot;&gt;
  &lt;head&gt;
    &lt;meta charset=&quot;utf-8&quot; /&gt;
    &lt;title&gt;template2.html&lt;/title&gt;
  &lt;/head&gt;
  &lt;body&gt;
    &lt;p&gt;Goodbye world&lt;/p&gt;
  &lt;/body&gt;
&lt;/html&gt;

</code></pre>
<p>This is an excerpt of the code, but <a href="https://github.com/DanKaplanSES/jsdom-sandbox/tree/reinit-jquery-dynamic-and-static-imports-failing-testcase-so" rel="nofollow noreferrer">you can find a complete github repository</a> here.</p>
<h2>Context</h2>
<p>I'm working on a frontend-only, single page app project. Even though the project runs exclusively in the browser, the automated tests run in Node.JS. The tests load the html in <a href="https://github.com/jsdom/jsdom/" rel="nofollow noreferrer">JSDOM</a> and execute portions of the production code.<sup>1</sup></p>
<p>On creation, JSDOM returns a DOM API that works in Node.JS, including a <code>window</code> object. Without this, jQuery will error on <strong>import</strong> because modern versions <a href="https://cdnjs.cloudflare.com/ajax/libs/jquery/3.3.1/jquery.js" rel="nofollow noreferrer">have code like this</a>:</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>(function(global, factory) {

    "use strict";

    if (typeof module === "object" &amp;&amp; typeof module.exports === "object") {

      // For CommonJS and CommonJS-like environments where a proper `window`
      // is present, execute the factory and get jQuery.
      // For environments that do not have a `window` with a `document`
      // (such as Node.js), expose a factory as module.exports.
      // This accentuates the need for the creation of a real `window`.
      // e.g. var jQuery = require("jquery")(window);
      // See ticket trac-14549 for more info.
      module.exports = global.document ?
        factory(global, true) :
        function(w) {
          if (!w.document) {
            throw new Error("jQuery requires a window with a document");
          }
          return factory(w);
        };
    } else {
      factory(global);
    }

    // Pass this if window is not defined yet
  })(typeof window !== "undefined" ? window : this, function(window, noGlobal) {
    console.log(`window`, window);
    console.log(`noGlobal`, noGlobal);
  })</code></pre>
<pre class="snippet-code-html lang-html prettyprint-override"><code>&lt;script src="https://cdnjs.cloudflare.com/ajax/libs/jquery/3.3.1/jquery.min.js"&gt;&lt;/script&gt;</code></pre>
</div>
</div>
</p>
<p>As you can see, this executes as a side effect of <strong>import</strong>ing jQuery. This has caused considerable headache because it isn't always straightforward to create JSDOM before importing jQuery.</p>
<p>For example, if the production code imports jQuery and the test imports the production code, JSDOM (and therefore <code>window</code>) won't exist yet. ~~This throws an error.~~ And when it's later used, <code>window</code> won't be set.</p>
<p>But here's a more important use case: I want to be able to use different HTML files in my tests, but this is limiting me to one per test run.</p>
<p>Someday, I'd like to release this test code as a test framework to the public. Some people may explicitly <code>import jQuery from 'jquery'</code> or <code>import $ from 'jquery'</code> or use a <code>jQuery</code>/<code>$</code> in the global scope. Ideally, they wouldn't have to modify their production code to use my framework.</p>
<hr />
<h2>Notes</h2>
<p>For the record, I'm using jQuery 3.7.1, but stackoverflow code snippets don't give me the option to pick that version. I think that's fine because, as far as I can tell, this code is the same in both.</p>
<p><sup>1</sup>: Unfortunately, that means going against the official JSDOM advice. But in <em>this</em> context, I can't see a way around that.</p>

Title: iOS Safari overriding 100vh on input focus: Injecting empty space below the DOM.
Body: <p>When an input field is selected on iOS Safari, about ≈150px is injected, outside of the DOM, below the HTML tag</p>
<p><a href="https://i.stack.imgur.com/HGR3z.gif" rel="nofollow noreferrer"><img src="https://i.stack.imgur.com/HGR3z.gif" alt="enter image description here" /></a></p>
<p>In the screenshot above the green border has been applied to the HTML element - and the black scrollable area beneath is only accessible on iOS safari when an input field has been focused. While the HTML element retains its 100vh/svh attribute</p>
<p>You can see the <code>&lt;HTML&gt;</code> tag turn blue when I hover over the element in the console... I've done this to help show that the empty space is not related to the webpage itself</p>
<p>The expected functionality is for the keyboard not to inject this spacing below the keyboard… as is the case for other browsers on iOS</p>
<p><a href="https://i.stack.imgur.com/rI3Pz.png" rel="nofollow noreferrer"><img src="https://i.stack.imgur.com/rI3Pz.png" alt="enter image description here" /></a></p>
<p>I've spent some time messing around with different height values (SVH is preferred in my instance) and overflow style settings, using JS and CSS, but none of that has an impact because the space added to the webpage appears to be independent of the DOM and inaccessible via the console</p>
<p>Specifically, I've experimented with calculating the actual viewport height when the page loads, and then using this fixed value throughout the lifetime of the page - by applying this fixed value to the body/html element to ensure that no extra space is added at the bottom when the keyboard is displayed</p>
<p><code>CSS</code></p>
<pre><code>body {
  --vh: 100vh; /* Fallback for browsers that do not support Custom Properties */
  height: calc(var(--vh, 1vh) * 100);
  overflow: auto;
}
</code></pre>
<p><code>JS</code></p>
<pre><code>useEffect(() =&gt; {
  let vh = window.innerHeight * 0.01;
  document.documentElement.style.setProperty('--vh', `${vh}px`);

  window.addEventListener('resize', () =&gt; {
    let vh = window.innerHeight * 0.01;
    document.documentElement.style.setProperty('--vh', `${vh}px`);
  });

  return () =&gt; {
    window.removeEventListener('resize', () =&gt; {
      let vh = window.innerHeight * 0.01;
      document.documentElement.style.setProperty('--vh', `${vh}px`);
    });
  };
}, []);
</code></pre>
<p>But since the space injected does not appear to be a part of the DOM - updating the height of the <code>&lt;HTML&gt;</code> or <code>&lt;body&gt;</code> tags does not actually resolve the issue.</p>
<p>Has anyone found a solution for this?</p>
<ul>
<li><a href="https://codesandbox.io/s/purple-dew-fibs5k?file=/src/index.tsx" rel="nofollow noreferrer">Code Sandbox (Code)</a></li>
<li><a href="https://fibs5k.csb.app/" rel="nofollow noreferrer">Code Sandbox (Demo)</a></li>
<li><a href="https://imgur.com/a/ZphP7Pg" rel="nofollow noreferrer">Screen Recording</a></li>
<li><a href="https://stackoverflow.com/questions/66122046/why-does-my-html-page-get-additional-unwanted-height-on-mobile-safari">Another (unresolved) SO thread discussing the same issue</a></li>
</ul>

Title: Toggling &quot;hidden&quot; attribute using javascript.
Body: <p>I want to show and hide an &lt;input&gt; element based on the &lt;select&gt; value.
I found a way to do it, but I think it's so much code for a simple purpose. What could be a better way?</p>
<p>Here's the code I wrote without using any frameworks:</p>
