Title: Next 13.4 Error: NEXT_REDIRECT in API routes.
Body: <p>My /app/api/auth/route.ts file:</p>
<pre><code>import { redirect } from 'next/navigation';

export async function GET(req: Request) {
  try {
    redirect('/dashboard');
  } catch (error) {
    console.log(error);
    redirect('/');
  }
}
