<pre><code>                buttons: [
                    {
                        id: &quot;MyOkBtn&quot;,
                        text: '&lt;i class=&quot;fa fa-check-circle&quot; aria-hidden=&quot;true&quot;&gt;&lt;/i&gt;Ok',
