Title: Issues with setting GlobalWorkerOptions.workerSrc and loading jsPDF library in a PDF to JPG conversion web page.
Body: <p>I am trying to create an HTML web page that can convert a PDF file to JPG images and then export the rearranged pages as a new PDF file.</p>
<p>The codes are shown as follows:</p>
<pre><code>&lt;!DOCTYPE html&gt;
&lt;html&gt;
  &lt;head&gt;
    &lt;title&gt;PDF pages rearranger&lt;/title&gt;
    &lt;script src=&quot;https://cdnjs.cloudflare.com/ajax/libs/pdf.js/2.10.377/pdf.min.js&quot;&gt;&lt;/script&gt;
    &lt;style&gt;
      /* Define the style for the container element */
      #container {
        width: 600px;
        height: 400px;
        border: 1px solid black;
        margin: 20px auto;
        overflow: auto;
      }

      /* Define the style for the image elements */
      img {
        width: 100px;
        height: 100px;
        margin: 10px;
        cursor: move; /* Change the cursor to indicate that the images are draggable */
      }
    &lt;/style&gt;

    &lt;!-- Load the jQuery library from a CDN --&gt;
    &lt;script src=&quot;https://code.jquery.com/jquery-3.6.0.min.js&quot;&gt;&lt;/script&gt;

    &lt;!-- Load the jQuery UI library from a CDN --&gt;
    &lt;script src=&quot;https://code.jquery.com/ui/1.13.0/jquery-ui.min.js&quot;&gt;&lt;/script&gt;

    &lt;!-- Load the jsPDF library from a CDN --&gt;
    &lt;script src=&quot;https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js&quot;&gt;&lt;/script&gt;
  &lt;/head&gt;
  &lt;body&gt;
    &lt;input type=&quot;file&quot; id=&quot;fileInput&quot; accept=&quot;.pdf&quot; /&gt;
    &lt;button id=&quot;convertButton&quot;&gt;Convert to JPG&lt;/button&gt;
    &lt;!-- Create a div element to hold the images --&gt;
    &lt;div id=&quot;container&quot;&gt;&lt;/div&gt;
    &lt;!-- Create a button to export the rearranged pages as a new PDF file --&gt;
    &lt;button id=&quot;exportButton&quot;&gt;Export as PDF&lt;/button&gt;

    &lt;script&gt;
      // Set the GlobalWorkerOptions.workerSrc property
      window.GlobalWorkerOptions = {
        workerSrc: 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/2.10.377/pdf.worker.min.js'
      };

      const fileInput = document.getElementById('fileInput');
      const convertButton = document.getElementById('convertButton');
      const container = document.getElementById('container');
      const exportButton = document.getElementById('exportButton');

      convertButton.addEventListener('click', async () =&gt; {
        const file = fileInput.files[0];
        if (!file) {
          alert('Please select a PDF file first');
          return;
        }

        // Clear any existing images in the container
        container.innerHTML = '';

        const reader = new FileReader();
        reader.onload = async (event) =&gt; {
          const typedArray = new Uint8Array(event.target.result);
          const pdfDocument = await pdfjsLib.getDocument(typedArray).promise;
          const numPages = pdfDocument.numPages;

          for (let i = 1; i &lt;= numPages; i++) {
            const page = await pdfDocument.getPage(i);
            const viewport = page.getViewport({ scale: 1.0 });
            const canvas = document.createElement('canvas');
            canvas.width = viewport.width;
            canvas.height = viewport.height;
            const ctx = canvas.getContext('2d');
            await page.render({ canvasContext: ctx, viewport }).promise;
            const dataUrl = canvas.toDataURL('image/jpeg');
            download(dataUrl, `page${i}.jpg`);

            // Create an img element for each page and add it to the container
            const img = document.createElement('img');
            img.src = dataUrl;
            img.alt = `Page ${i}`;
            container.appendChild(img);
          }

          // Make the image elements draggable and sortable using jQuery UI
          $(&quot;#container&quot;).sortable({
            // Define a helper function to create a clone of the dragged image
            helper: function(e, ui) {
              return $(ui).clone().appendTo(&quot;#container&quot;).show();
            }
          });
        };
        reader.readAsArrayBuffer(file);
      });

      exportButton.addEventListener('click', () =&gt; {
        // Create a new jsPDF instance
        const doc = new jsPDF();

        // Get all the img elements in the container
        const images = container.querySelectorAll('img');

        // Add each image to the PDF document
        images.forEach((img, index) =&gt; {
          if (index &gt; 0) {
            doc.addPage();
          }
          doc.addImage(img.src, 'JPEG', 10, 10);
        });

        // Save the PDF document
        doc.save('rearranged.pdf');
      });

      function download(dataUrl, filename) {
        const link = document.createElement('a');
        link.href = dataUrl;
        link.download = filename;
        link.click();
      }
    &lt;/script&gt;
  &lt;/body&gt;
&lt;/html&gt;

</code></pre>
<p>However, when I tried to run the code, I encountered two issues:</p>
<p>The first warning message appears when I click the &quot;Convert to JPG&quot; button, saying “Deprecated API usage: No GlobalWorkerOptions.workerSrc specified.” I guess it is caused by the fact that the GlobalWorkerOptions.workerSrc property is not being set correctly.</p>
<p>The second warning message appears when I click the &quot;Export as PDF&quot; button, saying “Uncaught ReferenceError: jsPDF is not defined.” So seems the jsPDF library is not being loaded correctly.</p>
<p>Can anyone help me understand what might be causing these issues and provide suggestions for how to resolve them?</p>
