Title: How to draw a spline with varying stroke widths in JS.
Body: <p>I can draw a <a href="https://jsfiddle.net/changsin_tw/mvgkdLwn/1/" rel="nofollow noreferrer">spline using d3</a> without a problem.</p>
<pre><code>&lt;html&gt;
&lt;head&gt;
    &lt;script src=&quot;https://d3js.org/d3.v7.min.js&quot;&gt;&lt;/script&gt;
    &lt;style&gt;
        .graph-container {
            width: 100%;
            height: 800px;
            position: relative;
        }
    &lt;/style&gt;
&lt;/head&gt;
&lt;body&gt;
    &lt;div id=&quot;graph-container&quot; class=&quot;graph-container&quot;&gt;&lt;/div&gt;
    &lt;script&gt;
        // Define the data points for the spline curve
        const data = [
            { x: 0, y: 80, r: 12 },
            { x: 100, y: 100, r: 40 },
            { x: 200, y: 30, r: 6 },
            { x: 300, y: 50, r: 8 },
            { x: 400, y: 40, r: 10 },
            { x: 500, y: 80, r: 12 },
        ];

        // Set up the SVG container
        const svgWidth = 600;
        const svgHeight = 200;
        const svg = d3.select('#graph-container')  // Select the graph-container div
            .append('svg')
            .attr('width', svgWidth)
            .attr('height', svgHeight);

        // Create the spline generator
        const line = d3.line()
            .x((d) =&gt; d.x)
            .y((d) =&gt; d.y)
//            .curve(d3.curveMonotoneX);
            .curve(d3.curveCardinal);

        // Draw the spline curve
        svg.append('path')
            .datum(data)
            .attr('d', line)
            .attr('fill', 'none')
            .attr('stroke', 'green')
            .attr('stroke-width', (d) =&gt; d.r);
    &lt;/script&gt;
&lt;/body&gt;
&lt;/html&gt;

