<p>The entire chart component is</p>
<pre><code>import { useEffect, useRef } from &quot;react&quot;;
import isEqual from &quot;lodash/isEqual&quot;;
import * as d3 from &quot;d3&quot;;
import data from &quot;./data&quot;;

// interface SunburstProps {
//   data: {};
//   keyId: string;
//   width: number;
// }

interface TreeNode {
  name: string;
  value?: number;
  children?: TreeNode[];
}

interface Data {
  name: string;
  children: TreeNode[];
}

interface SunburstProps {
  data: Data;
  keyId: string;
  width: number;
}

const partition = (data: any) =&gt; {
  const root = d3
    .hierarchy(data)
    .sum((d) =&gt; d.value)
    .sort((a, b) =&gt; (b.value || 0) - (a.value || 0));

  const partition = d3.partition().size([2 * Math.PI, root.height + 1])(root);

  return partition;
};

function usePrevious(value: any) {
  const ref = useRef();
  useEffect(() =&gt; {
    ref.current = value;
  });
  return ref.current;
}

const Sunburst = (props: SunburstProps) =&gt; {
  const svgRef = useRef&lt;SVGSVGElement&gt;(null);
  const prevProps = usePrevious(props);
  useEffect(() =&gt; {
    if (!isEqual(prevProps, props)) {
      renderSunburst();
    }
    // eslint-disable-next-line
  }, [props]);

  const renderSunburst = () =&gt; {
    const { data, width } = props;
    const color = d3.scaleOrdinal(
      d3.quantize(d3.interpolateRainbow, data.children.length + 1)
    );

    if (data) {
      document.querySelectorAll(&quot;g&quot;).forEach((node) =&gt; {
        node.remove();
      });
      const radius = width / 6;
      const svg = d3
        .select(svgRef.current)
        .attr(&quot;viewBox&quot;, [0, 0, width, width])
        .style(&quot;font&quot;, &quot;10px sans-serif&quot;);

      const g = svg
        .append(&quot;g&quot;)
        .attr(&quot;transform&quot;, `translate(${width / 2},${width / 2})`);

      const root = partition(data);
      root.each((d: any) =&gt; (d.current = d));
      console.log(&quot;Root:&quot;, root);

      const arcVisible = (d: any) =&gt; {
        return d.y1 &lt;= 3 &amp;&amp; d.y0 &gt;= 1 &amp;&amp; d.x1 &gt; d.x0;
      };

      const labelVisible = (d: any) =&gt; {
        return d.y1 &lt;= 3 &amp;&amp; d.y0 &gt;= 1 &amp;&amp; (d.y1 - d.y0) * (d.x1 - d.x0) &gt; 0.03;
      };

      const labelTransform = (d: any) =&gt; {
        const x = (((d.x0 + d.x1) / 2) * 180) / Math.PI;
        const y = ((d.y0 + d.y1) / 2) * radius;
        return `rotate(${x - 90}) translate(${y},0) rotate(${
          x &lt; 180 ? 0 : 180
        })`;
      };

      const clicked = (event: any, p: any) =&gt; {
        parent.datum(p.parent || root);

        g.select(&quot;#mainCircleText&quot;).text(p.data.name);

        root.each(
          (d: any) =&gt;
            (d.target = {
              x0:
                Math.max(0, Math.min(1, (d.x0 - p.x0) / (p.x1 - p.x0))) *
                2 *
                Math.PI,
              x1:
                Math.max(0, Math.min(1, (d.x1 - p.x0) / (p.x1 - p.x0))) *
                2 *
                Math.PI,
              y0: Math.max(0, d.y0 - p.depth),
              y1: Math.max(0, d.y1 - p.depth),
            })
        );

        const t = g.transition().duration(750);

        // Transition the data on all arcs, even the ones that aren’t visible,
        // so that if this transition is interrupted, entering arcs will start
        // the next transition from the desired position.
        path
          .transition(t)
          .tween(&quot;data&quot;, (d) =&gt; {
            const i = d3.interpolate(d.current, d.target);
            return (t) =&gt; (d.current = i(t));
          })
          .filter(function (d) {
            return +this.getAttribute(&quot;fill-opacity&quot;) || arcVisible(d.target);
          })
          .attr(&quot;fill-opacity&quot;, (d) =&gt;
            arcVisible(d.target) ? (d.children ? 0.6 : 0.4) : 0
          )
          .attrTween(&quot;d&quot;, (d) =&gt; () =&gt; {
            return d3
              .arc()
              .startAngle((d) =&gt; d.x0)
              .endAngle((d) =&gt; d.x1)
              .padAngle((d) =&gt; Math.min((d.x1 - d.x0) / 2, 0.005))
              .padRadius(radius * 1.5)
              .innerRadius((d) =&gt; d.y0 * radius)
              .outerRadius((d) =&gt; Math.max(d.y0 * radius, d.y1 * radius - 1))(
              d.current
            );
          });

        label
          .filter(function (d) {
            return +this.getAttribute(&quot;fill-opacity&quot;) || labelVisible(d.target);
          })
          .transition(t)
          .attr(&quot;fill-opacity&quot;, (d: any) =&gt; +labelVisible(d.target))
          .attrTween(&quot;transform&quot;, (d: any) =&gt; () =&gt; labelTransform(d.current));
      };

      const path = g
        .append(&quot;g&quot;)
        .selectAll(&quot;path&quot;)
        .data(root.descendants().slice(1))
        .join(&quot;path&quot;)
        .attr(&quot;fill&quot;, (d: any) =&gt; {
          while (d.depth &gt; 1) d = d.parent;
          return color(d.data.name);
        })
        .attr(&quot;fill-opacity&quot;, (d: any) =&gt;
          arcVisible(d.current) ? (d.children ? 0.6 : 0.4) : 0
        )
        .attr(&quot;d&quot;, (d: any) =&gt; {
          return d3
            .arc()
            .startAngle((d: any) =&gt; {
              return d.x0;
            })
            .endAngle((d: any) =&gt; d.x1)
            .padAngle((d: any) =&gt; Math.min((d.x1 - d.x0) / 2, 0.005))
            .padRadius(radius * 1.5)
            .innerRadius((d: any) =&gt; d.y0 * radius)
            .outerRadius((d: any) =&gt;
              Math.max(d.y0 * radius, d.y1 * radius - 1)
            )(d.current);
        });

      path
        .filter((d: any) =&gt; d.children)
        .style(&quot;cursor&quot;, &quot;pointer&quot;)
        .on(&quot;click&quot;, clicked);

      path.append(&quot;title&quot;).text(
        (d: any) =&gt;
          `${d
            .ancestors()
            .map((d: any) =&gt; d.data.name)
            .reverse()
            .join(&quot;/&quot;)}\n${d3.format(&quot;,d&quot;)(d.value)}`
      );

      const label = g
        .append(&quot;g&quot;)
        .attr(&quot;pointer-events&quot;, &quot;none&quot;)
        .attr(&quot;text-anchor&quot;, &quot;middle&quot;)
        .style(&quot;user-select&quot;, &quot;none&quot;)
        .selectAll(&quot;text&quot;)
        .data(root.descendants().slice(1))
        .join(&quot;text&quot;)
        .attr(&quot;dy&quot;, &quot;0.35em&quot;)
        .attr(&quot;fill-opacity&quot;, (d: any) =&gt; +labelVisible(d.current))
        .attr(&quot;transform&quot;, (d: any) =&gt; labelTransform(d.current))
        .text((d: any) =&gt; d.data.name);

      const parent = g
        .append(&quot;circle&quot;)
        .datum(root)
        .attr(&quot;r&quot;, radius)
        .attr(&quot;fill&quot;, &quot;none&quot;)
        .attr(&quot;pointer-events&quot;, &quot;all&quot;)
        .on(&quot;click&quot;, clicked);

      g.append(&quot;text&quot;)
        .datum(root)
        .attr(&quot;id&quot;, &quot;mainCircleText&quot;)
        .text((d: any) =&gt; d.data.name)
        .attr(&quot;font-size&quot;, 40) //font size
        .attr(&quot;x&quot;, 0)
        .attr(&quot;dy&quot;, &quot;.35em&quot;)
        .attr(&quot;text-anchor&quot;, &quot;middle&quot;)
        .on(&quot;click&quot;, clicked);
    }
  };

  return (
    &lt;div id={props.keyId} className=&quot;text-center&quot;&gt;
      &lt;svg ref={svgRef} id={`${props.keyId}-svg`} /&gt;
    &lt;/div&gt;
  );
};
