            })
        );

        const t = g.transition().duration(750);

        // Transition the data on all arcs, even the ones that aren’t visible,
        // so that if this transition is interrupted, entering arcs will start
        // the next transition from the desired position.
        path
          .transition(t)
          .tween(&quot;data&quot;, (d) =&gt; {
            const i = d3.interpolate(d.current, d.target);
            return (t) =&gt; (d.current = i(t));
          })
          .filter(function (d) {
            return +this.getAttribute(&quot;fill-opacity&quot;) || arcVisible(d.target);
          })
          .attr(&quot;fill-opacity&quot;, (d) =&gt;
            arcVisible(d.target) ? (d.children ? 0.6 : 0.4) : 0
          )
          .attrTween(&quot;d&quot;, (d) =&gt; () =&gt; {
            return d3
              .arc()
              .startAngle((d) =&gt; d.x0)
              .endAngle((d) =&gt; d.x1)
              .padAngle((d) =&gt; Math.min((d.x1 - d.x0) / 2, 0.005))
              .padRadius(radius * 1.5)
              .innerRadius((d) =&gt; d.y0 * radius)
              .outerRadius((d) =&gt; Math.max(d.y0 * radius, d.y1 * radius - 1))(
              d.current
            );
          });

        label
          .filter(function (d) {
            return +this.getAttribute(&quot;fill-opacity&quot;) || labelVisible(d.target);
          })
          .transition(t)
          .attr(&quot;fill-opacity&quot;, (d: any) =&gt; +labelVisible(d.target))
          .attrTween(&quot;transform&quot;, (d: any) =&gt; () =&gt; labelTransform(d.current));
      };
</code></pre>
<p>This time ts error in <code>path..transition(t)</code> as <code>No overload matches this call. Overload 1 of 3, '(name: string, factory: null): Transition&lt;BaseType | SVGPathElement, HierarchyRectangularNode&lt;unknown&gt;, SVGGElement, unknown&gt;', gave the following error.</code>. Any help/suggestion really helpful.</p>

Title: How to fix the &#39;Expected number&#39; error in parallel plot&#39;s path attribute in D3.js with CSV input?.
Body: <p>[d3.js parallel plot] Error:  attribute d: Expected number, &quot;M0,NaNL122.5,NaNL24…&quot;.</p>
<p>I tried to visualize a parallel plot with d3.js, exploiting this example with the iris dataset:</p>
<p><a href="https://d3-graph-gallery.com/graph/parallel_custom.html" rel="nofollow noreferrer">https://d3-graph-gallery.com/graph/parallel_custom.html</a></p>
<p>My csv file is structured as follows:</p>
<pre><code>City,GreenAreaDensity,LowEmission,AutobusStopDensity,CirculatingVehicles,ExposedNoisePollution
Torino,7.46,17.3,24.4,277.0,14.9
Vercelli,1.28,11.2,2.1,77.0,8.8
Novara,1.22,11.9,3.8,246.0,14.7
Biella,33.56,10.1,4.1,189.0,9.3
Cuneo,6.82,10.4,6.3,85.0,3.6
Asti,17.14,11.0,1.9,139.0,36.5
