  // Draw the axis:
  svgParallel.selectAll(&quot;myAxis&quot;)
    // For each dimension of the dataset I add a 'g' element:
    .data(dimensions).enter()
    .append(&quot;g&quot;)
    .attr(&quot;class&quot;, &quot;axis&quot;)
    // I translate this element to its right position on the x axis
    .attr(&quot;transform&quot;, function(d) { return &quot;translate(&quot; + x(d) + &quot;)&quot;; })
    // And I build the axis with the call function
    .each(function(d) { d3.select(this).call(d3.axisLeft().ticks(5).scale(y[d])); })
    // Add axis title
    .append(&quot;text&quot;)
      .style(&quot;text-anchor&quot;, &quot;middle&quot;)
      .attr(&quot;y&quot;, -9)
      .text(function(d) { return d; })
      .style(&quot;fill&quot;, &quot;black&quot;)

})
</code></pre>
<p>In fact the value ycolumn returns NaN, but here if I print d[column] returns the exact value I want on that axis.</p>
<p>This problem is irrelevant if I choose fixed axis for every parameter, but I need different range for the axis:</p>
<pre><code>// For each dimension, I build a linear scale. I store all in a y object
  var y = {}
  var name;
  for (i in dimensions) {
    name = dimensions[i]
    //console.log(name);
    y[name] = d3.scaleLinear()
    // .domain( [0,150] ) // --&gt; Same axis range for each group
      .domain( [d3.extent(data, function(d) { 
