<p>Is this an issue with the key I'm using in data()?
Or is there something more to be done while using ordinal scale to make this code work?</p>
<p>Thanks!</p>

Title: Aligning x position of tspan in IE11 using d3.js.
Body: <p>Really struggling with this. I've tried a lot of hacks to get the labels to render correctly on my force directed d3 graph. Here is a <a href="https://stackblitz.com/edit/github-dzry6q-4cuunq?file=src/app/directed-graph-experiment.service.ts" rel="nofollow noreferrer">stackBlitz</a></p>
<p>You will notice in all other browsers except IE11 renders ok.</p>
<p><a href="https://i.stack.imgur.com/Cl61L.png" rel="nofollow noreferrer"><img src="https://i.stack.imgur.com/Cl61L.png" alt="enter image description here" /></a></p>
<p>In IE:</p>
<p><a href="https://i.stack.imgur.com/D46j7.png" rel="nofollow noreferrer"><img src="https://i.stack.imgur.com/D46j7.png" alt="enter image description here" /></a></p>
<p>As you can see in IE11 the first <code>&lt;tspan&gt;</code> isn't anchored to the middle. I've tried a combination of things with and without the <code>x</code> attribute, <code>dx</code> manipulation. I have lined them up via the <code>dx</code> attribute but as each set of labels have different lengths the math isn't the same for each.</p>
<p>The svg structure is as follows:</p>
<pre><code>&lt;text class=&quot;edgelabel&quot; id=&quot;edgelabel0&quot; font-size=&quot;10&quot; style=&quot;text-anchor: middle;&quot;&gt;
   &lt;textPath xlink:href=&quot;#edgepath0&quot; dominant-baseline=&quot;middle&quot; startOffset=&quot;50%&quot; style=&quot;cursor: pointer;&quot;&gt;
      &lt;tspan class=&quot;edgelabels&quot; dx=&quot;0&quot;&gt;label one&lt;/tspan&gt;
      &lt;tspan class=&quot;edgelabels&quot; x=&quot;0&quot; dy=&quot;22&quot; dx=&quot;0&quot;&gt;label two&lt;/tspan&gt;
      &lt;tspan class=&quot;edgelabels&quot; x=&quot;0&quot; dy=&quot;22&quot; dx=&quot;0&quot;&gt;label three&lt;/tspan&gt;
   &lt;/textPath&gt;
&lt;/text&gt;
</code></pre>
<p>You can see above in this particular implementation I intentionally left out the <code>x</code> attribute for the first tspan.</p>
<p>This is the code that renders the above:</p>
<pre><code>const edgelabels = zoomContainer
  .selectAll('.edgelabel')
  .data(links)
  .enter()
  .append('text')
  .attr('class', 'edgelabel')
  .style('text-anchor', 'middle')
  .attr('id', function (d, i) {
    return 'edgelabel' + i;
  })
  .attr('font-size', 10);

edgelabels
  .append('textPath')
  .attr('xlink:href', function (d, i) {
    return '#edgepath' + i;
  })
  .style('cursor', 'pointer')
  .attr('dominant-baseline', 'middle')
  .attr('startOffset', '50%')
  .selectAll('div.textPath')
  .data(function (d, i) {
    return d.label;
  })
  .enter()
  .append('tspan')
  .attr('class', 'edgelabels')
  .text(function (d, i) {
    return console.log(d), d;
  })
  .attr('x', function (d, i) {
    if (i &gt; 0) {
      return 0;
    }
  })
  .attr('dy', function (d, i) {
    if (i &gt; 0) {
      return 22;
    }
  })
  .attr('dx', 0);
</code></pre>
<p>Has anybody else had this issue, can you see anything wrong? Is there anything else I could try to get a consistent dx attribute for each set of labels? Could I restructure the code to get a better result?</p>
<p>Complete file code:</p>
<pre><code>import { Injectable } from '@angular/core';
import * as d3 from 'd3';

@Injectable({
  providedIn: 'root',
})
export class DirectedGraphExperimentService {
  constructor() {}

  /** A method to bind a zoom behaviour to the svg g element */
  public applyZoomableBehaviour(svgElement, containerElement) {
    let svg, container, zoomed, zoom;

    svg = d3.select(svgElement);

    container = d3.select(containerElement);

    zoomed = () =&gt; {
      const transform = d3.event.transform;
      container.attr(
        'transform',
        'translate(' +
          transform.x +
          ',' +
          transform.y +
          ') scale(' +
          transform.k +
          ')'
      );
    };

    zoom = d3.zoom().scaleExtent([0.5, 1]).on('zoom', zoomed);

    svg.call(zoom).style('cursor', 'move');
  }

  private clearView(svg) {
    return svg.selectAll('*').remove();
  }

  private ticked(link, node, edgepaths, edgelabels) {
    link
      .attr('x1', function (d) {
        return d.source.x;
      })
      .attr('y1', function (d) {
        return d.source.y;
      })
      .attr('x2', function (d) {
        return d.target.x;
      })
      .attr('y2', function (d) {
        return d.target.y;
      });

    node.attr('transform', function (d) {
      return 'translate(' + d.x + ', ' + d.y + ')';
    });

    edgepaths.attr('d', function (d) {
      return (
        'M ' +
        d.source.x +
        ' ' +
        d.source.y +
        ' L ' +
        d.target.x +
        ' ' +
        d.target.y
      );
    });

    edgelabels.attr('transform', function (d) {
      if (d.target.x &lt; d.source.x) {
        let bbox = this.getBBox();

        let rx = bbox.x + bbox.width / 2;
        let ry = bbox.y + bbox.height / 2;
        return 'rotate(180 ' + rx + ' ' + ry + ')';
      } else {
        return 'rotate(0)';
      }
    });
  }

  private dragended(d3, d, simulation) {
    if (!d3.event.active) simulation.alphaTarget(0.3).restart();
    d.fx = d.x;
    d.fy = d.y;
  }

  private initDefinitions(svg) {
    svg
      .append('defs')
      .append('marker')
      .attr('id', 'arrowhead')
      .attr('viewBox', '-0 -5 10 10')
      .attr('refX', 27)
      .attr('refY', 0)
      .attr('orient', 'auto')
      .attr('markerWidth', 8)
      .attr('markerHeight', 8)
      .attr('xoverflow', 'visible')
      .append('svg:path')
      .attr('d', 'M 0,-5 L 10 ,0 L 0,5')
      .attr('fill', '#999')
      .style('stroke', 'none');
    return svg;
  }

  private forceSimulation(d3, { width, height }) {
    return d3
      .forceSimulation()
      .force(
        'link',
        d3
          .forceLink()
          .id(function (d) {
            return d.id;
          })
          .distance(500)
          .strength(2)
      )
      .force('charge', d3.forceManyBody())
      .force('center', d3.forceCenter(width / 2, height / 2));
  }

  private _update(d3, svg, data) {
    let { links, nodes } = data;

    // this.clearView(svg); // removes everything!
    this.initDefinitions(svg);
    const simulation = this.forceSimulation(d3, {
      width: +svg.attr('width'),
      height: +svg.attr('height'),
    });

    const zoomContainer = d3.select('svg g');

    const link = zoomContainer
      .selectAll('.link')
      .data(links)
      .enter()
      .append('line')
      .style('stroke', '#999')
      .style('stroke-opacity', '.6')
      .style('stroke-width', '2px')
      .attr('class', 'link')
      .attr('marker-end', 'url(#arrowhead)');

    link.append('title').text(function (d) {
      return d.label;
    });

    const edgepaths = zoomContainer
      .selectAll('.edgepath')
      .data(links)
      .enter()
      .append('path')
      .attr('class', 'edgepath')
      .attr('fill-opacity', 0)
      .attr('stroke-opacity', 0)
      .attr('id', function (d, i) {
        return 'edgepath' + i;
      });

    const edgelabels = zoomContainer
      .selectAll('.edgelabel')
      .data(links)
      .enter()
      .append('text')
      .attr('class', 'edgelabel')
      .style('text-anchor', 'middle')
      .attr('id', function (d, i) {
        return 'edgelabel' + i;
      })
      .attr('font-size', 10);

    edgelabels
      .append('textPath')
      .attr('xlink:href', function (d, i) {
        return '#edgepath' + i;
      })
      .style('cursor', 'pointer')
      .attr('dominant-baseline', 'middle')
      .attr('startOffset', '50%')

      .selectAll('div.textPath')
      .data(function (d, i) {
        return d.label;
      })
      .enter()
      .append('tspan')
      .attr('class', 'edgelabels')
      .text(function (d, i) {
        return console.log(d), d;
      })
      .attr('x', function (d, i) {
        if (i &gt; 0) {
          return 0;
        }
      })
      .attr('dy', function (d, i) {
        if (i &gt; 0) {
          return 22;
        }
      })
      .attr('dx', 0);
    svg.selectAll('.edgelabel').on('click', function () {
      // arrow function will produce this = undefined
      d3.selectAll('.edgelabel').style('fill', '#999');
      d3.select(this).style('fill', 'blue');
    });

    const node = zoomContainer
      .selectAll('.node')
      .data(nodes)
      .enter()
      .append('g')
      .attr('class', 'node')
      .call(
        d3
          .drag()
          .on('start', (d) =&gt; this.dragended(d3, d, simulation))
          .on('drag', function dragged(d) {
            d.fx = d3.event.x;
            d.fy = d3.event.y;
          })
          .on('end', (d) =&gt; this.dragended(d3, d, simulation))
      );

    node
      .append('circle')
      .style('fill', '#fff')
      .style('cursor', 'pointer')
      .style('fill-opacity', '1')
      .style('stroke-opacity', '0.5')
      .attr('id', (d, i) =&gt; d.id)
      .attr('r', 28);
    svg.selectAll('circle').on('click', function () {
      // arrow function will produce this = undefined
      d3.selectAll('.nodeText').style('fill', 'black');
      d3.select(this.parentNode).selectAll('.nodeText').style('fill', 'blue');
    });

    node
      .append('image')
      .attr('xlink:href', 'https://github.com/favicon.ico')
      .attr('x', -10)
      .attr('y', -40)
      .attr('width', 16)
      .attr('class', 'image')
      .attr('height', 16);
    node
      .append('svg:foreignObject')
      .attr('class', 'delete-icon')
      .html('&lt;div style=&quot;color:green;padding-left: 50px;&quot;&gt;remove&lt;/div&gt;')
      .text('delete');

    const nodeText = node
      .data(nodes)
      .append('text')
      .style('text-anchor', 'middle')
      .style('cursor', 'pointer')
      .attr('dy', -3)
      .attr('y', -25)
      .attr('class', 'nodeText')
      .attr('id', 'nodeText');

    nodeText
      .selectAll('tspan')
      .data((d, i) =&gt; d.label)
      .enter()
      .append('tspan')
      .attr('class', 'nodeTextTspan')
      .text((d) =&gt; d)
      .style('font-size', '12px')
      .attr('x', -10)
      .attr('dx', 10)
      .attr('dy', 22);
    svg.selectAll('.nodeText').on('click', function () {
      d3.selectAll('.nodeText').style('fill', 'black');
      d3.select(this).style('fill', 'blue');
    });

    node.append('title').text(function (d) {
      return d.id;
    });

    simulation.nodes(nodes).on('tick', () =&gt; {
      this.ticked(link, node, edgepaths, edgelabels);
    });

    simulation.force('link').links(links);
  }

  public update(data, element) {
    const svg = d3.select(element);
    return this._update(d3, svg, data);
  }
}
</code></pre>
<p><strong>UPDATE:</strong>
IE11 does not like <code>&lt;tspans&gt;</code> inside of <code>&lt;textPaths&gt;</code> therefore:</p>
<p>I've implemented some of @herrstrietzel solution into my <a href="https://stackblitz.com/edit/github-dzry6q-czqwvh?file=src/app/directed-graph-experiment.service.ts" rel="nofollow noreferrer">new demo</a>. The <code>&lt;tspans&gt;</code> are now directly inside of the <code>&lt;text&gt;</code> elements and each <code>&lt;text&gt;</code> has a dynamic x/y coordinates to lay it on the <code>&lt;path&gt;</code> as we no longer have <code>&lt;textPaths&gt;</code> to do this for us. I've had to do a lot of the rework inside of the <code>ticked()</code> method to gain access to the latest x/y coords as you do not get these outside. One issue remains:</p>
<pre><code>// gets the coordinates of the edgepaths to use for the &lt;text&gt; positioning
edgepaths.each(function (d) {
  source_x = d.source.x;
  source_y = d.source.y;
  target_x = d.target.x;
  target_y = d.target.y;
});

let p1 = { x: source_x, y: source_y };
let p2 = { x: target_x, y: target_y };

// centers the &lt;text&gt; on the path
let textAnchor = this.interpolatedPoint(p1, p2, 0.5);

// Adds the x/y attribute to the &lt;text&gt; elements
edgelabels.attr('x', textAnchor.x).attr('y', textAnchor.y)
</code></pre>
<p>The text elements share the same coordinates and therefore share the same path... not sure why it hasn't adjusted inside the loop. The index of the first label that's already there should get the first index coordinate, but for some reason they are all just getting one set of path coordinates. p1 and p2 always give me the last coordinates in the array of edges.</p>

Title: d3js rectangle strip gauge chart.
Body: <p><a href="https://i.stack.imgur.com/JPPXm.png" rel="nofollow noreferrer"><img src="https://i.stack.imgur.com/JPPXm.png" alt="enter image description here" /></a></p>
<p>How would I convert the current code to something like this pressure chart - where rectangles are arranged in an arc -- and then the best case tick is highlighted to represent the value.</p>
<p>So we would append rectangles and change the angle as we create the skeleton.</p>
<p>I've got this demo that creates a spread of rectangles and changes the angles - but I am not sure how to stabilize this and create the arc from the left side - <a href="https://jsfiddle.net/smo6kqzw/3/" rel="nofollow noreferrer">https://jsfiddle.net/smo6kqzw/3/</a></p>
<pre><code>var svg = d3.select('body').append('svg').attr(&quot;height&quot;, 500).attr(&quot;width&quot;, 500).attr(&quot;class&quot;, &quot;svger&quot;)




var rectbuf = 50;

var padd = 1;


for (let i = 0; i &lt; 20; i++) {

svg.append(&quot;rect&quot;)
  .attr(&quot;width&quot;, 30)
  .attr(&quot;height&quot;, 20)
  .attr(&quot;fill&quot;, &quot;red&quot;)
  .attr(&quot;y&quot;, 20)
  .attr(&quot;x&quot;, rectbuf * 5)
  .attr(&quot;transform&quot;, &quot;rotate(&quot;+((5+padd) *i)+&quot;)&quot;)

}

</code></pre>
<hr />
<pre><code>// create svg element:
var svg = d3.select(&quot;#rect&quot;).append(&quot;svg&quot;).attr(&quot;width&quot;, 800).attr(&quot;height&quot;, 200)

// Add the path using this helper function
svg.append('rect')
  .attr('x', 10)
  .attr('y', 120)
  .attr('width', 600)
  .attr('height', 40)
  .attr('stroke', 'black')
  .attr('fill', '#69a3b2');
</code></pre>
<p>I currently have a dial chart that looks like this
<a href="https://i.stack.imgur.com/e3cIB.png" rel="nofollow noreferrer"><img src="https://i.stack.imgur.com/e3cIB.png" alt="enter image description here" /></a></p>
<pre><code>import React from 'react'
import * as d3 from 'd3'

class GaugeChart extends React.Component {
  constructor(props) {
    super(props)
    this.myRef = React.createRef()
    this.state = {
      data: [],
      theme: this.props.theme
        ? this.props.theme
        : ['#bde0fe', '#2698f9', '#71bcfd', '#f1f8fe'],
    }
  }

  componentDidMount() {
    var $this = this.myRef.current

    d3.select($this).selectAll('svg').remove()

    const value = this.props.value
    const data = [
      {
        label: 'Completed',
        value: value,
      },
      {
        label: 'Remaining',
        value: 100 - value,
      },
    ]

    const width = parseInt(this.props.width, 10),
      height = parseInt(this.props.height, 10),
      radius = parseInt(this.props.r, 10),
      innerradius = parseInt(this.props.ir, 10)

    var color = d3.scaleOrdinal().range(this.state.theme)

    var arc = d3.arc().outerRadius(radius).innerRadius(innerradius)

    data.forEach(function (d) {
      d.total = +d.value
    })

    var pie = d3
      .pie()
      .startAngle(-90 * (Math.PI / 180))
      .endAngle(90 * (Math.PI / 180))
      .padAngle(0.02) // some space between slices
      .sort(null)
      .value(function (d) {
        return d.total
      })

    var svg = d3
      .select($this)
      .append('svg')
      .attr('width', width)
      .attr('height', height + 5)
      .append('g')
      .attr('class', 'piechart')
      .attr('transform', 'translate(' + width / 2 + ',' + height + ')')

    var segments = svg.append('g').attr('class', 'segments')

    var slices = segments
      .selectAll('.arc')
      .data(pie(data))
      .enter()
      .append('g')
      .attr('class', 'arc')

    slices
      .append('path')
      .attr('d', arc)
      .attr('fill', function (d, i) {
        return color(i)
      })
    /*.transition()
          .attrTween('d', function(d) {
            var i = d3.interpolate(d.startAngle + 0.1, d.endAngle);
            return function(t) {
              d.endAngle = i(t);
              return arc(d);
            }
          } )*/

    var arrow = svg.append('g').attr('transform', 'rotate( 0  )')

    arrow
      .append('path')
      .attr('fill', '#ef7e60')
      .attr(
        'd',
        `M -${innerradius - 5},0 -${innerradius - 12},-5 -${
          innerradius - 12
        },5`,
      ) // draw triangle

    var text = svg
      .append('text')
      .attr('text-anchor', 'middle')
      .attr('dy', 0)
      .attr('fill', '#ef7e60')

    function update(data) {
      text.text(`${Math.round(data[0].value)}%`) // set % text

      arrow.transition().attr('transform', `rotate( ${data[0].value * 1.8}  )`) //rotate to desired qantity ( i put to 60% of 180 deg )
    }
    update(data)
  }

  render() {
    return &lt;div ref={this.myRef} className=&quot;GaugeChart&quot; /&gt;
  }
}
export default GaugeChart
</code></pre>
