Title: Set IPv4 netmask programmatically on macOS.
Body: <p>On macOS, I have a <code>utun</code> interface that I've created.  I'd like to, in C, assign it an IPv4 address and netmask.  The former I can do via the <code>SIOCSIFADDR</code> <code>ioctl</code> command.  However, I'm having some trouble with setting the netmask.  On Linux, I'd do</p>
<pre class="lang-c prettyprint-override"><code>struct sockaddr_in addr = {.sin_family = AF_INET};
struct ifreq ifr = {.ifr_name = &quot;utun5&quot;};

inet_pton(AF_INET, &quot;255.255.255.0&quot;, &amp;addr.sin_addr);
memcpy(&amp;ifr.ifr_netmask, &amp;addr, sizeof(addr));
if ( ioctl(sock, SIOCSIFNETMASK, &amp;ifr) == -1 ) {
    // handle the error
}
</code></pre>
<p>My problem is, though sys/sockio.h on my Macbook defines the value <code>SIOCSIFNETMASK</code>, <code>struct ifreq</code> doesn't appear to have any netmask field.  net/if.h shows me</p>
<pre class="lang-c prettyprint-override"><code>struct ifreq {
    char ifr_name[IFNAMESIZ];
    union {
        struct sockaddr ifru_addr;
        struct sockaddr ifru_dstaddr;
        struct sockaddr ifru_broadaddr;
        short ifru_flags;
        ...
</code></pre>
<p>On Linux, it looks like</p>
<pre class="lang-c prettyprint-override"><code>struct ifreq {
    union {
        char ifrn_name[IFNAMSIZ];
    } ifr_ifrn;
    union {
        struct sockaddr ifru_addr;
        struct sockaddr ifru_dstaddr;
        struct sockaddr ifru_broadaddr;
        struct sockaddr ifru_netmask;
        struct sockaddr ifru_hwaddr;
        ...
</code></pre>
<p>Now, it occurred to me that this is just a union and it shouldn't matter that <code>ifru_netmask</code> isn't defined on macOS.  I can just set the netmask value in <code>ifru_addr</code>.  I tried that and, while the <code>SIOCSIFNETMASK</code> command succeeded, <code>ifconfig</code> shows that the device has its default netmask of <code>0xff000000</code>:</p>
<pre><code>utun5: flags=8051&lt;UP,POINTOPOINT,RUNNING,MULTICAST&gt; mtu 1500
    inet 1.2.3.4 --&gt; 0.0.0.0 netmask 0xff000000
</code></pre>
<p>Am I missing something obvious?</p>
<p>Here's my MRE:</p>
<pre class="lang-c prettyprint-override"><code>#include &lt;arpa/inet.h&gt;
#include &lt;net/if.h&gt;
#include &lt;net/if_utun.h&gt;
#include &lt;netinet/in.h&gt;
#include &lt;stdio.h&gt;
#include &lt;sys/ioctl.h&gt;
#include &lt;sys/kern_control.h&gt;
#include &lt;sys/kern_event.h&gt;
#include &lt;sys/socket.h&gt;
#include &lt;unistd.h&gt;

int
tun_device_create(char *if_name)
{
    int fd;
    struct ctl_info info = {0};
    struct sockaddr_ctl addr = {
        .sc_family = AF_SYSTEM, .sc_len = sizeof(struct sockaddr_ctl), .ss_sysaddr = AF_SYS_CONTROL};

    fd = socket(AF_SYSTEM, SOCK_DGRAM, SYSPROTO_CONTROL);
    if (fd &lt; 0) {
        perror(&quot;socket (AF_SYSTEM)&quot;);
        return -1;
    }

    snprintf(info.ctl_name, sizeof(info.ctl_name), &quot;%s&quot;, UTUN_CONTROL_NAME);
    if (ioctl(fd, CTLIOCGINFO, &amp;info) == -1) {
        perror(&quot;ioctl (CTLIOCGINFO)&quot;);
        goto error;
    }
    addr.sc_id = info.ctl_id;

    if (connect(fd, (struct sockaddr *)&amp;addr, sizeof(addr)) != 0) {
        perror(&quot;connect (AF_SYSTEM)&quot;);
        goto error;
    }

    if (getsockopt(fd, SYSPROTO_CONTROL, UTUN_OPT_IFNAME, if_name, &amp;(socklen_t){IFNAMSIZ}) != 0) {
        perror(&quot;getsockopt (SYSPROTO_CONTROL)&quot;);
        goto error;
    }

    return fd;

error:
    close(fd);
    return -1;
}

int
set_addr_and_bring_up(const char *if_name, const char *ipv4_address, const char *ipv4_netmask)
{
    int sock, ret = -1;
    struct ifreq ifr = {0};
    struct sockaddr_in *addr = (struct sockaddr_in *)&amp;ifr.ifr_addr;

    sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock &lt; 0) {
        perror(&quot;socket&quot;);
        return -1;
    }

    snprintf(ifr.ifr_name, sizeof(ifr.ifr_name), &quot;%s&quot;, if_name);

    addr-&gt;sin_family = AF_INET;
    inet_pton(AF_INET, ipv4_address, &amp;addr-&gt;sin_addr);
    if (ioctl(sock, SIOCSIFADDR, &amp;ifr) == -1) {
        perror(&quot;ioctl (SIOCSIFADDR)&quot;);
        goto done;
    }

    inet_pton(AF_INET, ipv4_netmask, &amp;addr-&gt;sin_addr);
    if (ioctl(sock, SIOCSIFNETMASK, &amp;ifr) == -1) {
        perror(&quot;ioctl (SIOCSIFNETMASK)&quot;);
        goto done;
    }

    ifr.ifr_flags = IFF_UP;
    if (ioctl(sock, SIOCSIFFLAGS, &amp;ifr) == -1) {
        perror(&quot;ioctl (SIOCSIFFLAGS)&quot;);
        goto done;
    }

    ret = 0;

done:
    close(sock);
    return ret;
}

int
main()
{
    int fd;
    char if_name[IFNAMSIZ];

    fd = tun_device_create(if_name);
    if (fd &lt; 0) {
        return 1;
    }

    if (set_addr_and_bring_up(if_name, &quot;1.2.3.4&quot;, &quot;255.255.255.0&quot;) != 0) {
        close(fd);
        return 1;
    }

    printf(&quot;Tun device created: %s\n&quot;, if_name);
    pause();

    close(fd);
    return 0;
}
</code></pre>

