uniform float reflectivity;

void main(void){
    vec4 texture_color = texture(model_texture, pass_texture_coords);
    texture_color = vec4(vec3(texture_color.a), 1.0);
    //if(texture_color.a &lt; 0.5){
    //    discard;
    //}

    vec3 unit_normal = normalize(surface_normal);
    vec3 unit_light_vector = normalize(to_light_vector);

    float n_dot1 = dot(unit_normal, unit_light_vector);
    float brightness = max(n_dot1, 0.1);
    vec3 diffuse = brightness * light_color;

    vec3 unit_vector_to_camera = normalize(to_camera_vector);
    vec3 light_direction = -unit_light_vector;
    vec3 reflected_light_direction = reflect(light_direction, unit_normal);

    float specular_factor = dot(reflected_light_direction, unit_vector_to_camera);
    specular_factor = max(specular_factor, 0.0);
    float damped_factor = pow(specular_factor, shine_damper);
    vec3 final_specular = damped_factor * reflectivity * light_color;

    out_color = vec4(diffuse, 1.0) * texture_color + vec4(final_specular, 1.0);
}
</code></pre>
<p>Also before rendering anything, this method gets called:</p>
<pre class="lang-python prettyprint-override"><code>@staticmethod
    def update_display():
        InputController().apply_input()                     # apply inputs every frame

        glEnable(GL_BLEND)
        glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA)   # so that transparent bits of the texture won't get rendered
        glEnable(GL_ALPHA_TEST)

        glEnable(GL_DEPTH_TEST)
        glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT)  # Remove everything from screen (i.e. displays all white)
        glClearColor(0, 0.3, 0, 1)                          # set backdrop color
        glLoadIdentity()                                    # Reset all graphic/shape's position
</code></pre>

Title: normalizing difference of 2 numbers.
Body: <p>I'm making a simple graph drawing shader, but have encounted a problem with making the lines of equal thickness everywhere.</p>
<p>When I dont normalize it it turns out a bit thicker in areas where the diffrence is smaller. When I normalize it it turns out very disturted.</p>
<pre><code>#version 460 core

layout(location = 0) out vec4 color;

in vec4 gl_FragCoord;

uniform vec2 Screen_Size;
uniform vec2 zoom;
uniform vec2 offset;
#define GRAPHCOLOR vec3(0.176, 0.439, 0.701)

float leftside(vec2 pos) {
    return(pos.y);
}
float rightside(vec2 pos) {
    return(pos.x);
}
vec2 cameramat(vec2 pos) {
    return((pos - offset) * zoom);
}
void main() {
    float eps = (50.0*sqrt(zoom.x*zoom.y)) / 2000.0;
    vec2 pos = cameramat(2.0 * (gl_FragCoord.xy / Screen_Size) - vec2(1, 1));
    vec3 _color = vec3(0.9, 0.9, 0.9);
    vec2 sides = (vec2(leftside(pos), rightside(pos)));

    _color = mix(_color, vec3(0.70), step(abs(pos.x - float(int(pos.x))), 0.002 * zoom.x));
    _color = mix(_color, vec3(0.70), step(abs(pos.y - float(int(pos.y))), 0.002 * zoom.y));

    _color = mix(_color, vec3(0.4), step(abs(pos.x), 0.002 * zoom.x));
    _color = mix(_color, vec3(0.4), step(abs(pos.y), 0.0025 * zoom.y));

    _color = mix(_color, mix(_color, GRAPHCOLOR, step(abs((sides.x - sides.y)), eps / 2)),smoothstep(eps, 0, abs((sides.x - sides.y))));

    color = vec4(_color, 0.9);
}
</code></pre>
