<p>login/page.jsx :</p>
<pre><code>&quot;use client&quot;;
import { useState, useEffect } from &quot;react&quot;;
import { useDispatch, useSelector } from &quot;react-redux&quot;;
import { useLoginMutation } from &quot;@/app/GlobalRedux/features/api/usersApiSlice&quot;;
