                    underlineText2 = null,
                    staticText2 = null,
                    clickableText = {

                    }
                )

            }


        }
    }
}
</code></pre>
<p><strong>CheckedBox</strong></p>
<pre><code>@Composable
fun CheckedBox(
    modifier: Modifier,
    underlineText1: String,
    fontSize: TextUnit,
    staticText1: String,
    underlineText2: String?,
    staticText2: String?,
    clickableText: () -&gt; Unit
) {

    val isCheck = remember { mutableStateOf(false) }
    val color = if (isSystemInDarkTheme()) Color(0xFF1A1818) else Color.White

    val annotatedText = buildAnnotatedString {
        withStyle(
            style = SpanStyle(
                textDecoration = TextDecoration.Underline,
                fontSize = fontSize
            )
        ) {
            append(underlineText1)
        }
        withStyle(
            style = SpanStyle(
                fontSize = fontSize
            )
        ) {
            append(staticText1)
        }

        if (underlineText2 != null &amp;&amp; staticText2 != null) {
            withStyle(
                style = SpanStyle(
                    textDecoration = TextDecoration.Underline,
                    fontSize = fontSize
                )
            ) {
                append(underlineText2)
            }
            withStyle(
                style = SpanStyle(
                    fontSize = fontSize
                )
            ) {
                append(staticText2)
            }
        }
    }

    Row(
        modifier = Modifier
            .fillMaxWidth()
            .padding(
                start = 15.dp,
                end = 15.dp,
                top = 10.dp,
                bottom = 10.dp
            )
    ) {

        Card(
            elevation = 0.dp,
            shape = RoundedCornerShape(6.dp),
            border = BorderStroke(2.dp, color = MaterialTheme.colors.grayColor)
        ) {
            Box(
                modifier = Modifier
                    .size(25.dp)
                    .weight(1f)
                    .background(if (isCheck.value) DYTGreenColor else color)
                    .clickable {
                        isCheck.value = !isCheck.value
                    },
                contentAlignment = Alignment.TopStart
            ) {
                if (isCheck.value)
                    Icon(Icons.Default.Check, contentDescription = &quot;&quot;, tint = Color.White)
            }
        }
        Text(
            modifier = Modifier
                .padding(start = 10.dp)
                .clickable {
                    clickableText()
                },
            text = annotatedText
        )
    }

}
</code></pre>
<p>When I do it this way, all text can be clicked normally.</p>
<p>what I want to do :</p>
<p>As you can see, all the text is not underlined, only the contracts are underlined and the user should be able to click on these contracts so that I can contact the service and show the relevant contract on the screen.</p>
