Title: Is this an accurate polyfill of react&#39;s useEffectEvent?.
Body: <p>Is this an accurate polyfill of react's upcoming <code>useEffectEvent</code> hook? Does it present any potential issues?</p>
<p>One part I was not sure about was whether the ref is guaranteed to have been updated prior to the returned function being used in any other effects. I think I'm okay on this front so long as I never use the rather esoteric <code>useInsertionEffect</code> anywhere else in my code, but I would like to confirm that.</p>
<pre class="lang-js prettyprint-override"><code>function useEffectEvent(callback) {
  const fnRef = useRef(null)
  useInsertionEffect(() =&gt; {
    fnRef.current = callback
  }) 
  return (...args) =&gt; {
    return fnRef.current.apply(null, args)
  }
}
</code></pre>

Title: How to use useSearchParams Hook with React Router v6.
Body: <p>I am trying to implement a search parameter functionality to my React image search app. And, I have learned that I need to (can) use the useSearchParams Hook, but I am not sure how to make these changes.</p>
<p>So, basically I want the URL to be something like localhost:3000/<code>input</code>&amp;page=1, meaning that whatever comes after the slash is going to be the <code>input</code> value and key/value pair for page numbers.</p>
<p>As you can see in the app.js, I have these 3 main Routes and the Home Route (renders Main.js) is the one I am mainly working on. Also, Main.js renders Header.js (renders form and others).</p>
<p>I am thinking that I should create a new Route in the app.js but I am not sure what to do.</p>
<pre><code>import './App.css';
import Home from './components/pages/Home';
import Favorites from './components/pages/Favorites';
import Error from './components/pages/Error';
import { BrowserRouter, Routes, Route } from 'react-router-dom'
import { SkeletonTheme } from 'react-loading-skeleton';
import { useDarkMode } from './components/Navbar';


function App() {
  const darkMode = useDarkMode(state =&gt; state.darkMode)
  let style
  if (darkMode === 'light') {
    style = 'wrapper'
  } else {
    style = 'wrapper-dark'
  }

  return (
    &lt;div className={style}&gt;
      &lt;SkeletonTheme baseColor=&quot;#808080&quot; highlightColor=&quot;#b1b1b1&quot;&gt;
        &lt;BrowserRouter&gt;
          &lt;Routes&gt;
            &lt;Route path='/' element={&lt;Home /&gt;} /&gt;
            &lt;Route path='favorites' element={&lt;Favorites /&gt;} /&gt;
            &lt;Route path='*' element={&lt;Error /&gt;} /&gt;
          &lt;/Routes&gt;
        &lt;/BrowserRouter&gt;
      &lt;/SkeletonTheme&gt;
    &lt;/div&gt;
  );
}

export default App;
</code></pre>
<pre><code>import React from 'react'
import Header from './Header'
import Image from './Image'
import { useState, useEffect, useRef } from 'react'
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome'
import { faTriangleExclamation } from '@fortawesome/free-solid-svg-icons'
// import InfiniteScroll from 'react-infinite-scroll-component'


function Main() {
  const [input, setInput] = useState('')
  const [allImages, setAllImages] = useState([])
  // const [totalResults, setTotalResults] = useState(null)
  const [isVisible, setIsVisible] = useState(false)
  const [error, setError] = useState(null)
  const [showError, setShowError] = useState(false)
  const [fadeOut, setFadeOut] = useState(false)
  const [page, setPage] = useState(1)
  const paginationRef = useRef(false)

  // get
  useEffect(() =&gt; {
    if (localStorage.getItem('input')) {
      setInput(JSON.parse(localStorage.getItem('input')))
    }

    if (localStorage.getItem('allImages')) {
      setAllImages(JSON.parse(localStorage.getItem('allImages')))
      // setTotalResults(JSON.parse(localStorage.getItem('totalResults')))
      setIsVisible(JSON.parse(localStorage.getItem('isVisible')))
      setPage(JSON.parse(localStorage.getItem('page')))
      paginationRef.current = true
    }
  }, [])

  // set
  //* dryer?
  useEffect(() =&gt; {
    localStorage.setItem('input', JSON.stringify(input))
  }, [input])

  useEffect(() =&gt; {
    localStorage.setItem('allImages', JSON.stringify(allImages))
  }, [allImages])

  // useEffect(() =&gt; {
  //   localStorage.setItem('totalResults', JSON.stringify(totalResults))
  // }, [totalResults])

  useEffect(() =&gt; {
    localStorage.setItem('isVisible', JSON.stringify(isVisible))
  }, [isVisible])

  function handleChange(event) {
    setInput(event.target.value)
  }

  // display nothing by default
  // display image-list when user press search button

  // function handleSubmit(event) {
  //   event.preventDefault()
  //   // interpolate input state and .env variable to API
  //   fetch(`https://api.unsplash.com/search/photos?query=${input}&amp;client_id=${process.env.REACT_APP_UNSPLASH_API_KEY}`)
  //     .then(res =&gt; res.json())
  //     .then(data =&gt; setAllImages(data.results))
  // }

  async function fetchImages() {
    try {
      const res = await fetch(`https://api.unsplash.com/search/photos?&amp;page=${page}&amp;per_page=30&amp;query=${input}&amp;client_id=${process.env.REACT_APP_UNSPLASH_API_KEY}`)
      const data = await res.json()
      if (data.total !== 0) {
        setAllImages(data.results)
        // setTotalResults(data.total)
        setIsVisible(true)
      }
    } catch(error) {
      setError(error)
    }
  }

  const handleSubmit = async (event) =&gt; {
    event.preventDefault();
    fetchImages()
    setPage(1)
    paginationRef.current = true
  }

  // error
  useEffect(() =&gt; {
    if (error) {
      setShowError(true)
      setTimeout(() =&gt; {
        setFadeOut(true)
        setTimeout(() =&gt; {
          setShowError(false)
        }, 1000)
      }, 5000)
    }
  }, [error])

  // total results
  // let results
  // if (totalResults &gt;= 10000) {
  //   results = 'Total Results: ' + totalResults + '+'
  // } else if (totalResults &gt; 0) {
  //   results = 'Total Results: ' + totalResults
  // } else if (totalResults === 0) {
  //   results = 'Nothing Found'
  // }

  // pagination
  useEffect(() =&gt; {
    if (paginationRef.current) {
      fetchImages()
    }
    localStorage.setItem('page', JSON.stringify(page))
  }, [page])

  function handlePrev() {
    setPage(prevState =&gt; prevState - 1)
    fetchImages()
  }
  function handleNext() {
    setPage(prevState =&gt; prevState + 1)
    fetchImages()
  }


  return (
    &lt;main&gt;
      &lt;Header
        input={input}
        handleChange={handleChange}
        handleSubmit={handleSubmit}
      /&gt;

      {showError &amp;&amp; &lt;div className={`network-error ${fadeOut ? 'fade-out' : ''}`}&gt;
        &lt;i&gt;&lt;FontAwesomeIcon icon={faTriangleExclamation} /&gt;&lt;/i&gt;
        &lt;div className='network-error--message'&gt;
          &lt;h5&gt;Network Error&lt;/h5&gt;
          &lt;p&gt;Please check your Internet connection and try again&lt;/p&gt;
        &lt;/div&gt;
      &lt;/div&gt;}

      {/* &lt;p className='main--results'&gt;{results}&lt;/p&gt; */}
      &lt;div className='main--image-list mt-5 pb-5'&gt;
        {allImages.map(el =&gt; (
          &lt;Image
            key={el.id}
            // do need spread operator below for img's src to work in Image.js
            {...el}
            el={el}
          /&gt;
        ))}
      &lt;/div&gt;

      {isVisible &amp;&amp; &lt;div className='main--pagination'&gt;
        &lt;button disabled={page === 1} onClick={handlePrev}&gt;
          Prev
        &lt;/button&gt;
        &lt;h5 className='main--pagination--h5'&gt;{page}&lt;/h5&gt;
        &lt;button onClick={handleNext}&gt;
          Next
        &lt;/button&gt;
      &lt;/div&gt;}
    &lt;/main&gt;
  )
}

export default Main
</code></pre>
<pre><code>import React from 'react'
import Navbar from './Navbar'


function Header(props) {
  return (
    &lt;div className='header'&gt;
      &lt;Navbar /&gt;
      &lt;h2 className='header--heading text-center text-light'&gt;Find Images&lt;/h2&gt;
      &lt;div className='header--form'&gt;
        &lt;form onSubmit={props.handleSubmit}&gt;
          &lt;input
            className='header--form--input'
            autoComplete='off'
            type='text'
            placeholder='Search'
            onChange={props.handleChange}
            name='input'
            value={props.input}
          /&gt;
        &lt;/form&gt;
      &lt;/div&gt;
    &lt;/div&gt;
  )
}

export default Header
</code></pre>

Title: React Router Dom - v6 - useBlocker.
Body: <p>As <a href="https://github.com/remix-run/react-router/issues/8139" rel="noreferrer">https://github.com/remix-run/react-router/issues/8139</a> is finished and we got <code>useBlocker</code> in v6, did anyone got it to work?</p>
<p>This is what I got so far and pretty much I'm stuck with error I quite don't understand</p>
<p>in App.js I have my <code>BrowserRouter</code> and everything is wrapped inside</p>
<p>Also I used example from implementer's gists (I copy pasted)</p>
<pre><code>import * as React from &quot;react&quot;;
import { useBeforeUnload, unstable_useBlocker as useBlocker } from &quot;react-router-dom&quot;;

function usePrompt(message, { beforeUnload } = {}) {

let blocker = useBlocker(
  React.useCallback(
     () =&gt; (typeof message === &quot;string&quot; ? !window.confirm(message) : false),
  [message]
  )
);
let prevState = React.useRef(blocker.state);

React.useEffect(() =&gt; {
    if (blocker.state === &quot;blocked&quot;) {
    blocker.reset();
  }
  prevState.current = blocker.state;
}, [blocker]);

useBeforeUnload(
     React.useCallback(
       (event) =&gt; {
         if (beforeUnload &amp;&amp; typeof message === &quot;string&quot;) {
          event.preventDefault();
          event.returnValue = message;
         }
      },
      [message, beforeUnload]
    ),
  { capture: true }
 );
}

function Prompt({ when, message, ...props }) {
    usePrompt(when ? message : false, props);
    return null;
}
</code></pre>
<p>And then within my component I called <code>Prompt</code> like this</p>
<pre><code>const MyComponent = (props) =&gt; {
    const [showPrompt, setShowPrompt] = useState(false)

    ...

    return (
        ...
        &lt;Prompt when={showPrompt} 
                message=&quot;Unsaved changes detected, continue?&quot; 
                beforeUnload={true} 
        /&gt;
    )
}
</code></pre>
<p>And on page load of <code>MyComponent</code> I keep getting error</p>
<pre><code>Error: useBlocker must be used within a data router.  See 
    https://reactrouter.com/routers/picking-a-router.
     at invariant (history.ts:308:1)
     at useDataRouterContext (hooks.tsx:523:1)
     at useBlocker (hooks.tsx:723:1)
     at usePrompt (routerCustomPrompt.js:8:1)
     at Prompt (routerCustomPrompt.js:37:1)
</code></pre>
<p>Did anyone got <code>useBlocker</code> in new version to work?</p>

