Title: How can I create a Bootstrap carousel with autoplay for images and videos?.
Body: <p>I'm trying to create a carousel with autoplay with images and videos so I have the following code:</p>
<p>I'm trying to create an autoplay carousel with images and videos with bootstrap 4, jquery and html so I have the following code:</p>
<p>In jquery I try to verify the element that is displayed and the following according to its type update the interval of the slide, apparently it does not find the selector but when using a different order it reproduces the video but the slide no longer changes.</p>
<p>The idea is to have 5 slides when the image has an interval of 5 seconds and then when it is video it has the interval corresponding to the duration of the video and that it is played.</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>$(document).ready(function() {

            let allVids  = $("#myCarousel").find('.carousel-item.video');
            const carousel = $("#myCarousel");

            function setCarouselInterval(interval) {
                carousel.carousel('dispose');
                carousel.carousel({
                    interval: interval
                });
                carousel.carousel('cycle');
            }

            setInterval(function() {
                $('.carousel').carousel('next');
            }, 50000);

            allVids.each(function(index, el) {
            if (index !== 0) {
                if ($(this).is('video')) {
                    $(this).find('video')[0].pause();
                }
            }
            });

            $("#myCarousel").on('slide.bs.carousel', function(ev) {
                // debugger;
                let slides       = $(this).find('.carousel-item');
                let currentSlide = slides[ev.from];
                let nextSlide    = slides[ev.to];

                let currentElement = currentSlide.querySelector('img, video');
                let nextElement    = nextSlide.querySelector('img, video');

                if (currentElement &amp;&amp; currentElement.tagName === 'VIDEO') {
                    let currentVideo = currentElement;
                    currentVideo.pause();
                    currentVideo.currentTime = 0;
                }

                if (nextElement.tagName === 'VIDEO') {
                    // debugger;
                    let nextVideo = nextElement;
                    let time      = nextVideo.duration;
                    let interval  = time * 1000;
                    nextVideo.play();
                    setCarouselInterval(interval);

                } else {

                    let intervalAux = 5000;
                    setCarouselInterval(intervalAux);
                }

            });
        });</code></pre>
