Title: Need help in centering the data labels on the top of slice of pie chart in highchart.
Body: <p>need help in centering the pie data labels on top of slices.
I'm using React Highchart.</p>
<p>Currently the Chart looks like this.</p>
<p><a href="https://i.stack.imgur.com/dqXGO.png" rel="nofollow noreferrer"><img src="https://i.stack.imgur.com/dqXGO.png" alt="Current PIE chart" /></a></p>
<p>Sample Code for label centering:</p>
<pre class="lang-js prettyprint-override"><code>function redrawDatalabels() {
  var chart = this,
    cX = chart.series[0].center[0],
    cY = chart.series[0].center[1],
    shapeArgs,
    ang,
    posX,
    posY,
    bBox;

  Highchart.each(chart.series[0].data, function (point, i) {
    if (point.dataLabel) {
      bBox = point.dataLabel.getBBox();
      shapeArgs = point.shapeArgs;
      ang = (shapeArgs.end - shapeArgs.start) / 2 + shapeArgs.start;
      const labelPos = point.labelPosition.alignment === &quot;right&quot; ? 1 : -1;
      posX = cX + (shapeArgs.r / 2) * Math.cos(ang) + (labelPos * bBox.width) / 2;
      posY = cY + (shapeArgs.r / 2) * Math.sin(ang) - bBox.height / 2;
      point.dataLabel._pos.x = posX;
      point.dataLabel._pos.y = posY;
    }
  });
  chart.series[0].placeDataLabels();
}
</code></pre>
<p>CodeSandBox: <a href="https://codesandbox.io/s/hc-animate-9j72hn?file=/src/App.js" rel="nofollow noreferrer">https://codesandbox.io/s/hc-animate-9j72hn?file=/src/App.js</a></p>

