         }
       })
</code></pre>
<p>client side:</p>
<pre><code>document.addEventListener('DOMContentLoaded', () =&gt; {
  const createAccountBtn = document.getElementById('createAccountBtn');
  const loginBtn = document.getElementById('loginBtn');
  const cargoInput = document.getElementById('cargoInput');
  const nucleoSelection = document.getElementById('nucleoSelection');

  if (createAccountBtn) {
    createAccountBtn.addEventListener('click', handleCreateAccount);
  }

  if (loginBtn) {
    loginBtn.addEventListener('click', handleLogin);
  }

  cargoInput.addEventListener('change', () =&gt; {
    const selectedCargo = cargoInput.value;
    // Check if &quot;Líder de Núcleo&quot; or &quot;Membro&quot; is selected, and show or hide the additional selection box accordingly
    if (selectedCargo === 'lider de nucleo' || selectedCargo === 'membro') {
      nucleoSelection.style.display = 'block';
    } else {
      nucleoSelection.style.display = 'none';
    }
  });
});

async function handleCreateAccount(event) {
  event.preventDefault();

  const nameInput = document.getElementById('nameInput').value;
  const genderInput = document.getElementById('genderInput').value;
  const cargoInput = document.getElementById('cargoInput').value;
  const nucleoInput = document.getElementById('nucleoInput').value; // Get the selected nucleo value if applicable
  const emailInput = document.getElementById('emailInput').value;
  const passwordInput = document.getElementById('passwordInput').value;
  const genderValue = document.getElementById('genderValue');
  genderValue.value = genderInput;

  try {
    const response = await fetch('http://localhost:3000/register', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        username: nameInput,
        gender: genderInput,
        cargo: cargoInput,
        nucleo: nucleoInput, // Pass the selected nucleo value if applicable
        email: emailInput,
        password: passwordInput,
      }),
    });

    const data = await response.json();
    if (response.ok) {
      alert(data.message);
      redirectToFeed();
    } else {
      alert(data.error);
    }
  } catch (error) {
    console.error('Erro durante o registro:', error);
    alert('Falha no registro.');
  }
}

async function handleLogin() {
  const emailInput = document.getElementById('emaillogin').value;
  const passwordInput = document.getElementById('senhalogin').value;

  try {
    const response = await fetch('http://localhost:3000/login', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        email: emailInput,
        password: passwordInput,
      }),
    });

    const data = await response.json();
    if (response.ok) {
      // Store the JWT token received from the server securely (e.g., in local storage)
      localStorage.setItem('jwtToken', data.token);
      alert(data.message);
      setTimeout(() =&gt; {
        // Clear the input fields after a second
        document.getElementById('emaillogin').value = '';
        document.getElementById('senhalogin').value = '';
      }, 1000);
      redirectToFeed();
    } else {
      alert(data.error);
    }
  } catch (error) {
    console.error('Erro durante o login:', error);
    alert('Falha no login.');
  }
}

function redirectToFeed() {
  window.location.href = '/feedlogado.html';
}

</code></pre>
<p>server side:</p>
<pre><code>const express = require('express');
const { PrismaClient } = require('@prisma/client');
const bcrypt = require('bcrypt');
const jwt = require('jsonwebtoken');
const app = express();
const cors = require('cors');
const prisma = new PrismaClient();
app.use(cors());
app.use(express.json());

const jwtSecret = 'yourSecretKey';
const user = await db.collection('users').where('id', userId).get();
function generateToken(user) {
  return jwt.sign({ userId: user.id }, jwtSecret, { expiresIn: '8h' }); // Token expires in 8 hours
}

app.post('/login', async (req, res) =&gt; {
  const { email, password } = req.body;

  try {
    const user = await prisma.user.findUnique({
      where: { email: email },
      select: { id: true, email: true, password: true },
    });

    if (!user) {
      return res.status(401).json({ error: 'Credenciais inválidas' });
    }
    const passwordMatch = await bcrypt.compare(password, user.password);

    if (passwordMatch) {
      const token = generateToken(user);
      return res.status(200).json({ message: 'Login realizado com sucesso!', token, id: user.id, email: user.email });
    } else {
      return res.status(401).json({ error: 'Credenciais inválidas' });
    }
  } catch (error) {
    console.error('Erro durante o login:', error);
    res.status(500).json({ error: 'Login falhou' });
  }
});

app.post('/register', async (req, res) =&gt; {
  const { username, gender, cargo, nucleo, email, password } = req.body;

  try {
    const existingUser = await prisma.user.findUnique({
      where: { email },
    });

    if (existingUser) {
      return res.status(409).json({ error: 'Email already exists' });
    }
    const hashedPassword = await bcrypt.hash(password, 10);

    const existingCargo = await prisma.cargo.findUnique({ where: { name: cargo } });

    if (!existingCargo) {
      return res.status(404).json({ error: 'Cargo not found' });
    }

    let nucleoConnect;
    if (nucleo &amp;&amp; !isNaN(parseInt(nucleo))) {
      const existingNucleo = await prisma.nucleo.findUnique({ where: { id: parseInt(nucleo) } });
      if (!existingNucleo) {
        return res.status(404).json({ error: 'Nucleo not found' });
      }
      nucleoConnect = { connect: { id: existingNucleo.id } };
    }

    const newUser = await prisma.user.create({
      data: {
        username,
        gender,
        cargo: {
          connect: { id: existingCargo.id },
        },
        nucleo: nucleoConnect,
        email,
        password: hashedPassword,
      },
    });

    res.status(200).json({ message: 'Conta criada com sucesso!' });
  } catch (error) {
    console.error('Erro:', error);
    res.status(500).json({ error: 'Registro falhou.' });
  }
});


const port = process.env.PORT || 3000;

const server = app.listen(port, () =&gt; {
  console.log(`Servidor iniciado em http://localhost:${port}`);
});

process.on('SIGINT', () =&gt; {
  console.log('Received SIGINT. Closing server...');
  server.close(() =&gt; {
    console.log('Server closed.');
    prisma.$disconnect().then(() =&gt; {
      console.log('Prisma client disconnected.');
      process.exit(0);
    });
  });
});

prisma.$on('error', (err) =&gt; {
  console.error('Prisma client error:', err);
});

</code></pre>
<p>also, if it helps, this is my prisma model:</p>
<pre><code>generator client {
  provider = &quot;prisma-client-js&quot;
}

datasource db {
  provider = &quot;sqlite&quot;
  url      = &quot;file:./database.db&quot;
}

model User {
  id         Int   @id @default(autoincrement())
  gender     String   
  password   String   
  username   String?   
  email      String @unique
  refreshTokens RefreshToken[]
  admin      Boolean  @default(false)
  created_at DateTime @default(now())

  cargo      Cargo?   @relation(fields: [cargoId], references: [id])
  cargoId    Int?

  posts      Post[]
  comments   Comment[]
}

model Cargo {
  id         Int      @id @default(autoincrement())
  nome       String   
  nucleo     String   
  created_at DateTime @default(now())

  users      User[]
}

model Post {
  id                            Int @id @default(autoincrement())
  content                       String
  updated_at                    DateTime @updatedAt
  created_at                    DateTime @default(now())

  comment Comment[]

  userId Int
  user User @relation(fields: [userId], references: [id])
}

model Comment {

  id Int @id @default(autoincrement()) 
  content String

  postId Int
  post Post @relation(fields: [postId], references: [id])

  userId Int
  user User @relation(fields: [userId], references: [id])

} 
model RefreshToken {
  id          Int   @id @default(autoincrement())
  hashedToken String
  userId      Int      
  User        User     @relation(fields: [userId], references: [id], onDelete: Cascade)
  revoked     Boolean  @default(false)
  createdAt   DateTime @default(now())
  updatedAt   DateTime @updatedAt
}
</code></pre>
<p>Ive already tried checking if its collecting it right and all but I cant find whats wrong (still learning)</p>

Title: How to compile Dart server into Javascript and run with NodeJs?.
Body: <p>My goal is to run my Dart server in Firebase Cloud functions, but it does not support Dart Runtime, so I thought that maybe it is possible to compile it to JS and run it there with NodeJS. I did the test on my local machine with this simple code:</p>
<pre><code>import 'package:shelf/shelf.dart';
import 'package:shelf/shelf_io.dart' as io;
import 'package:shelf_router/shelf_router.dart';

Future&lt;void&gt; main() async {
  print(&quot;Hello world once&quot;);
  var app = Router();

  app.get('/hello', (Request request) {
    return Response.ok('hello-world');
  });

  app.get('/user/&lt;user&gt;', (Request request, String user) {
    return Response.ok('hello $user');
  });

  var server = await io.serve(app, 'localhost', 8080);
  print(&quot;Hello worl 2&quot;);
}
</code></pre>
<p>If I run: <code>dart main.dart</code> it prints</p>
<pre><code>Hello world once
Hello worl 2
</code></pre>
<p>And if I got to <code>http://localhost:8080/hello</code>, I get <code>hello-world</code>.</p>
<p>However, if I run: <code> dart compile js main.dart</code> and run <code>node out.js</code>, it only prints</p>
<pre><code>Hello world once
</code></pre>
<p>And the server is not responding.</p>
<p>I read some people say it is not possible to use <code>dart.io</code> in compiled to JS code, but I am not sure about the veracity of such and if even if it's true, why ? Is there a workaround ? My frontend is in <code>Flutter</code> and I don't wanna write my backend code with a different language.</p>

Title: Swift server-side vapor: How to download file to disk?.
Body: <p>I want to download multiple files in swift vapor. Some files have to be downloaded to disk and some should be just in-memory. For some i need to specify http-headers.</p>
<p>I know of the <code>ClientRequest</code> which can be used to get the result as an in-memory string. With it i can also specify the headers. Like this:</p>
<pre class="lang-swift prettyprint-override"><code>let request = ClientRequest(
    method: .GET,
    url: URI(string: url),
    headers: headers
)
let response: ClientResponse = try app.client.send(request).wait()

guard
    var body = response.body,
    let rawBytes = body.readData(length: body.readableBytes),
    let decoded = String(data: rawBytes, encoding: String.Encoding.utf8)
else {
    return nil
}
</code></pre>
<p>Is there also a way of downloading a file directly to disk? Or piping it to disk?
If the file is too large i don't want to have it in-memory all at once. Especially when it's not necessary.</p>
<p>I'm aware that I can call <code>curl</code>/<code>wget</code> from swift, but that is not what i'm after..</p>

Title: How to configure vite.config to proxy a server at a different port.
Body: <p>I am trying to fetch data from a Flask server (localhost:5000) with my Vite app (localhost:5173). All of my API endpoints work in Postman. I followed instructions from Vite's documentation, however, I must be missing something, because the fetch still sends requests to localhost:5173.</p>
<p>Here is vite.config.ts:</p>
<pre><code>export default defineConfig({
  plugins: [react()],
  server: {
    proxy: {
      &quot;/api&quot;: {
        target: &quot;http://127.0.0.1:5000&quot;,
        changeOrigin: true,
        secure: false,
        ws: true,
        configure: (proxy, _options) =&gt; {
          proxy.on('error', (err, _req, _res) =&gt; {
            console.log('proxy error', err);
          });
          proxy.on('proxyReq', (proxyReq, req, _res) =&gt; {
            console.log('Sending Request to the Target:', req.method, req.url);
          });
          proxy.on('proxyRes', (proxyRes, req, _res) =&gt; {
            console.log('Received Response from the Target:', proxyRes.statusCode, req.url);
          });
        }
      },
    }
  }
})
</code></pre>
<p>These are the client-side console outputs from the error-handling in vite.config:</p>
<pre><code>Sending Request to the Target: GET /api/home/
Received Response from the Target: 200 /api/home/
</code></pre>
<p>This is my fetch:</p>
<pre><code>fetch('/api/home')
      .then((res) =&gt; console.log(res))
    // .then((res) =&gt; res.json())
    // .then((data: object[]) =&gt; {
    //   setPostData(data)
    // })
</code></pre>
<p>This is the output of the above console.log (confused why the fetch still hits the localhost:5173 endpoint):</p>
<pre><code>type: 'basic', 
url: 'http://localhost:5173/api/home/', 
redirected: true, 
status: 200,  ok: true, …
</code></pre>
<p>This is some data, as it responds in Postman:</p>
<pre><code>[{
        &quot;comments&quot;: [],
        &quot;created_at&quot;: &quot;Thu, 23 Mar 2023 08:30:17 GMT&quot;,
        &quot;likes&quot;: 2,
        &quot;text&quot;: &quot;Lorem ipsum&quot;,
        &quot;title&quot;: &quot;Morbi non quam nec dui luctus rutrum&quot;,
        &quot;updated_at&quot;: &quot;Thu, 23 Mar 2023 08:30:17 GMT&quot;,
        &quot;user&quot;: &quot;alesmonde0&quot;,
        &quot;user_id&quot;: 1
    }]
</code></pre>
<p>I am fairly new to Flask, new to TypeScript, but have experience with React/Vite using Express and Node instead.
Am I missing something simple?</p>
<p>I have tried:</p>
<ul>
<li>Following the documentation on Vite</li>
<li>Changing the server.proxy path in vite.config to '/' - this serves only my Flask app, with no Vite</li>
<li>Adding <code>secure: false</code> to vite.config - a solution I found on a similar question - this didn't work</li>
<li>Adding <code>ws: true</code> to vite.config - another solution I found here - didn't work</li>
<li>Changing server.proxy url from '/api' to '/' - this served my Flask app and I was unable to see my Vite front-end</li>
<li>Adding Access-Control-Allow-Origin headers to my fetch - this did nothing</li>
<li>Adding server.proxy.configure options to attempt to find an error - this confusingly responds with 200 - I expected a 400</li>
</ul>

