<pre><code>import React, { useState, useEffect } from &quot;react&quot;;
import { useSetUserMutation } from &quot;../../../store/store&quot;;
import { useSelector } from &quot;react-redux&quot;;

function Row({ row, columnaEstado, columnaVer, handleSelect, selected }) {
  const { session_id: token } = useSelector(({ session }) =&gt; session);
  // const [rowState, setRowState] = useState(row.ESTADO);
  const [setUser, result] = useSetUserMutation();

  if (row.RNUM == 2) console.log(row.ESTADO);
  const handleDoubleClick = (e) =&gt; {
    if (e.detail === 2) {
      setUser({ token, row });
      console.log(result);
    }
  };
  const { formatter: estadoFormatter } =
    columnaEstado;
  const { formatter: accionFormatter } = columnaVer;
  const selectedStyle = (selected) =&gt; {
    if (selected) {
      return { backgroundColor: &quot;#eeeeee&quot; };
    } else {
      return {};
    }
  };
  return (
    &lt;tr
      key={row.COD_USUARIO}
      onClick={() =&gt; handleSelect(row)}
      style={selectedStyle(selected)}
    &gt;
      &lt;td&gt;{row.RNUM}&lt;/td&gt;
      &lt;td&gt;{row.ID_USUARIO}&lt;/td&gt;
      &lt;td onClick={handleDoubleClick}&gt;{estadoFormatter(row.ESTADO)}&lt;/td&gt;
      &lt;td&gt;{accionFormatter([], row)}&lt;/td&gt;
    &lt;/tr&gt;
  );
}

export default Row;
</code></pre>

Title: What is the best way to save Formik values in Redux Toolkit so that I can persist them with redux-persist?.
Body: <p>I have a multi step form made in React with formik and I am also using Redux Toolkit with redux-persist. I am able to save the form steps in the Redux state and the user remains in the current step even if they close/open the window again. But how can I also store the formik values he has entered in the Redux state so that the values persist as well?</p>
<p>This is the code of my form:</p>
<pre><code>export default function UserDetailsForm() {
  const formik = useFormik({
    initialValues: FormInitialValues,
    validationSchema: FORM_MODULES[module]?.schema[formStep],
    onSubmit: (values, actions) =&gt; {
      sendFormRequest(values, actions);
    },
  });

  return (
        &lt;form className='form-container' onSubmit={formik.handleSubmit}&gt;


