            setModule={handleSetModule}
            setFormStep={handleSetFormStep}
          /&gt;}

          {/* 4. Product Info */}

          {module === 3 &amp;&amp;
          &lt;ProductInfo
            formik={formik}
            formStep={formStep}
            setModule={handleSetModule}
