            ["x", 0], 
            ["́x́", 1], 
            ["̂x̂", 2], 
            ["ẍ", 2], 
            ["̌x̌", 2], 
            ["ẋ", 1], 
            ["̧x̧", 1], //
            ["̱x̱", 1], 
            ["̣x̣", 1], 
            ["ᶍ", 2] 
        ],
     /*...*/
}

$("button").on("click", function(){
  text= $(".text").text()
  for(e in text){
    console.log(text[e])
  }
})</code></pre>
<pre class="snippet-code-html lang-html prettyprint-override"><code>&lt;script src="https://cdnjs.cloudflare.com/ajax/libs/jquery/3.3.1/jquery.min.js"&gt;&lt;/script&gt;

&lt;h2 class= "text" contenteditable= "true"&gt;Lorem Ipx́um ẋ&lt;/h2&gt;
&lt;button&gt;Log each character&lt;/button&gt;</code></pre>
</div>
