Title: writing to and reading from a file in c++.
Body: <p>I was trying to code a list of students with some data on them into binary and decoding it to check if everything was coded fine, using as few bits as possible (e.g. 8 faculties → 3 bits). Coding into binary seems to work fine, but decoding it back doesn't.
I have 3 files in total:
original data - a list of data on students
binary code - consist of one line of coded information with no spaces
output check file</p>
<p>I tried using file pointers to head back to the beginning of the second file to read it propperly using seekp(), closing and opening file anew but id didn't seem to work for me.
Code I used:</p>
<pre><code>#include &lt;iostream&gt;
#include &lt;fstream&gt;
#include &lt;cctype&gt;
#include &lt;algorithm&gt;
#include &lt;sstream&gt;
#include &lt;string&gt;
#include &lt;cmath&gt;

struct Student {
    int faculty;//3bit
    int course;//3bit
    int group;//7
    std::string name;
};

void StringToUpperCase(std::string&amp; str, int strlen) {
    for (int i = 0; i &lt; strlen; i++) {
        str[i] = toupper(str[i]);
    }
}

void code(unsigned char* c, int size, std::fstream &amp; file){
    unsigned char uc;
    unsigned char m;
    uc = *c;
    for (int i = size - 1; i &gt; -1; i--) {
        m = 1 &lt;&lt; i;
        file &lt;&lt; (((uc &amp; m) != 0) ? 1 : 0);
    }
}

void decode(int size, std::fstream&amp; input, std::ofstream&amp; output) {
    int result = -1;
    int digit;
    for (int i = size - 1; i &gt; -1; i--) {
        input &gt;&gt; digit;
        if (digit == 1) {
            result += pow(2, i);
        }
    }
    result += 1;
    output &lt;&lt; result &lt;&lt; &quot; &quot;;
}


void codeChar(unsigned char* c, std::fstream&amp; file) {
    unsigned char uc;
    unsigned char m;
    if ((unsigned char)c == ' ') {
        uc = 27;
    }else{ uc = *c - 'A' + 1; }

    for (int i = 4; i &gt; -1; i--) {
        m = 1 &lt;&lt; i;
        file &lt;&lt; (((uc &amp; m) != 0) ? 1 : 0);
    }
}

void decodeChar(std::fstream&amp; input, std::ofstream&amp; output) {
    char symbol;
    int code = 0;
    for (int i = 4; i &gt; -1; i--) {
        input &gt;&gt; symbol;
        if (symbol == '0') { code += pow(2, i); }
    }
    if (code == 27) {
        output &lt;&lt; &quot; &quot;;
    }
    else { output &lt;&lt; char(code + 'A' - 1); }
}

int main()
{
    std::ifstream file(&quot;D:\\cpp\\test.txt&quot;);
    if (!file.is_open()) {
        std::cout &lt;&lt; &quot;no file found&quot;;
        return 1;
    }
    int students_count;
    file &gt;&gt; students_count;
    int total_bytes = 0;

    Student line;

    std::fstream bitwise(&quot;D:\\cpp\\mid_product.txt&quot;, std::ios::app);
    std::ofstream result(&quot;D:\\cpp\\result.txt&quot;, std::ios::app);



    for (int i = 0; i &lt; students_count; i++) {

        file &gt;&gt; line.faculty &gt;&gt; line.course &gt;&gt; line.group;
        line.faculty -= 1;
        std::getline(file, line.name, '\n');

        line.name = line.name.substr(1);

        int name_length = line.name.length();
        total_bytes += 13 + name_length*5;

        StringToUpperCase(line.name, name_length);

        code((unsigned char *)&amp;line.faculty, 3, bitwise);
        code((unsigned char *)&amp;line.course, 3, bitwise);
        code((unsigned char *)&amp;line.group, 7, bitwise);
        for (int k = 0; k &lt; name_length; k++) {
            codeChar((unsigned char*)&amp;line.name[k], bitwise);
        }


        decode(3, bitwise, result);
        decode(3, bitwise, result);
        decode(7, bitwise, result);
        for (int j = 0; j &lt; name_length; j++) {
            decodeChar(bitwise, result);
        }
        result &lt;&lt; &quot;\n&quot;;

    }

    result.close();
    file.close();


    total_bytes = (total_bytes / 8 &gt;=1) ? (total_bytes / 8 + 1) : total_bytes;

}

</code></pre>
<p>some lines are excluded for the sake of space economy, and some may represent a complete gibberish as I was trying to to fix it many times.</p>
<p>putting in a file with one line:
<code>3 6 19 John Doe</code>
I am expecting to get a result in a third file:
<code>3 6 9 JOHN DOE</code>
but actual output is
<code>0 0 0 ________</code>
please help me make out what I am doing wrong.</p>

Title: Is there a way to pass a string variable to remove() in c.
Body: <p>Okay, so this is the function I'm using <code>remove()</code>:</p>
<pre><code>int fmove(const char * filepth, const char * destpth)
{
    FILE * fp;
    fp = fopen(filepth, &quot;r+&quot;);

    FILE * fpdest;
    fpdest = fopen(destpth, &quot;w&quot;);

    if ((fp != NULL) &amp;&amp; (fpdest != NULL))
    {
        char fpdata[999];
        fgets(fpdata, 999, fp);
        fputs(fpdata, fpdest);

        remove(filepth);
    } else
    {
        prtmessage(&quot;ERROR&quot;, &quot;Cannot move file!&quot;);
        return 1;
    }

    return 0;
}
</code></pre>
<p>but the <code>remove()</code> returns -1. I know that arrays return their pointers (am I telling it right?), but is there a way to pass the string in the <code>filepath</code> to <code>remove()</code>?</p>

Title: Stream the output of a void function using printf().
Body: <p>I want to store the output of a function (<code>matrix_output_printf()</code>) printing the following output (a matrix):</p>
<pre><code>0   1   2   
1   2   3   
2   3   4   
</code></pre>
<p>I would like to save this output in a text file.</p>
<p>In a first attempt, I modified the original in <code>matrix_output_fprintf()</code> so that it stores the output continuously using <code>fprintf()</code>. I indeed stores the output but the code of <code>matrix_output_printf()</code> has been changed</p>
<p>However, I would like not to modify <code>matrix_output_printf()</code> as, let's say, it is part of a package and want to test it without modifiying it.
Is there a way to store (using C and not bash) the output of <code>matrix_output_printf()</code> from outside the function (or without using <code>fprintf()</code>?</p>
<p>The content of <strong>file.txt</strong> is the following:</p>
<pre><code>0   1   2   
1   2   3   
2   3   4   
</code></pre>
<p>Here is the code:</p>
<pre><code>/* main.c */
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;

void matrix_output();

void matrix_output_printf(){
  for (int i = 0; i &lt; 3; i++){
    for (int j = 0; j &lt; 3; j++){
      printf(&quot;%d\t&quot;, i+j);
    }
    printf(&quot;\n&quot;);
  }
}

void matrix_output_fprintf(){
  FILE * fp;
  fp = fopen(&quot;file.txt&quot;, &quot;w&quot;);
  fclose(fp);
  fp = fopen(&quot;file.txt&quot;, &quot;ab&quot;);
  for (int i = 0; i &lt; 3; i++){
    for (int j = 0; j &lt; 3; j++){
      fprintf(fp, &quot;%d\t&quot;, i+j);
    }
    fprintf(fp, &quot;\n&quot;);
  }
  fclose(fp);
}


int main ()
{
  matrix_output_printf();
  matrix_output_fprintf();
  return 0;
}
</code></pre>

Title: How could the function defined in the interface with the body be redefined in the inherited function without overriding?.
Body: <p>Can somebody explain how same function on same class behaved different?</p>
<pre><code>using System;

