Title: When adding something to linked list, the other items on the list take the name of the last item added.
Body: <p>I have a console application written in C, which takes inputs from the user in order to manipulate a linked list.</p>
<p>When the user inputs &quot;add&quot; to add an item, it will add the item, but all nodes added this way will share the name of the last item made using the &quot;add&quot; command.</p>
<p><strong>list.h</strong></p>
<pre class="lang-c prettyprint-override"><code>typedef struct node {
    char *name;
    int value;
    struct node *next;
} node_js;

static node_js *currentNode;

void printList(node_js *thing) {
    currentNode = thing;

    while (currentNode != NULL) {
        printf(&quot;%s\n&quot;, currentNode-&gt;name);
        printf(&quot;&gt;%d\n&quot;, currentNode-&gt;value);

        currentNode = currentNode-&gt;next;
    }
    printf(&quot;\n&quot;);
}

void addLast(node_js **thing, const char *name, int val) {
    if (*thing == NULL) {
        *thing = (node_js *)malloc(sizeof(node_js));
        //(*thing)-&gt;name = name;
        (*thing)-&gt;name = name;
        (*thing)-&gt;value = val;
        (*thing)-&gt;next = NULL;
    } else {
        currentNode = *thing;

        while (currentNode-&gt;next != NULL) {
            currentNode = currentNode-&gt;next;
        }

        currentNode-&gt;next = (node_js *)malloc(sizeof(node_js));
        //currentNode-&gt;next-&gt;name = strdup(name);
        currentNode-&gt;next-&gt;name = name;
        currentNode-&gt;next-&gt;value = val;
        currentNode-&gt;next-&gt;next = NULL;
    }
}

void removeLast(node_js **thing) {
    if (*thing == NULL) {
        return;
    }

    if ((*thing)-&gt;next == NULL) {
        free(*thing);
        *thing = NULL;
        return;
    }

    currentNode = *thing;

    while (currentNode-&gt;next-&gt;next != NULL) {
        currentNode = currentNode-&gt;next;
    }

    free(currentNode-&gt;next);
    currentNode-&gt;next = NULL;
}
</code></pre>
<p><strong>main.c</strong></p>
<pre class="lang-c prettyprint-override"><code>//the problem is on the addLast() inside the while(1), the probelm only occur with items that are
//added when user inputs &quot;add&quot;
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &quot;list.h&quot;

static int numInput;
static char textInput[32];

static char uInput[16];

node_js *list = NULL;

int main() {
     printf(&quot;--- Welcome to the program! ---\n&gt;Type 'exit', 'quit' or 'q' to exit\n&gt;Type 'help' for a list of the commands\n\n&quot;);

    //make list
    list = (node_js *)malloc(sizeof(node_js));

    list-&gt;name = &quot;joe&quot;;
    list-&gt;value = 10;
    list-&gt;next = (node_js *)malloc(sizeof(node_js));

    list-&gt;next-&gt;name = &quot;james&quot;;
    list-&gt;next-&gt;value = 20;
    list-&gt;next-&gt;next = NULL;

    addLast(&amp;list, &quot;jane&quot;, 30); //here it works fine

    while (1) {
        printf(&quot;input: &quot;);
        scanf_s(&quot;%s&quot;, textInput, sizeof(textInput));

        if (strcmp(textInput, &quot;quit&quot;) == 0 || strcmp(textInput, &quot;q&quot;) == 0 || strcmp(textInput, &quot;exit&quot;) == 0) {
            printf(&quot;Bye!&quot;);
            free(list);
            exit(1);
        }
        if (strcmp(textInput, &quot;print&quot;) == 0) {
            printList(list);
        }
        if (strcmp(textInput, &quot;add&quot;) == 0) {
            printf(&quot;name: &quot;);
            scanf_s(&quot;%s&quot;, uInput, sizeof(uInput));/*the problem is on the addLast() inside the while(1), the probelm only occur with items that are added when user inputs &quot;add&quot;*/
            printf(&quot;number: &quot;);
            scanf_s(&quot;%d&quot;, &amp;numInput, sizeof(numInput));

            addLast(&amp;list, uInput, numInput);
            printf(&quot;--- added (%s, %d) ---\n&quot;, uInput, numInput);   
        }
        if (strcmp(textInput, &quot;remove&quot;) == 0) {
            removeLast(&amp;list);
            printf(&quot;--- Removed last item of list ---\n&quot;);
        }
    }
    free(list);
    return 0;
}
