Title: Issues with Linked List in C.
Body: <p>The prompt I was given asks for a program in c that implements a linked list and gives users options to perform different functions on the linked list. The needed functions are:</p>
<ul>
<li>isempty(): checks if the list is empty and returns values indicating whether it is empty or not</li>
<li>add(): add an element to the tail of the list</li>
<li>insert(): insert an element at a specific index in the list</li>
<li>find(): find the index that a specific value is stored at. . If the function fails return a value indicating that</li>
<li>get(): get the value stored at a specific index</li>
<li>remove(): remove the first occurance of a specific value in the list.If the function fails return a value indicating that</li>
<li>replace(): replace the value stored at a specific index</li>
<li>delete(): delete the element at a specific index. . If the function fails return a value indicating that</li>
<li>list(): print the elements of the list in the format [a, b, c]</li>
</ul>
<p>When I call the add_tail function it allows me to enter the value I wish to add, but after about a minute I get a message in the terminal saying the program was killed. What could be causing that? I'm also having issues with the while loop in the main function that is used to print the menu and take the users input. The menu will print normally when I first run the program, but after an action is completed the menu prints once but skips over the user input, and then prints again but accepts the user input the second time.</p>
<p>header file:</p>
<pre><code>#ifndef LAB8_H_
#define LAB8_H_

#define FIND 'F'
#define EMPTY 'E'
#define ADD 'A'
#define INSERT 'I'
#define DELETE 'D'
#define REMOVE 'R'
#define REPLACE 'S'
#define GET 'G'
#define LIST 'L'
#define QUIT 'Q'
#define FAIL -100

struct node_t {
        struct node_t * next;
        int value;
};

struct node_t * create_node(int value);
struct node_t * add_tail(struct node_t * head, int value);
struct node_t * insert_node(struct node_t * head, int index, int value);
int is_empty(struct node_t * head);
int find_val(struct node_t * head, int value);
int get_value(struct node_t * head, int index);
struct node_t * replace_val(struct node_t * head, int index, int value);
struct node_t * remove_val(struct node_t * head, int value);
struct node_t * delete_node(struct node_t * head, int index);
void print_list(struct node_t * head);

#endif 
</code></pre>
<p>.c file:</p>
<pre><code>#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &quot;func.h&quot;

struct node_t * create_node(int value)
{
        struct node_t * new_node = malloc(sizeof(struct node_t));
        new_node -&gt; next = NULL;
        new_node -&gt; value = value;

        return new_node;
}


struct node_t * add_tail(struct node_t * head, int value)
{
        struct node_t * tmp;

        if(head == NULL){
                printf(&quot;Cannot add tail to an empty list. Try again\n&quot;);
                return NULL;
        } else{
                while(head != NULL){
                        if(head -&gt; next == NULL){
                                tmp = create_node(value);
                                head -&gt; next = tmp;
                        } else{
                                head = head -&gt; next;
                        }
                }
        }

        return head;
}


struct node_t * insert_node(struct node_t * head, int index, int value)
{
        struct node_t * tmp;
        struct node_t * new;

        if(index &lt; 0){
                printf(&quot;Index cannot be a negative number. Please try again\n&quot;);
                return head;
        }

        if(index == 0){
                tmp = head;
                head = create_node(value);
                head -&gt; next = tmp;
        } else {
                tmp = head;

                while(tmp != NULL){
                        if (index == 1){
                                struct node_t * prev = tmp;
                                tmp = tmp -&gt; next;
                                new = create_node(value);
                                new -&gt; next = tmp;
                                prev -&gt; next = new;
                                head = prev;
                        } else if((tmp -&gt; next == NULL) &amp;&amp; (index != 0)){
                                printf(&quot;The index is not found in the bounds of the list. Try again\n&quot;);
                                return head;
                        } else{
                                tmp = tmp -&gt; next;
                                index--;
                        }
                }
        }

        return head;
}

int is_empty(struct node_t * head)
{
        if(head == NULL){
                return 0;
        } else{
                return 1;
        }
}

int find_val(struct node_t * head, int value)
{
        int index = 0;

        if(head == NULL){
                printf(&quot;Cannot find value in empty list! Try again\n&quot;);
                index = -100;
        } else{
                while(head != NULL){
                        if((head -&gt; next == NULL) &amp;&amp; (head -&gt; value != value)){
                                printf(&quot;The value does not exist in the list\n&quot;);
                                index = -100;
                        } else if(head -&gt; value == value){
                                return index;
                        } else{
                                head = head -&gt; next;
                                index++;
                        }
                }
        }

        return index;
}

int get_value(struct node_t * head, int index)
{
        int value;

        if(index &lt; 0){
                printf(&quot;Index cannot be a negative number. Try again\n&quot;);
                value = -100;
        } else if(head == NULL){
                printf(&quot;Cannot find index in empty list. Try again\n&quot;);
                value = -100;
        } else{
                while(head != NULL){
                        if(index == 0){
                                value = head -&gt; value;

                        } else if((head -&gt; next == NULL) &amp;&amp; (index != 0)){
                                printf(&quot;Index does not exist in the bounds of the list. Try again\n&quot;);
                                value= -100;
                        } else{
                                head = head -&gt; next;
                                index--;
                        }
                }
        }

        return value;
}

struct node_t * replace_val(struct node_t * head, int index, int value)
{
        struct node_t * tmp;

        if(index &lt; 0){
                printf(&quot;Index cannot be a negative number. Try again\n&quot;);
                return NULL;
        } else if(head == NULL){
                printf(&quot;Cannot replace elements in an empty list. Try again\n&quot;);
                return NULL;
        } else{
                while(head != NULL){
                        if (index == 0){
                                tmp = head;
                                tmp -&gt; value = value;
                                free(head);
                                head = tmp;
                        } else if((head -&gt; next == NULL) &amp;&amp; (index != 0)){
                                printf(&quot;Index does not exist is the bounds of the list. Try again\n&quot;);
                                return NULL;
                        } else{
                                head = head -&gt; next;
                                index--;
                        }
                }
        }

        return head;
}

struct node_t * remove_val(struct node_t * head, int value)
{
        struct node_t * tmp;

        if(head == NULL){
                printf(&quot;Value cannot be found in an empty list. Try again\n&quot;);
                return NULL;
        } else{
                while(head != NULL){
                        if((head -&gt; next == NULL) &amp;&amp; (head -&gt; value != value)){
                                printf(&quot;The value does not exist in the list. Try again\n&quot;);
                                return NULL;
                        } else if(head -&gt; next -&gt; value == value){
                                tmp = head -&gt; next;
                                head -&gt; next = tmp -&gt; next;
                                free(tmp);
                        } else{
                                head = head -&gt; next;
                        }
                }
        }

        return head;
}

struct node_t * delete_node(struct node_t * head, int index)
{
        struct node_t * tmp;

        if(index &lt; 0){
                printf(&quot;Index cannot be a negative number. Try again\n&quot;);
                return NULL;
        } else if(head == NULL){
                printf(&quot;Cannot delete elements from an empty list. Try again\n&quot;);
                return NULL;
        } else{
                while(head != NULL){
                        if((head -&gt; next == NULL) &amp;&amp; (index != 0)){
                                printf(&quot;The index is not found in the bounds of the list. Try again\n&quot;);
                                return NULL;
                        } else if(index == 1){
                                tmp = head;
                                head = head -&gt; next;
                                tmp -&gt; next = head -&gt; next;
                                head -&gt; next = NULL;
                                free(head);
                                head = tmp;
                        } else{
                                head = head -&gt; next;
                                index--;
                        }
                }
        }

        return head;
}

void print_list(struct node_t * head)
{
        if (head == NULL){
                printf(&quot;The list is empty. Nothing to print\n&quot;);
        } else{
                while(head != NULL){
                        if(head -&gt; next != NULL){
                                printf(&quot;%d, &quot;, head -&gt; value);
                        } else{
                                printf(&quot;%d&quot;, head -&gt; value);
                        }

                        head = head -&gt; next;
                }
        }
}
</code></pre>
