Title: How to handle server&#39;s request for logout confirmation in Backbone.
Body: <p>I've got a project comprising a servlet/restlet back end (written in a Java8 framework) and Backbone front end.</p>
<p>The Backbone has a &quot;Logout&quot; button to terminate the user's browser session with the server and return them to the application's login prompt.</p>
<p>The original version of the Java framework included a web server which did not make a request to confirm the logout. As such, the Backbone code works just fine. Chrome DevTools shows the network call log as follows:</p>
<p><a href="https://i.stack.imgur.com/Ld31I.png" rel="nofollow noreferrer"><img src="https://i.stack.imgur.com/Ld31I.png" alt="enter image description here" /></a></p>
<p>The Java framework now has to be updated to a much more recent version; the Backbone code hasn't been modified. The web service in the newer Java framework is now requesting a logout confirmation which the Backbone isn't handling as needed: instead of being re-directed to the login prompt, the current page of the application (the one containing the Logout button) is simply re-displayed, so the only way to effect a logout is to close the browser window and restart the back end ! Chrome DevTools shows this new network call log as follows (please ignore the first line relating to panels):</p>
<p><a href="https://i.stack.imgur.com/teJS5.png" rel="nofollow noreferrer"><img src="https://i.stack.imgur.com/teJS5.png" alt="enter image description here" /></a></p>
<p>I'm new to Backbone and didn't write the original code. I'm simply trying to work out how to change it to get the logout working again by responding appropriately to the logoutConfirm. I've taken the original code, without third-party libraries, then stripped out anything that is purely application related to leave only the code relating to authorisation and logout -- I hope that's OK as a simplified reproduction here of the code I'm working with (see below).</p>
<p>Incidentally, the event corresponding to the click of the Logout button is the 'click .logoutlink' shown almost at the end of the code sample.</p>
<p>Can anyone explain to me what needs changing and why ? Many thanks.</p>
<pre><code>function AppAuth() {
    return {
        _currentUser: undefined,
        _redirectTo: undefined,

        isAuthorized: function () {
            return app.cookieCutter.get('apphash') !== undefined;
        },

        currentUser: function () {
            return this._currentUser;
        },

        // If user authorised, just return. If not, change the hash to /login
        authorizedOrRedirect: function () {
            if (!app.auth.isAuthorized() &amp;&amp; window.location.hash != '/login') {
                app.auth._redirectTo = window.location.hash; // Save current page to go back to
                this.logout();
                return false;
            }
        },

        logout: function () {
            if (this._currentUser != undefined) {
                this._currentUser.trigger('logout');
            }

            this._currentUser = undefined;

            $.ajax(&quot;/logout&quot;, {
                type: &quot;GET&quot;
            });

            var cookies = app.cookies.keys();
            _.forEach(cookies, function (cookie) {
                app.cookieCutter.remove(cookie);
            });

            window.location.pathname = &quot;/logout&quot;;
            return true;
        },
    };
}

app = {};
app.traceUrlEvents = true;

// Comment out if NOT CORS requests. In our case they are until release:
app.apiIsCrossOrigin = true;
jQuery.support.cors = true;

// Remote working
app.apiRoot = '/v1';
app.loginEndpoint = '/login';

// Localhost
app.auth = APPAuth();

if (app._queueSameGetRequests) {
    Backbone.xhrs = {};
    var oldFetch = Backbone.Model.prototype.fetch;
    Backbone.Model.prototype.fetch = function (opts) {
        var self = this;
        var args = arguments;
        // cache GET requests, not the others
        if (!opts || opts['cache'] !== true) {
            return oldFetch.apply(this, arguments);
        }

        var promise;
        var r;

        if (_.isFunction(this.url)) {
            r = this.url();
        } else {
            r = this.url;
        }

        // issue the request if a cached version does not exist
        if (!Backbone.xhrs[r]) {
            promise = Backbone.xhrs[r] = oldFetch.apply(this, arguments);
        } else {
            var p = Backbone.xhrs[r].done(function () {
                oldFetch.apply(self, args);
            });
            return p;
        }
        return promise;
    };
}

// Default error handlers for network and other XHR errors
app.networkAuthErrorHandler = function () {
    app.auth.logout();
    // Refresh the window, this should cause redirection to login screen. Could loop ?
    console.log(&quot;302 from API, authorization required&quot;);
    app.auth.authorizedOrRedirect();
};

app.networkErrorHandler = function () {
    $('#global-warn').show();
};

// Handle transport errors/network being down
$(document).ajaxError(function (evt, resp, request, txt) {
    if (resp.status === 0) {
        app.networkErrorHandler();
    }
});

app.Router = {};

app.boot = function () {
    app.EventObject = {};
    _.extend(app.EventObject, Backbone.Events);
    new app.controllers.DefaultController();
    app.Router = new app.controllers.Auth();
    new app.controllers.Users();

    // Force authorisation check when using navigate from within app
    var triggerNewRoute = function () {
        console.log(&quot;Route change&quot;, arguments);
        app.EventObject.trigger('routeChange');
        app.auth.authorizedOrRedirect();
    };

    Backbone.$(window).on('hashchange', triggerNewRoute);

    if (app.traceUrlEvents) {
        Backbone.$(window).on('pushstate', urlTraces);
        Backbone.$(window).on('popstate', urlTraces);
        Backbone.$(window).on('hashchange', urlTraces);
    }
};

app.models.BaseModel = Backbone.Model.extend({
    apiRoot: function () {
        return app.apiRoot;
    },

    // Overwrite to support trailing slashes
    url: function () {
        var base = _.result(this, 'urlRoot') || _.result(this.collection, 'url') || this.urlError();
        if (this.isNew()) return base;
        return base + (base.charAt(base.length - 1) === '/' ? '' : '/') + encodeURIComponent(this.id) + '/';
    },
});

(function (global) {
    'use strict';
})(this);

app.controllers.Auth = app.controllers.BaseController.extend({
    routes: {
        &quot;auth/&quot;: &quot;getAuthPage&quot;
    },

    getAuthPage: function () {
        var loginView = new app.views.LoginView();
        app.rootView.renderMainView(loginView, 'login');

        if (app.auth.isAuthorized()) {
            app.Router.navigate('//', { trigger: true });
        }
    }
});

// Router/controller for the user list page
app.controllers.Users = app.controllers.BaseController.extend({
    &quot;routes&quot;: {
        &quot;logout/&quot;: &quot;logoutCurrentUser&quot;
    },

    logoutCurrentUser: function () {
        console.log(&quot;&gt;&gt;&gt;&gt;&gt; logoutCurrentUser() is empty function !!&quot;)
    }
});

// Render the title bar
app.views.Headerbar = Backbone.View.extend({
    template: 'topbar',
    className: 'navbar navbar-main',
    events: {
        'click .logoutlink': 'doLogout',
    },

    doLogout: function (e) {
        e.preventDefault();
        app.auth.logout();
        window.location = app.loginEndpoint;
        return false;
    }
});
</code></pre>

