Title: Error generating JWT token during ASP.NET Core Web API authorization.
Body: <p>I have a Web API project through which I register and log in. During authorization, where I should get a token, an error appears:
<code>An unhandled exception has occurred while executing the request.  System.TypeInitializationException: The type initializer for System.IdentityModel.Tokens.Jwt.JsonExtensions' threw an exception.    System.TypeLoadException: Could not load type 'Microsoft.IdentityModel.Json.JsonConvert' from assembly 'Microsoft.IdentityModel.Tokens, Version=7.0.0.0, Culture=neutral, PublicKeyToken=31bf3856ad364e35'</code></p>
<p>Token generation code:</p>
<pre><code>using ASFT.Auth.Interfaces;
using Microsoft.IdentityModel.Tokens;
using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using System.Security.Cryptography;

namespace ASFT.Auth.Services
{
    public class TokenService : ITokenService
    {
        public string GenerateAccessToken(IEnumerable&lt;Claim&gt; claims)
        {
            var signinCredentials = new SigningCredentials(AuthOptions.Key, SecurityAlgorithms.HmacSha256);

            var tokenOptions = new JwtSecurityToken(
                issuer: AuthOptions.Issuer,
                audience: AuthOptions.Audience,
                claims: claims,
                expires: DateTime.Now.AddHours(48),
                signingCredentials: signinCredentials);

            return new JwtSecurityTokenHandler().WriteToken(tokenOptions);
        }
    }
}
</code></pre>
<p><a href="https://i.stack.imgur.com/HR5CR.jpg" rel="noreferrer">The error</a> is on this line - <code>return new JwtSecurityTokenHandler().WriteToken(tokenOptions);</code></p>
<p>Connected packages:</p>
<pre><code>&lt;PackageReference Include=&quot;Microsoft.AspNetCore.Authentication.JwtBearer&quot; Version=&quot;7.0.11&quot; /&gt;
&lt;PackageReference Include=&quot;Microsoft.AspNetCore.OpenApi&quot; Version=&quot;7.0.11&quot; /&gt;
&lt;PackageReference Include=&quot;Microsoft.IdentityModel.Tokens&quot; Version=&quot;7.0.0&quot; /&gt;
&lt;PackageReference Include=&quot;Swashbuckle.AspNetCore&quot; Version=&quot;6.5.0&quot; /&gt;
&lt;PackageReference Include=&quot;Microsoft.EntityFrameworkCore&quot; Version=&quot;7.0.11&quot; /&gt;
&lt;PackageReference Include=&quot;Microsoft.EntityFrameworkCore.SqlServer&quot; Version=&quot;7.0.11&quot; /&gt;
&lt;PackageReference Include=&quot;Microsoft.EntityFrameworkCore.Tools&quot; Version=&quot;7.0.11&quot;&gt;
   &lt;PrivateAssets&gt;all&lt;/PrivateAssets&gt;
   &lt;IncludeAssets&gt;runtime; build; native; contentfiles; analyzers; buildtransitive&lt;/IncludeAssets&gt;&lt;/PackageReference&gt;
</code></pre>
<p>Expected status 200 with token and refresh token in the response body.</p>

Title: Migrating existing API project to .NET 8 getting error when creating JWT tokens.
Body: <p>I just upgraded an ASP.NET Core 6 Web API to .NET 8 (note everything worked perfectly fine in .NET 6) and I'm getting this error when creating a JWT token:</p>
<blockquote>
<p>System.ArgumentOutOfRangeException: 'IDX10720: Unable to create KeyedHashAlgorithm for algorithm 'HS256', the key size must be greater than: '256' bits, key has '152' bits. (Parameter 'keyBytes')'</p>
</blockquote>
<p>Based on what I understand from this error, it looks like there is a new requirement for how long the secret needs to be so I made the secret longer, which works for creating the token but when reading the token I get a whole new error</p>
<blockquote>
<p>System.ArgumentException: 'IDX12723: Unable to decode the payload '[PII of type 'System.String' is hidden. For more details, see https://aka.ms/IdentityModel/PII.]' as Base64Url encoded string.'</p>
</blockquote>
<p>Edit: here is the inner exception maybe this can shed some light</p>
<blockquote>
<p>JsonException: IDX11020: The JSON value of type: 'String', could not be converted to 'JsonTokenType.Number'. Reading: 'System.IdentityModel.Tokens.Jwt.JwtPayload.iat', Position: '52', CurrentDepth: '1', BytesConsumed: '75'.</p>
</blockquote>
<p>Is there some breaking changes here for handling JWT tokens?</p>
<p>Here's the code of the private method reading the token</p>
<pre><code>private User? _GetIdentity(HttpContext context, string token)
{
     try
     {
         var handler = new JwtSecurityTokenHandler();
         //var jsonToken = handler.ReadToken(token);
         var tokenS = handler.ReadToken(token) as JwtSecurityToken;//error happens here

         var user = new User
         {
             Id = tokenS.Claims.First(claim =&gt; claim.Type == ClaimTypes.NameIdentifier).Value,
             UserName = tokenS.Claims.First(claim =&gt; claim.Type == ClaimTypes.Name).Value,
             Email = tokenS.Claims.First(claim =&gt; claim.Type == ClaimTypes.Email).Value,
             Role = tokenS.Claims.First(claim =&gt; claim.Type == ClaimTypes.Role).Value
         };

         if (tokenS.ValidTo &lt; DateTime.UtcNow)
         {
             throw new Exceptions.UnauthorizedAccessException($&quot;...&quot;);
         }

         return user;
     }
     catch(Exceptions.UnauthorizedAccessException e)
     {
        _logger.LogError(e.Message);
         throw;
     }
}
</code></pre>
<p>Here's the code for the class generating the JWT token:</p>
<pre><code>public class JwtService
{
    private const int EXPIRATION_TOKEN_MINUTES = 25;
    private const int EXPIRATION_REFRESH_DAYS = 7;
    private readonly IConfiguration _configuration;

    public JwtService(IConfiguration configuration)
    {
        _configuration = configuration;
    }

    public AuthenticationResponse CreateToken(IdentityUser user, IEnumerable&lt;string&gt; roles)
    {
        var expiration = DateTime.Now.AddMinutes(EXPIRATION_TOKEN_MINUTES);
        var refreshExpiration = DateTime.Now.AddDays(EXPIRATION_REFRESH_DAYS);
        var token = CreateJwtToken(
            CreateClaims(user, roles),
            CreateSigningCredentials(),
            expiration
            );
        var refreshToken = CreateJwtToken(
            CreateRefreshTokenClaims(user.Id),
            CreateSigningCredentials(),
            refreshExpiration
            );

        var tokenHandler = new JwtSecurityTokenHandler();

        return new AuthenticationResponse
        {
            Token = tokenHandler.WriteToken(token),
            RefreshToken = tokenHandler.WriteToken(refreshToken),
            Expiration = expiration
        };
    }

    private JwtSecurityToken CreateJwtToken(Claim[] claims, SigningCredentials credentials, DateTime expiration) =&gt;
        new JwtSecurityToken(
            _configuration[&quot;Jwt:Issuer&quot;],
            _configuration[&quot;Jwt:Audience&quot;],
            claims,
            expires: expiration,
            signingCredentials: credentials
        );

    private Claim[] CreateRefreshTokenClaims(string userId) =&gt;
        new[]
        {
            new Claim(JwtRegisteredClaimNames.Jti, Guid.NewGuid().ToString()),
            new Claim(JwtRegisteredClaimNames.Iat, DateTime.Now.ToString()),
            new Claim(ClaimTypes.NameIdentifier, userId)
        };

    private Claim[] CreateClaims(IdentityUser user, IEnumerable&lt;string&gt; roles) =&gt;
         new[] {
            //new Claim(JwtRegisteredClaimNames.Sub, _configuration[&quot;Jwt:Subject&quot;]),
            new Claim(JwtRegisteredClaimNames.Jti, Guid.NewGuid().ToString()),
            new Claim(JwtRegisteredClaimNames.Iat, DateTime.UtcNow.ToString()),
            new Claim(ClaimTypes.NameIdentifier, user.Id),
            new Claim(ClaimTypes.Name, user.UserName),
            new Claim(ClaimTypes.Email, user.Email),

         }
         .Concat(roles.Select(r =&gt; new Claim(ClaimTypes.Role, r)).ToArray())
         .ToArray();

    private SigningCredentials CreateSigningCredentials() =&gt;
        new SigningCredentials(
            new SymmetricSecurityKey(
                Encoding.UTF8.GetBytes(_configuration[&quot;Jwt:Secret&quot;])
            ),
            SecurityAlgorithms.HmacSha256
        );

    public ClaimsIdentity CreateClaimsIdentity(string username, string userId, IEnumerable&lt;string&gt; roles)
    {
        List&lt;Claim&gt; claims = new List&lt;Claim&gt;
        {
            new Claim(ClaimTypes.Name, username),
            new Claim(ClaimTypes.NameIdentifier, userId)
        };

        claims.AddRange(roles.Select(role =&gt; new Claim(ClaimTypes.Role, role)));

        ClaimsIdentity identity = new ClaimsIdentity(
            claims,
            &quot;Token&quot;,
            ClaimTypes.Name,
            ClaimTypes.Role
            );

        return identity;
    }

    public ClaimsPrincipal ValidateToken(string token)
    {
        try
        {
            var tokenHandler = new JwtSecurityTokenHandler();

            // Set the token validation parameters
            var validationParameters = new TokenValidationParameters
            {
                ValidateIssuer = true,
                ValidateAudience = true,
                ValidateLifetime = true,
                ValidateIssuerSigningKey = true,
                ValidAudience = _configuration[&quot;Jwt:Audience&quot;],
                ValidIssuer = _configuration[&quot;Jwt:Issuer&quot;],
                IssuerSigningKey = new SymmetricSecurityKey(
                Encoding.UTF8.GetBytes(_configuration[&quot;Jwt:Secret&quot;])
                )
            };

            // Validate and parse the token
            var principal = tokenHandler.ValidateToken(token, validationParameters, out var _);

            return principal;
        }
        catch
        {
            // Token validation failed
            return null;
        }
    }
}
</code></pre>

Title: Issue with Using JWT for Authentication in ASP.NET Core MVC.
Body: <p>I'm encountering an issue while implementing authentication using JSON Web Token (JWT) in ASP.NET Core MVC. I have an ASP.NET Core API with a login endpoint that returns a JWT in response to user login. Here's the code for my login endpoint in the API:</p>
<pre><code>[HttpPost]
[Route(&quot;login&quot;)]
public async Task&lt;IActionResult&gt; Login([FromBody] LoginUserDTO userDTO)
{
    // ... (omission for brevity)
    return Accepted(new TokenRequest { Token = await _authManager.CreateToken(), RefreshToken = await _authManager.CreateRefreshToken() });
}    

public async Task&lt;string&gt; CreateToken()
{
    var signingCredentials = GetSigningCredentials();
    var claims = await GetClaims();
    var token = GenerateTokenOptions(signingCredentials, claims);

    return new JwtSecurityTokenHandler().WriteToken(token);
}

private JwtSecurityToken GenerateTokenOptions(SigningCredentials signingCredentials, List&lt;Claim&gt; claims)
{
    var jwtSettings = _configuration.GetSection(&quot;Jwt&quot;);
    var expiration = DateTime.Now.AddMinutes(Convert.ToDouble(
        jwtSettings.GetSection(&quot;lifetime&quot;).Value));

    var token = new JwtSecurityToken(
        issuer: jwtSettings.GetSection(&quot;Issuer&quot;).Value,
        claims: claims,
        expires: expiration,
        signingCredentials: signingCredentials
        );

    return token;
}

private async Task&lt;List&lt;Claim&gt;&gt; GetClaims()
{
    var claims = new List&lt;Claim&gt;
    {
        new Claim(ClaimTypes.Name, _user.UserName)
    };

    var roles = await _userManager.GetRolesAsync(_user);

    foreach (var role in roles)
    {
        claims.Add(new Claim(ClaimTypes.Role, role));
    }

    return claims;
}

private SigningCredentials GetSigningCredentials()
{
    var key = _configuration.GetSection(&quot;Jwt:KEY&quot;).Value;
    var secret = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(key));

    return new SigningCredentials(secret, SecurityAlgorithms.HmacSha256);
}
</code></pre>
<p>Now, in my MVC project, I have a Login method that calls the API for login and securely saves the token:</p>
<pre><code>public async Task&lt;IActionResult&gt; Login(LoginViewModel model)
{
    // ... (omission for brevity)

    var token = await GetAccessToken(model); // call tha API to get the token

    if (!string.IsNullOrEmpty(token))
    {
        SaveToken(token);
        return RedirectToAction(&quot;Index&quot;, &quot;Home&quot;);
    }
    else
    {
        ModelState.AddModelError(&quot;&quot;, &quot;Invalid username or password&quot;);
    }
    return View(model);
} 
private void SaveTokenSecurely(string token)
{
    // Puoi salvare il token in un cookie sicuro, ad esempio:
    var cookieOptions = new CookieOptions
    {
        HttpOnly = true,
        Secure = true,
        SameSite = SameSiteMode.Strict,
        Expires = DateTime.UtcNow.AddHours(1)
    };

    Response.Cookies.Append(&quot;AccessToken&quot;, token, cookieOptions);
}
</code></pre>
<p>Here's how I've configured authentication in the MVC project:</p>
<pre><code>builder.Services.AddAuthentication(auth =&gt;
{
    auth.DefaultAuthenticateScheme = JwtBearerDefaults.AuthenticationScheme;
    auth.DefaultChallengeScheme = JwtBearerDefaults.AuthenticationScheme;
    auth.DefaultForbidScheme = JwtBearerDefaults.AuthenticationScheme;
})
 .AddJwtBearer(options =&gt;
 {
     var jwtSettings = builder.Configuration.GetSection(&quot;Jwt&quot;);
     var key = jwtSettings.GetSection(&quot;Key&quot;).Value;
     var issuer = jwtSettings.GetSection(&quot;Issuer&quot;).Value;

     options.TokenValidationParameters = new TokenValidationParameters
     {
         ValidateIssuer = true,
         ValidateAudience = false,
         ValidateLifetime = true,
         ValidateIssuerSigningKey = true,
         ValidIssuer = issuer,
         IssuerSigningKey = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(key)),

     };
 });
</code></pre>
<p>The appsettings.json file is the same for the API and MVC project:</p>
<pre><code>  &quot;Jwt&quot;: {
    &quot;Issuer&quot;: &quot;MY.PROJECT.Api&quot;,
    &quot;lifetime&quot;: 15,
    &quot;Key&quot;: &quot;SUPERR STRONG KEY&quot;
  }
</code></pre>
<p>The problem is that despite successful login and obtaining the token, when I try to access my Privacy page with the [Authorize(Roles = &quot;Administrator&quot;)] attribute, I still get a 401 error. I've verified that the &quot;Administrator&quot; role is present in the payload of my token.</p>
<p>I checked the token in <a href="https://jwt.io/" rel="nofollow noreferrer">jwt.io</a> and <a href="https://i.stack.imgur.com/oChAS.png" rel="nofollow noreferrer">here is the result</a>. If the <code>secret base64 encoded</code> is not checked I get Invalid Signature.</p>
<p>Also I tried to call <code>Privacy()</code> from <a href="https://www.postman.com/" rel="nofollow noreferrer">Postman</a> setting the <code>Authorization</code> &gt; <code>Bearer Token</code> &gt; <code>and then the token</code>, this works as expected.</p>
<p>I'm aware that there are several questions on Stack Overflow regarding JWT token unauthorized errors in ASP.NET Core MVC, and I've already looked into some of them:</p>
<ul>
<li><a href="https://stackoverflow.com/questions/60784211/jwt-token-error-401-unauthorized-in-net-core-3-1">JWT Token Error 401 Unauthorized in .NET Core 3.1</a></li>
<li><a href="https://stackoverflow.com/questions/61976960/asp-net-core-jwt-authentication-always-throwing-401-unauthorized">ASP.NET Core JWT Authentication Always Throwing 401 Unauthorized</a></li>
<li><a href="https://stackoverflow.com/questions/72071601/getting-401-unauthorized-asp-net-core-6">Getting 401 Unauthorized ASP.NET Core 6</a></li>
<li><a href="https://stackoverflow.com/questions/67837552/asp-net-core-5-and-6-jwt-authentication-is-always-throws-http-401-code">ASP.NET Core 5 and 6 JWT Authentication Always Throws HTTP 401 Code</a></li>
</ul>
<p>Does anyone have an idea of what the issue might be or how I can resolve it? Thanks in advance for the help!</p>
<h2>Temporary solution</h2>
<p>I solve it adding this:</p>
<pre><code>builder.Services.AddAuthentication(auth =&gt;
{
    auth.DefaultAuthenticateScheme = JwtBearerDefaults.AuthenticationScheme;
    auth.DefaultChallengeScheme = JwtBearerDefaults.AuthenticationScheme;
    auth.DefaultForbidScheme = JwtBearerDefaults.AuthenticationScheme;
})
 .AddJwtBearer(options =&gt;
 {
     var jwtSettings = builder.Configuration.GetSection(&quot;Jwt&quot;);
     var key = jwtSettings.GetSection(&quot;Key&quot;).Value;
     var issuer = jwtSettings.GetSection(&quot;Issuer&quot;).Value;

     options.TokenValidationParameters = new TokenValidationParameters
     {
         ValidateIssuer = true,
         ValidateAudience = false,
         ValidateLifetime = true,
         ValidateIssuerSigningKey = true,
         ValidIssuer = issuer,
         IssuerSigningKey = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(key)),
     };
     options.Events = new JwtBearerEvents
     {
         OnMessageReceived = context =&gt;
         {
             var token = context.Request.Cookies[&quot;AccessToken&quot;];
             context.Token = token;
             return Task.CompletedTask;
         }
     };
 });
</code></pre>
<p>although this is not a very good solution. Could you please provide a complete answer regarding my problem?</p>

Title: Custom token validator not working in .NET 8.
Body: <p>Today I was checking if I can migrate my app to .NET 8. At first everything was ok by when I tried to log in, I get following error in the console:</p>
<blockquote>
<p>Failed to validate the token.<br />
Microsoft.IdentityModel.Tokens.SecurityTokenInvalidSignatureException:
IDX10506: Signature validation failed. The user defined 'Delegate' specified on
TokenValidationParameters did not return a 'Microsoft.IdentityModel.JsonWebTokens.JsonWebToken',
but returned a 'System.IdentityModel.Tokens.Jwt.JwtSecurityToken' when validating token</p>
</blockquote>
<p>My client is using customized implementation of PingID. Tokens are validated using introspection that why I've written custom token validator:</p>
<pre><code>public class PingTokenValidator : ISecurityTokenValidator
{
    private readonly IConfiguration configuration;
    private readonly ILogger log;
    private readonly OpenIdConnectConfiguration openIdConnectConfiguration;
    private readonly JwtSecurityTokenHandler tokenHandler;

    public PingTokenValidator(OpenIdConnectConfiguration openIdConnectConfiguration,
        IConfiguration configuration)
    {
        this.tokenHandler = new();
        this.openIdConnectConfiguration = openIdConnectConfiguration;
        this.configuration = configuration;
        this.log = Log.ForContext&lt;PingTokenValidator&gt;();
    }

    public bool CanReadToken(string securityToken)
    {
        return true;
    }

    public ClaimsPrincipal ValidateToken(string securityToken,
        TokenValidationParameters validationParameters,
        out SecurityToken validatedToken)
    {
        try
        {
            var principal = this.tokenHandler.ValidateToken(securityToken, validationParameters, out validatedToken);

            if (tokenExistInCache &amp;&amp; cachedToken == securityToken)
            {
                return principal;
            }

            if (!this.IsValid(securityToken))
            {
                throw new SecurityTokenValidationException(&quot;Token not authorised by PingID.&quot;);
            }

            return principal;
        }
        catch (Exception e)
        {
            this.log.Error(e, &quot;Error validating JWT token&quot;);
            throw;
        }
    }

    public bool CanValidateToken { get; }

    public int MaximumTokenSizeInBytes { get; set; } = TokenValidationParameters.DefaultMaximumTokenSizeInBytes;

    private bool IsValid(string securityToken)
    {
        var options = new RestClientOptions
        {
            Authenticator = new HttpBasicAuthenticator(this.configuration[&quot;FDID:UserId&quot;]!, this.configuration[&quot;FDID:Secret&quot;]!)
        };
        var client = new RestClient(options);
        var request = new RestRequest(this.openIdConnectConfiguration.IntrospectionEndpoint, Method.Post);
        request.AddHeader(&quot;Content-Type&quot;, &quot;application/x-www-form-urlencoded&quot;);
        request.AddParameter(&quot;grant_type&quot;, &quot;urn:pingidentity.com:oauth2:grant_type:validate_bearer&quot;);
        request.AddParameter(&quot;token&quot;, securityToken);
        var response = client.Execute(request);

        if (!response.IsSuccessful)
        {
            this.log.Error(response.ErrorException, &quot;Error validating JWT token. Response message: {@TokenIntrospectionMessage}&quot;, response.Content);
            return false;
        }

        if (string.IsNullOrWhiteSpace(response.Content))
        {
            this.log.Error(&quot;Ping returned empty response: {@IntrospectionResponse}&quot;, response);
            return false;
        }

        var tokenSummary = JsonSerializer.Deserialize&lt;PingTokenSummary&gt;(response.Content, new JsonSerializerOptions
        {
            PropertyNameCaseInsensitive = true
        });

        return tokenSummary is
        {
            Active: true
        };
    }
}
</code></pre>
<p>I was looking for other interfaces that could be used instead of <code>ISecurityTokenValidator</code> but with no luck. Am I missing something?</p>

Title: Uncaught Error: Firebase\JWT\JWT::decode(): Argument #3 ($headers) cannot be passed by reference.
Body: <p>I'm trying to use <a href="https://github.com/jcubic/php-terminal-jwt" rel="nofollow noreferrer">JWT library from Firebase in PHP</a>. This is my code:</p>
<pre class="lang-php prettyprint-override"><code>$env = parse_ini_file('.env');

class Auth {
    private $service;
    public function __construct($service) {
        $this-&gt;service = $service;
    }
    public function login($user, $password) {
        global $env;
        if ($user != $env['user'] || $password != $env['password']) {
            return null;
        }

        $date = new DateTimeImmutable();
        $expire_at = $date-&gt;modify('+6 minutes')-&gt;getTimestamp();
        $payload = [
            'iat'  =&gt; $date-&gt;getTimestamp(),
            'iss'  =&gt; $env['domain'],
            'nbf'  =&gt; $date-&gt;getTimestamp(),
            'exp'  =&gt; $expire_at,
            'userName' =&gt; $user,
        ];
        return JWT::encode(
            $payload,
            $env['secret'],
            'HS512'
        );
    }
    private function valid_token($jwt) {
        global $env;
        $token = JWT::decode($jwt, $env['secret'], ['HS512']);
        $now = new DateTimeImmutable();
        return $token-&gt;iss == $env['domain'] &amp;&amp;
          $token-&gt;nbf &gt; $now-&gt;getTimestamp() &amp;&amp;
          $token-&gt;exp &gt; $now-&gt;getTimestamp();
    }
    public function __call($method, $params) {
        $jwt = array_shift($params);
        if (!$this-&gt;valid_token($jwt)) {
            throw new Exception(&quot;Invalid Token&quot;);
        }

        if (!in_array($method, $methods)) {
            throw new Exception(&quot;Invalid method $method&quot;);
        }

        return call_user_func_array(array($this-&gt;service, $method), $params);
    }
}
</code></pre>
<p>But when I try to decode the JWT I got this exception:</p>
<pre>
<br />
<b>Fatal error</b>:  Uncaught Error: Firebase\JWT\JWT::decode(): Argument #3 ($headers) cannot be passed by reference in /home/kuba/projects/jcubic/terminal/jwt/service.php:45
Stack trace:
#0 /home/kuba/projects/jcubic/terminal/jwt/service.php(54): Auth-&gt;valid_token()
#1 /home/kuba/projects/jcubic/terminal/jwt/json-rpc.php(302): Auth-&gt;__call()
#2 /home/kuba/projects/jcubic/terminal/jwt/service.php(73): handle_json_rpc()
#3 {main}
  thrown in <b>/home/kuba/projects/jcubic/terminal/jwt/service.php</b> on line <b>45</b>
</pre>
<p>ChatGPT 3.5 suggested to change <code>['HS512']</code> into <code>array(HS512')</code> which throw the same error.</p>
<p>The code is based on this article: <a href="https://www.loginradius.com/blog/engineering/guest-post/securing-php-api-with-jwt/" rel="nofollow noreferrer">How to Secure a PHP API Using JWT</a>.</p>
<p>To give you a bit of background I'm trying to use this Auth class as a wrapper for Service object and it all act as JSON-RPC for jQuery Terminal. That out of the box call login function get the token save it in localStorage and pass it to other methods as first argument.</p>

Title: How to set up Spring boot 3 security config proper?.
Body: <p>I'm trying to integrate the updated Spring Security in my project, instead of using the deprecated <code>extending WebSecurityConfigurerAdapter</code>. I've set up a good system in which the user gets authenticated (<code>User</code> implements <code>UserDetails</code> - I am using Hibernate) and a token gets generated. I get a 200 on this login and receive a token. This authetication part works fine.</p>
<p>Now the problem is that my users have roles (like <code>ADMIN</code>, <code>USER</code>, ...) These roles are added to the generated token. My controllers get the <code>@PreAuthorize</code> annotation. The request cannot pass these annotation and get a forbidden. When I don't use the <code>@PreAuthorize</code>, the requests get validated with the token.</p>
<pre class="lang-java prettyprint-override"><code>@Configuration
@EnableWebSecurity
@EnableMethodSecurity
public class SecurityConfig {
    private RSAKey rsaKey;
    private final DefaultUserDetailsService defaultUserDetailsService;

    public SecurityConfig(DefaultUserDetailsService defaultUserDetailsService) {
        this.defaultUserDetailsService = defaultUserDetailsService;
    }

    @Bean
    public AuthenticationManager authenticationManager(AuthenticationConfiguration authenticationConfiguration) throws Exception {
        return authenticationConfiguration.getAuthenticationManager();
    }

    @Bean
    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {

    return http 
               .cors(Customizer.withDefaults())
               .csrf(AbstractHttpConfigurer::disable)
               .authorizeHttpRequests(auth -&gt; auth
                   .requestMatchers(&quot;/auth/**&quot;).permitAll()
                   .anyRequest().authenticated()
               )            
               .userDetailsService(defaultUserDetailsService)
               .sessionManagement(session -&gt;  session.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
               .oauth2ResourceServer(OAuth2ResourceServerConfigurer::jwt)
               .headers(headers -&gt; headers
                   .frameOptions().sameOrigin()
               )
               .httpBasic(withDefaults())
               .build();
    }

    @Bean
    public JWKSource&lt;SecurityContext&gt; jwkSource() {
        rsaKey = Jwks.generateRsa();
        JWKSet jwkSet = new JWKSet(rsaKey);
        return (jwkSelector, securityContext) -&gt; jwkSelector.select(jwkSet);
    }

    @Bean
    JwtDecoder jwtDecoder() throws JOSEException {
        return NimbusJwtDecoder.withPublicKey(rsaKey.toRSAPublicKey()).build();
   }

    @Bean
    JwtEncoder jwtEncoder(JWKSource&lt;SecurityContext&gt; jwks) {
        return new NimbusJwtEncoder(jwks);
    }

    @Bean
    public PasswordEncoder getPasswordEncoder() {
        return new BCryptPasswordEncoder();
    }

    @Bean
    CorsConfigurationSource corsConfigurationSource() {
        CorsConfiguration configuration = new CorsConfiguration();
        configuration.setAllowedOrigins(List.of(&quot;http://localhost:4200&quot;));
        configuration.setAllowedMethods(List.of(&quot;GET&quot;,&quot;POST&quot;,&quot;DELETE&quot;));
        configuration.setAllowedHeaders(List.of(&quot;Authorization&quot;,&quot;Content-Type&quot;));
        UrlBasedCorsConfigurationSource source = new UrlBasedCorsConfigurationSource();
        source.registerCorsConfiguration(&quot;/**&quot;,configuration);
        return source;
    }

}
</code></pre>
<pre class="lang-java prettyprint-override"><code>@Component
public class KeyGeneratorUtils {

    private KeyGeneratorUtils() {}

    static KeyPair generateRsaKey() {
        KeyPair keyPair;
        try {
            KeyPairGenerator keyPairGenerator = KeyPairGenerator.getInstance(&quot;RSA&quot;);
            keyPairGenerator.initialize(2048);
            keyPair = keyPairGenerator.generateKeyPair();
        } catch (Exception ex) {
            throw new IllegalStateException(ex);
        }
        return keyPair;
    }
}

</code></pre>
<pre class="lang-java prettyprint-override"><code>public class Jwks {
       private Jwks() {}

        public static RSAKey generateRsa() {
            KeyPair keyPair = KeyGeneratorUtils.generateRsaKey();
            RSAPublicKey publicKey = (RSAPublicKey) keyPair.getPublic();
            RSAPrivateKey privateKey = (RSAPrivateKey) keyPair.getPrivate();
            return new RSAKey.Builder(publicKey)
                    .privateKey(privateKey)
                    .keyID(UUID.randomUUID().toString())
                    .build();
        }
}

</code></pre>
<pre class="lang-java prettyprint-override"><code>@Service
public class DefaultTokenService implements TokenService {
    private final JwtEncoder encoder;

    public DefaultTokenService(JwtEncoder encoder) {
        this.encoder = encoder;
    }

    @Override
    public String generateToken(Authentication authentication) {
        Instant now = Instant.now();
        String scope = authentication.getAuthorities().stream()
                .map(GrantedAuthority::getAuthority)
                .collect(Collectors.joining(&quot; &quot;));

        System.out.println(&quot;scope: &quot; + scope);

        JwtClaimsSet claims = JwtClaimsSet.builder()
                .issuer(&quot;self&quot;)
                .issuedAt(now)
                .expiresAt(now.plus(1, ChronoUnit.HOURS))
                .subject(authentication.getName())
                .claim(&quot;scope&quot;, scope)
                .build();
        return this.encoder.encode(JwtEncoderParameters.from(claims)).getTokenValue();
    }
