<h2>projectDir\app\api\login\route.ts</h2>
<pre><code>// Imports
import { signJwtAccessToken } from &quot;@/lib/jwt&quot;;
import prisma from &quot;@/lib/prisma&quot;;
import * as bcrypt from 'bcryptjs';

// Interface
interface RequestBody {
    username: string;
    password: string;
}

// Return route.
export async function POST(request: Request) {
    // Get requests body.
    const body: RequestBody = await request.json();

    // Create const with requested user.
    const user = await prisma.user.findFirst({
        where: {
            email: body.username,
        }
    });

    // If user exists check if password is correct and return the user.
    if(user &amp;&amp; ( await bcrypt.compare(body.password, user.password))) {
        // Remove password from user object in the response.
        const {password, ...userWithoutPass} = user

        // Create jwt.
        const accessToken = signJwtAccessToken(userWithoutPass);

        // Combine user with jwt as result.
        const result = {
            ...userWithoutPass,
            accessToken,
        }

        // Return the result as JSON object.
        return new Response(JSON.stringify(result));
    }

    // Return null as JSON object.
    else return new Response(JSON.stringify(null));
}
</code></pre>
<h2>projectDir\app\lib\jwt.ts</h2>
<pre><code>
// Imports
import jwt,{ JwtPayload } from &quot;jsonwebtoken&quot;;

// Interfaces
interface SignOption {
    expiresIn?: string | number,
}

// Default token expiration date.
const DEFAULT_SIGN_OPTION:SignOption={
    expiresIn: &quot;1h&quot;
}

// Function to create jwt.
export function signJwtAccessToken(payload: JwtPayload, options: SignOption= DEFAULT_SIGN_OPTION) {
    // Get secret key.
    const secret_key = process.env.SECRET_KEY;

    // Create token.
    const token = jwt.sign(payload, secret_key!, options);

    // Return the token.
    return token;
}

// Function to verify jwt.
export function verifyJwt(token: string) {
    try {
        // Get secret key.
        const secret_key = process.env.SECRET_KEY; 
        // Verify secret key.
        const decoded = jwt.verify(token, secret_key!);

        // Return if jwt is valid 
        return decoded as JwtPayload;
    } catch (error) {
        // If jwt is not valid, log the error.
        console.log(error);

        // And return null.
        return null;
    }
}
</code></pre>
<h1>What I tried</h1>
<p>I tried the following with no success. They all resulted in the same problem.</p>
<ul>
<li>Different version of different libraries e.g. downgrading next js / downgrading next-auth.</li>
<li>Removing the custom login route from the route.ts file and using a predefined user.</li>
<li>Removing callbacks.</li>
<li>Tried using the middleware on other pages then /settings.</li>
<li>Reinstalling the node_modules.</li>
</ul>

Title: npm package &quot;aws-jwt-verify&quot; not able to fetch jwks file on windows ec2 machine.
Body: <p>We have an express project where we've created a route to verify our token using &quot;aws-jwt-verify&quot; npm package. This code was working properly fine on mac and linux machines but when for our staging environment we deployed this on windows ec2 machine using pm2 process manager this package was not working and throwing an error.</p>
<p>Code</p>
<pre><code>const { CognitoJwtVerifier } = require('aws-jwt-verify');
class TokenVerificationSvc {
    constructor() {
    }

    async verify(token, type = 'id') {
        const docClient = new CognitoJwtVerifier({
            userPoolId: process.env.SApplicationUsersPool,
            tokenUse: type,
            clientId: process.env.SApplicationUsersPoolClient,
        });
        return await docClient.verify(token);
    }
}

module.exports = { TokenVerificationSvc };
</code></pre>
<p>Error</p>
<blockquote>
<p>Failed to fetch <a href="https://cognito-idp.ap-south-1.amazonaws.com/" rel="nofollow noreferrer">https://cognito-idp.ap-south-1.amazonaws.com/</a>/.well-known/jwks.json: Response time-out (after 1500 ms.)`</p>
</blockquote>
<p>To fix the above issues we tried another approach where we use the axios to fetch the jwks files and then cache that with our &quot;aws-jwt-verify&quot; for use. This is the same approach mentioned in &quot;aws-jwt-verify&quot; package documentation for reading files from filesystem.</p>
<p>Improvised Code</p>
<pre><code>const { CognitoJwtVerifier } = require('aws-jwt-verify');
const axios = require('axios');
class TokenVerificationSvc {
    constructor() {
    }

    async verify(token, type = 'id') {
        const jwksResponse = await axios.get(`https://cognito-idp.${process.env.CLOUD_REGION}.amazonaws.com/${process.env.SApplicationUsersPool}/.well-known/jwks.json`)
        const docClient = new CognitoJwtVerifier({
            userPoolId: process.env.SApplicationUsersPool,
            tokenUse: type,
            clientId: process.env.SApplicationUsersPoolClient,
        });
        const jwks = jwksResponse.data;
        docClient.cacheJwks(jwks);
        return await docClient.verify(token);
    }
}

module.exports = { TokenVerificationSvc };
</code></pre>
<p>Now I want to understand if this is the right approach to implement this or if there is some other way to do the same not using axios or any other 3rd party request like package.</p>

Title: How Parametered Routing system works in Electric Clojure.
Body: <p>I need a little help with how the parameterized routing system works in Electric Clojure.</p>
<p>I tried to create an example as basic as I could to show you what I needed. When I route my user to a new page sometimes I need to carry some information with that routing, I.e. name surname, etc.</p>
<p>Example:</p>
<ol>
<li>page ----&gt;</li>
</ol>
<pre><code>(e/defn first-page []
        (e/client

          (dom/text (str (def sum (+ 2 7))
                         )
