Title: Freeing dynamically allocated graph nodes in C.
Body: <p>I want to build a graph that creates a new parent node by merging two child nodes. The code below is supposed to merge node <code>a</code> and <code>b</code> into a parent node <code>c</code>. Then, nodes <code>a</code> and <code>c</code> to create a parent node <code>d</code>:</p>
<pre><code>    a   b
    |---|
      |
  a   c
  |---|
    |
    d
</code></pre>
<p>When I try to free the graph starting at node <code>d</code> I get a segmentation fault and I don't know why. Somehow it works if I don't use the same node twice in the graph. However, I want to be able to use the same node more than once. Can someone please tell me what am I missing here?</p>
<pre><code>#include &lt;stdlib.h&gt;


struct Node {

    int data;

    struct Node *child1;
    struct Node *child2;

};

struct Node *NewNode(double data) {

    struct Node *node = NULL;
    node = malloc(sizeof(*node));

    if (node == NULL) {
        return node;
    }

    node-&gt;data = data;
    node-&gt;child1 = NULL;
    node-&gt;child2 = NULL;

    return node;
}

struct Node* merge(struct Node *self, struct Node *other) {

    struct Node *node = NewNode(-1);
    node-&gt;child1 = self;
    node-&gt;child2 = other;

    return node;
}


void free_graph(struct Node **node) {
    if (*node != NULL) {
        free_graph(&amp;(*node)-&gt;child1);
        free_graph(&amp;(*node)-&gt;child2);
        free(*node);
        *node = NULL;
    }
}

int main(void){

    struct Node *a = NewNode(1);
    struct Node *b = NewNode(2);
    struct Node *c = merge(a, b);
    struct Node *d = merge(a, c);
    free_graph(&amp;d);

}
</code></pre>

