Title: Connecting to the ftp by proxy from golang.
Body: <p>I need to connect to ftp server through proxy and download a file from Golang code. I've implemented simple client:</p>
<pre class="lang-golang prettyprint-override"><code>package main

import (
    &quot;bufio&quot;
    &quot;fmt&quot;
    &quot;github.com/jlaffaye/ftp&quot;
    &quot;io&quot;
    &quot;log&quot;
    &quot;net&quot;
    &quot;net/http&quot;
    &quot;os&quot;
    &quot;strings&quot;
    &quot;time&quot;
)

var targetAddr = &quot;ftp.dlptest.com&quot;
var proxyAddr = &quot;146.19.106.109:3128&quot;
var user = &quot;dlpuser&quot;
var pass = &quot;rNrKYTX9g7z3RgJRmxWuGHbeu&quot;
var path = &quot;/xxx.txt&quot;

func connectViaProxy(network, address string) (net.Conn, error) {

    parts := strings.Split(address, &quot;:&quot;)
    addr := fmt.Sprintf(&quot;%s:%s&quot;, targetAddr, parts[1])

    proxyConn, err := net.Dial(network, proxyAddr)
    if err != nil {
        return nil, err
    }

    req, err := http.NewRequest(http.MethodConnect, &quot;http://&quot;+addr, nil)
    if err != nil {
        proxyConn.Close()
        return nil, err
    }

    req.Header.Set(&quot;Accept&quot;, &quot;*/*&quot;)
    req.Header.Set(&quot;User-Agent&quot;, &quot;curl/8.1.2&quot;)
    req.Header.Set(&quot;Host&quot;, targetAddr+&quot;:21&quot;)

    err = req.Write(proxyConn)
    if err != nil {
        return nil, err
    }

    resp, err := http.ReadResponse(bufio.NewReader(proxyConn), req)
    if err != nil {
        proxyConn.Close()
        return nil, err
    }
    if resp.StatusCode != 200 {

        x, _ := io.ReadAll(resp.Body)
        fmt.Println(string(x))

        proxyConn.Close()
        return nil, fmt.Errorf(&quot;non-200 status code received from proxy: %v&quot;, resp.Status)
    }

    return proxyConn, nil
}

func main() {
    c, err := ftp.Dial(targetAddr+&quot;:21&quot;,
        ftp.DialWithTimeout(5*time.Second),
        ftp.DialWithDebugOutput(os.Stdin),
        ftp.DialWithDialFunc(connectViaProxy),
    )
    if err != nil {
        log.Fatal(err)
    }

    err = c.Login(user, pass)
    if err != nil {
        log.Fatal(err)
    }

    if r, err := c.Retr(path); err != nil {
        fmt.Println(err, &quot;:&lt;&quot;)
    } else {
        if reader, err := io.ReadAll(r); err != nil {
            fmt.Println(err, &quot;:(&quot;)
        } else {
            fmt.Println(string(reader))
        }
    }

    if err = c.Quit(); err != nil {
        log.Fatal(err)
    }
}

</code></pre>
<p>Unfortunately, I'm receiving 403 Forbidden while trying to connect. Normally I would assume that this is server restriction but it works completely fine through curl:</p>
<pre><code>curl -vvv -x 146.19.106.109:3128 -u dlpuser:rNrKYTX9g7z3RgJRmxWuGHbeu ftp://ftp.dlptest.com/xxx.txt
</code></pre>
<p>Does anyone have some idea why is that happening? As far as I saw, curl is also using http CONNECT under the hood, so I'm wondering what I am missing.</p>
<p>P.S. don't worry about credentials in code - these are publicly available for testing in the web</p>

