Title: How do I unit test if http request has been canceled using HttpTestingClientModule?.
Body: <p>My component is invoking the method to get data from the server, it happens in <code>ngOnInit</code> lifecycle of the component. The request takes some time, and the user can navigate away from current view and destroy the component. In such a case, the get data request should be canceled. And this is what happens in actual application.</p>
<p><a href="https://i.stack.imgur.com/BeXlX.png" rel="nofollow noreferrer">Image of cancelled request in network tab</a></p>
<p>Now my goal is to unit test this behavior. What approach should I take? My current implementation is pretty naive and doesn't work...</p>
<p>What should I do in order to simulate request cancellation?</p>
<p>Here's my approach:</p>
<p>Component class:</p>
<pre><code>@Component({
    ...
    providers: [ProjectsOverviewService] &lt;-- Lifecycle of service depends on component
    ...
})
export class ProjectsOverviewComponent implements OnInit {
    constructor(private projectsOverviewService: ProjectsOverviewService) {}

    ngOnInit() {
        this.projectsOverviewService.getSomeData();
    }
}
</code></pre>
<p>Service class:</p>
<pre><code>@Injectable()
export class ProjectsOverviewService implements OnDestroy {
    private someData: Data;
    private serviceDestroyed$ = new Subject();

    constructor(private projectPageService: ProjectPageService) {}

    ngOnDestroy() {
        this.serviceDestroyed$.next();
    }

    getSomeData() {
        this.projectPageService.projectsGetAll$
        .pipe(takeUntil(this.serviceDestroyed$))
        .subscribe(data =&gt; this.someData = data);
    }
}
</code></pre>
<p>Spec file:</p>
<pre><code>let component: ProjectsOverviewComponent;
let fixture: ComponentFixture&lt;ProjectsOverviewComponent&gt;;
let httpTestingController: HttpTestingController;

beforeEach(async () =&gt; {
    await TestBed.configureTestingModule({
        imports: [
            HttpClientTestingModule
        ],
        declarations: [ProjectsOverviewComponent],
        providers: [ProjectsServiceProxy]
    }).compileComponents();
});

beforeEach(() =&gt; {
    fixture = TestBed.createComponent(ProjectsOverviewComponent);
    component = fixture.componentInstance;
    httpTestingController = TestBed.inject(HttpTestingController);
    fixture.detectChanges();
});

it('should cancel get some data request when component is destroyed', () =&gt; {
    const req = httpTestingController.expectOne('/api/services/app/Projects/GetAll');

    console.log(req); // TestRequest

    component.ngOnDestroy();

    expect(req.cancelled).toBe(true); // Fails - expected false, to be true.
});
</code></pre>

