Title: Running gulp.series programmatically from Node app does not run all tasks.
Body: <p><strong>The objective:</strong> Run gulp tasks programmatically from within a node application to be used at run time of application.</p>
<p><strong>The problem</strong>: Only the first two tasks in <code>gulp.series</code> are being run (<code>clean</code> and <code>handlebars</code>), <code>inline</code> task is being completely skipped.</p>
<p><strong>The Question:</strong> Can anyone tell me why only the first two tasks seem to run?</p>
<p>The following code is in a file called <code>app.js</code>. I run the file by typing <code>node app.js</code> in the terminal.</p>
<p><strong>Here is my code:</strong> Please scroll to see full code.</p>
<pre><code>const gulp = require('gulp');
const rename = require('gulp-rename');
const inlineCSS = require('gulp-inline-css');
const clean = require('gulp-clean');
const panini = require('panini');

//Compile Handlebars templates
gulp.task('handlebars', async function () {
    return gulp
        .src('views/pages/*.hbs')
        .pipe(
            panini({
                root: 'views/pages',
                layouts: 'views/layouts',
                partials: 'views/partials',
            })
        )
        .pipe(
            rename(function (path) {
                path.basename += '-send';
                path.extname = '.html';
            })
        )
        .pipe(gulp.dest('dist/inline-html'));
});

//Inline CSS from app.css into compiled HTML files
gulp.task('inline', async function () {
    return gulp
        .src('dist/inline-html/*.html')
        .pipe(inlineCSS())
        .pipe(gulp.dest('dist/send-html'));
});

//Clean dist folder
gulp.task('clean', async function () {
    return gulp.src('dist/**/*', { read: false }).pipe(clean());
});

async function gulpTaskRunner() {
    return new Promise(function (resolve, reject) {
        gulp.series('clean', 'handlebars', 'inline', (done) =&gt; {
            console.log('Gulp task completed');
            resolve();
            done();
        })();
    });
}

async function app() {
    console.log('start');
    await gulpTaskRunner();
    console.log('end');
}

app();
</code></pre>

Title: Error [ERR_REQUIRE_ESM]: require() of ES Module in gulpfile.js.
Body: <p>I have a React16 project and I'm trying to update it to React18, with old packages everything work well. but I updated all packages and dependecies, and when I want to run it it return this error:</p>
<pre><code>$ npx gulp wds
Error [ERR_REQUIRE_ESM]: require() of ES Module E:\project\frontend\node_modules\gulp-rev\index.js from E:\project\frontend\gulpfile.js not supported.
Instead change the require of index.js in E:\project\frontend\gulpfile.js to a dynamic import() which is available in all CommonJS modules.
    at Object.&lt;anonymous&gt; (E:\project\frontend\gulpfile.js:6:13) {
  code: 'ERR_REQUIRE_ESM'
}
</code></pre>
<p>myold gulpfile.js</p>
<pre><code>const gulp = require('gulp');
const gutil = require('gulp-util');
const plumber = require('gulp-plumber');
const sourcemaps = require('gulp-sourcemaps');
const rename = require('gulp-rename'); // переименование файлов
const rev = require('gulp-rev');
const revManifest = require('gulp-revmanifest');
const webpack = require('webpack');
const sass = require('gulp-sass'); // препроцессор sass
const postcss = require('gulp-postcss'); // PostCSS core
const autoprefixer = require('autoprefixer'); // расстановка вендорных префиксов
const csso = require('gulp-csso'); // минификация css, единственный работает корректно с sourcemaps
const WebpackDevServer = require('webpack-dev-server');
const webpackConfigProd = require('./webpack.prod');
const wdsConfig = require('./webpack.wds');

const path = {
  // откуда брать исходники:
  src: {
    css: './sass/app.scss',
    fonts: './../assets/fonts/roboto/*.*',
  },
  // куда складывать готовые после сборки файлы:
  dist: {
    css: './../assets/css/',
    fonts: './../assets/fonts/',
    manifestDir: './../',
    manifest: './../ver.json',
  },
  // за изменением каких файлов мы хотим наблюдать
  watch: {
    js: './**/*.js',
    css: './**/*.scss*',
  },
};
gulp.task('wds', () =&gt; {
  gulp.watch([path.watch.css], gulp.series('css:build'));
  // Start a webpack-dev-server
  new WebpackDevServer(webpack(wdsConfig), {
    publicPath: '/',
    contentBase: './../assets',
    historyApiFallback: {
      index: 'index.html',
    },
    stats: {
      colors: true,
    },
  }).listen(8089, 'localhost', err =&gt; {
    if (err) throw new gutil.PluginError('webpack-dev-server', err);
    gutil.log('[webpack-dev-server]', './../assets/index.html');
  });
});

gulp.task('webpack', callback =&gt; {
  webpack(webpackConfigProd, (err, stats) =&gt; {
    if (err) {
      throw new gutil.PluginError('webpack', err);
    }
    gutil.log('[webpack]', stats.toString({}));
    callback();
  });
});

// watch
gulp.task('watch', () =&gt; {
  // билд css в случае изменения
  gulp.watch([path.watch.css], gulp.series('css:build'));
  // билд js
  gulp.watch([path.watch.js], gulp.series('webpack'));
});

// билд css
gulp.task('css:build', () =&gt; {
  const ap = [autoprefixer()];
  return gulp
    .src(path.src.css)
    .pipe(plumber())
    .pipe(sourcemaps.init()) // инициализируем sourcemap
    .pipe(sass().on('error', sass.logError)) // скомпилировать sass
    .pipe(sourcemaps.write({ includeContent: false }))
    .pipe(sourcemaps.init({ loadMaps: true }))
    .pipe(postcss(ap)) // добавить вендорные префиксы
    .pipe(gulp.dest(path.dist.css)) // вызгрузить в dist немин. версию
    .pipe(csso({ debug: false })) // минификация
    .pipe(sourcemaps.write({ includeContent: false }))
    .pipe(rename({ suffix: '.min' }))
    .pipe(gulp.dest(path.dist.css)) // вызгрузить в build мин.версию
    .pipe(rev())
    .pipe(
      revManifest(path.dist.manifest, {
        merge: true,
      })
    )
    .pipe(gulp.dest(path.dist.manifestDir));
});

</code></pre>
