                self.remove_profile_folder(path_to_profile)

        driver = self.init_driver(browser, headless=headless, remove_old_session=remove_old_session)
        try:
            sleep(3)
            driver.get(url)
            sleep(5)
            if refresh and &quot;telegram&quot; not in url:
