Title: How to position positive value on top and negative value on bottom of stacked bar in chart js.
Body: <p>The <code>formatter</code> function gives me the total of each group of stacked bars, I am trying to do the <code>datalabels</code> positioning it up if the total is positive and positioning it down if it is negative. Please any help would be very grateful.</p>
<p><a href="https://i.stack.imgur.com/urCEM.png" rel="nofollow noreferrer"><img src="https://i.stack.imgur.com/urCEM.png" alt="enter image description here" /></a></p>
<pre><code>datalabels: {
    anchor: (context) =&gt;{
        const anchor = [];
        let sum = ?;

        if(parseFloat(sum) &gt;=0){
            anchor.push('end');
        }else{
            anchor.push('start');
        }
        return anchor;
    },
    align: (context) =&gt;{
        const align = [];
        let sum = ?;

        if(parseFloat(sum) &gt;=0){
            align.push('end');
        }else{
            align.push('bottom');
        }
        return align;

    },
    formatter:(value, context) =&gt;{
        const datasetArray = [];
        context.chart.data.datasets.forEach((dataset) =&gt;{
            if(dataset.data[context.dataIndex] != undefined){
                datasetArray.push(dataset.data[context.dataIndex]);
            }

        });

        function totalSum(total, datapoint){                                           
            return +total + +datapoint;
        }

        let sum = datasetArray.reduce(totalSum);
        if(context.datasetIndex === datasetArray.length - 1){
            return parseFloat(sum).toFixed(2) ;
        }else{
            return '';
        }
    },
}
</code></pre>

