Title: Chart.js Pie with best random background color.
Body: <p>I have some data that will be visualized in Pie Chart form.</p>
<p>However, I want 2 adjacent colors not to be identical. For example, if I have 3 data then I don't want them to have the background colors <code>#90EE90</code>, <code>#A1FFA1</code>, and <code>#FF0000</code> because the colors <code>#90EE90</code> and <code>#A1FFA1</code> have a bad contrast score according to <a href="https://coolors.co/contrast-checker/90ee90-a1ffa1" rel="nofollow noreferrer">coolors.co</a>.</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>let randomColor = () =&gt; {
  let characters='0123456789ABCDEF';
  let randomString='';
  for (let i=0; i&lt;6; i++) {
    let randomIndex=Math.floor(Math.random()*characters.length);
    randomString+=characters.charAt(randomIndex);
  }
  return '#'+randomString;
}
let round = (num) =&gt; Math.round(num*100)/100;

let chart = null;
$('#generate').click(()=&gt;{
  let data = [];
  let labels = [];
  let pieces = $('#pieces').val();
  for(let i=0; i&lt;pieces; i++) {
    labels.push(randomColor());
    data.push(round(1/pieces));
  }
  if(chart) chart.destroy();
  chart = new Chart($('#chart'), {
    type: 'pie',
    data: {
      labels: labels,
      datasets: [{
        data: data,
        backgroundColor: labels,
        borderWidth: 0
      }]
    },
    options: {
      plugins: {
        tooltip: {
          callbacks: {
            label: (context) =&gt; {
              return context.parsed;
            }
          }
        }
      }
    }
  });
});</code></pre>
<pre class="snippet-code-html lang-html prettyprint-override"><code>&lt;script src="https://cdnjs.cloudflare.com/ajax/libs/jquery/3.3.1/jquery.min.js"&gt;&lt;/script&gt;
