using namespace std;

int main(int argc, char **argv)
{
    cout&lt;&lt;&quot;Expected: '       -10'\n      got:'&quot;&lt;&lt;fmt::format(&quot;{:&gt;10d}&quot;,-10)&lt;&lt;&quot;'\n&quot;;
