        var mediaSource = new MediaSource;
        video.src = URL.createObjectURL(mediaSource);
        mediaSource.addEventListener('sourceopen', sourceOpen);
      } else {
        console.error('Unsupported MIME type or codec: ', mimeCodec);
      }

      function sourceOpen (_) {
        var mediaSource = this;
        var sourceBuffer = mediaSource.addSourceBuffer(mimeCodec);
        fetchAB(assetURL, function (buf) {
          sourceBuffer.addEventListener('updateend', function (_) {
            mediaSource.endOfStream();
            video.play();
          });
          sourceBuffer.appendBuffer(buf);
        });
      };

      function fetchAB (url, cb) {
        var xhr = new XMLHttpRequest;
        xhr.open('get', url);
        xhr.responseType = 'arraybuffer';
        xhr.onload = function () {
          cb(xhr.response);
        };
        xhr.send();
      };
    &lt;/script&gt;
  &lt;/body&gt;
</code></pre>
<p>Im always getting the error:</p>
<blockquote>
<p>Access to XMLHttpRequest at 'https://localhost:7113/viedo1.mp4' from origin 'http://localhost:8080/testclient' has been blocked by CORS policy: No 'Access-Control-Allow-Origin' header is present on the requested resource.</p>
</blockquote>
<p>I checked the configuration over and over again, it seems exactly as specified by MSDN. Also setting the video <code>src</code> attribute to the video's remote path works fine but it fails when using <code>XMLHttpRequest</code>.</p>
<p>Any ideas?</p>

Title: On iOS my images load way too slow. I am using expo image picker with Firebase cloud storage with xhr blob conversion.
Body: <p>On Android it hasn't shown to be an issue but iOS takes a full minute to display images when taken with camera/gallery to create a new post AND also in a <code>FlatList</code> render.</p>
<p>Has anyone else had this issue or know how to optimize it?</p>
<p>I am using <code>xhr</code> to convert to a blob which I am wondering if that might be the issue because I do set a loading spinner which doesn't show for a minute then it does and it loads fast.</p>
<p>This is a react native app built with expo using Firebase storage I'm converting the image to a download URL and saving to a Firestore document.</p>
<p>Here is my image handler:</p>
<pre><code>function ImageSelector({
onTakeImage,
editImage,
basePath,
clearImage,
}: {
    onTakeImage: (image: ImageType) =&gt; void
    clearImage: boolean
    editImage?: {url: string, type: string} | null
    basePath: string
}) {
    const [image, setImage] = useState&lt;{
        url: string
        type: string
    } | null&gt;(editImage ? editImage : null)
    const [showDurationErr, setShowDurationErr] = useState&lt;boolean&gt;(false)
    const [galleryImage, setGalleryImage] = useState&lt;{
        url: string
        type: string
    } | null&gt;(null)
    const [cameraPermissionInfo, requestPermission] = useCameraPermissions()
    const [mediaStatus, requestPermissionMedia] = useMediaLibraryPermissions()
    const [uploadStatus, setUploadStatus] = useState&lt;number&gt;(-1)
    const video = useRef(null)
    const [status, setStatus] = useState&lt;AVPlaybackStatusSuccess | {}&gt;({})

async function verifyPermissions() {
    if (cameraPermissionInfo?.status === PermissionStatus.UNDETERMINED) {
        const permission = await requestPermission()
        return permission.granted
    }
    if (cameraPermissionInfo?.status === PermissionStatus.DENIED) {
        Alert.alert(
            &quot;Permission was denied&quot;,
            &quot;Camera permissions are required to use this app.&quot;
        )
        return false
    }

    return true
}

useEffect(() =&gt; {
    if (clearImage) {
        setImage(null)
    }
}, [clearImage])

useEffect(() =&gt; {
    if (!cameraPermissionInfo?.granted) verifyPermissions()
    if(!mediaStatus?.granted) verifyGalleryPermissions()
}, [])

async function verifyGalleryPermissions() {
    if (mediaStatus?.status === PermissionStatus.UNDETERMINED) {
        const permission = await requestPermissionMedia()
        return permission.granted
    }
    if (mediaStatus?.status === PermissionStatus.DENIED) {
        Alert.alert(
            &quot;Permission was denied&quot;,
            &quot;Gallery permissions will be needed to use this app.&quot;
        )
        return false
    }

    return true
}

async function imageTakerHandler() {
    const hasPermission = await verifyPermissions()

    if (!hasPermission) {
        return
    }
    const generatedFileId = uuid.v4()
    const image = await launchCameraAsync({
        mediaTypes: MediaTypeOptions.All,
        allowsEditing: true,
        // aspect: [16, 9],
        quality: 0.6,
    })
    console.log(image)
    async function getDownloadURL(){
        console.log(image)
        if(image.canceled){
            setShowDurationErr(true)
            return
        }
        if (image.assets) {
            //fetch and react native - in RN .57+ swtiched the default xhr.responseType from blob to text thus blobModules uriandler doesnt kick in and since
            //okhttp doesnt recognize url of file:// scheme it throws and exception.  Something about a blob leak so use blob.close()
            try {
                const uri = image.assets[0].uri

                const blob = await new Promise((resolve, reject) =&gt; {
                    Toast.show({
                        type: &quot;success&quot;,
                        text1: &quot;your blob&quot;,
                        text2: 'has started',
                    })
                    const xhr = new XMLHttpRequest()
                    xhr.onload = function () {
                        resolve(xhr.response)
                    }
                    xhr.onerror = function () {
                        reject(new TypeError(&quot;Network request failed&quot;))
                    }
                    xhr.responseType = &quot;blob&quot;
                    xhr.open(&quot;get&quot;, uri, true)
                    xhr.send(null)
                })

                const downloadUrl = await FirebaseStorageService.uploadFile(
                    blob as Blob,
                    `${basePath}/${generatedFileId}`,
                    setUploadStatus
                )
                return downloadUrl
            } catch (error: any) {
                console.log(error?.message, &quot;downloadImageurl error&quot;)
            }finally{
                Toast.show({
                    type: &quot;congrats&quot;,
                    text1: &quot;your blob&quot;,
                    text2: 'has completed',
                })
            }
        }
    }
    getDownloadURL().then((response) =&gt; {
        if (response &amp;&amp; image.assets) {
            setImage({
                url: response as string,
                type: image.assets[0].type!,
            })
            onTakeImage({
                url: response as string,
                type: image.assets[0].type!,
            })
        }
    }).then(() =&gt; setUploadStatus(-1))
    }



async function imageSelectorHandler() {
    setShowDurationErr(false)
    setGalleryImage(null)
    const hasPermissionforGallery = await verifyGalleryPermissions()
    if (!hasPermissionforGallery) {
        return
    }
    const generatedFileId = uuid.v4()
    const galleryImage = await launchImageLibraryAsync({
        mediaTypes: MediaTypeOptions.All,
        allowsEditing: true,
        // aspect: [16, 9],
        quality: 0.6,
        videoMaxDuration: 120,
    })

    async function getDownloadURL() {
        if (
            galleryImage.canceled ||
            !galleryImage.assets ||
            (galleryImage.assets[0].duration &amp;&amp;
                galleryImage.assets[0]?.duration &gt; 150000)
        ) {
            // User cancelled the image selection or no assets were returned

            setShowDurationErr(true)
            return
        }

        if (galleryImage.assets) {
            //fetch and react native - in RN .57+ swtiched the default xhr.responseType from blob to text thus blobModules uriandler doesnt kick in and since
            //okhttp doesnt recognize url of file:// scheme it throws and exception.  Something about a blob leak so use blob.close()
            try {
                const uri = galleryImage.assets[0].uri

                const blob = await new Promise((resolve, reject) =&gt; {
                    const xhr = new XMLHttpRequest()
                    xhr.onload = function () {
                        resolve(xhr.response)
                    }
                    xhr.onerror = function () {
                        reject(new TypeError(&quot;Network request failed&quot;))
                    }
                    xhr.responseType = &quot;blob&quot;
                    xhr.open(&quot;get&quot;, uri, true)
                    xhr.send(null)
                })

                const downloadUrl = await FirebaseStorageService.uploadFile(
                    blob as Blob,
                    `${basePath}/${generatedFileId}`,
                    setUploadStatus
                )
                return downloadUrl
            } catch (error: any) {
                console.log(error?.message, &quot;downloadImageurl error&quot;)
            }
        }
    }
    getDownloadURL().then((response) =&gt; {
        if (response &amp;&amp; galleryImage.assets) {
            setGalleryImage({
                url: response as string,
                type: galleryImage.assets[0].type!,
            })
            onTakeImage({
                url: response as string,
                type: galleryImage.assets[0].type!,
            })
        }
    }).then(() =&gt; setUploadStatus(-1))
}

let imagePreview = (
    &lt;Text
        style={{
            color: Colors.bone,
            marginVertical: 10,
            fontFamily: &quot;Prata&quot;,
            fontSize: 17,
        }}
    &gt;
        Image/Video
    &lt;/Text&gt;
)

if (image) {
    imagePreview = (
        &lt;View style={styles.imagePrev}&gt;
            &lt;Image style={styles.image} source={{ uri: image.url }} /&gt;
        &lt;/View&gt;
    )
}

if (galleryImage) {
    if (galleryImage.type === &quot;image&quot;) {
        imagePreview = (
            &lt;View style={styles.imagePrev}&gt;
                &lt;Image
                    resizeMode=&quot;contain&quot;
                    style={styles.image}
                    source={{ uri: galleryImage.url }}
                /&gt;
            &lt;/View&gt;
        )
    } else if (galleryImage.type === &quot;video&quot;) {
        imagePreview = (
            &lt;View className=&quot;h-80 w-full mb-2 &quot;&gt;
                &lt;Video
                    ref={video}
                    style={{ width: &quot;100%&quot;, height: &quot;100%&quot; }}
                    source={{
                        uri: galleryImage.url,
                    }}
                    useNativeControls
                    resizeMode={ResizeMode.COVER}
                    isLooping
                    onPlaybackStatusUpdate={(status) =&gt;
                        setStatus(() =&gt; status)
                    }
                /&gt;
            &lt;/View&gt;
        )
    }
}

return (
    &lt;ScrollView className=&quot;w-full&quot;&gt;
        &lt;View className=&quot;w-full&quot;&gt;{imagePreview}&lt;/View&gt;
        {uploadStatus &gt; 0 &amp;&amp;
         &lt;Progress.Circle
         className=&quot;self-center&quot;
         progress={uploadStatus}
         animated={true}
         showsText={true}

         unfilledColor={Colors.primaryGreen}
         color={Colors.accentDark}
         /&gt;}
        &lt;View style={styles.buttonContainer}&gt;
            &lt;Icon
                color={Colors.bone}
                name={&quot;camera-enhance-outline&quot;}
                onPress={imageTakerHandler}
                size={30}
                text=&quot;Camera&quot;
            /&gt;
            {/* &lt;PrimaryBtn text=&quot;Camera&quot; onPress={imageTakerHandler} /&gt; */}
            &lt;Icon
                color={Colors.primaryLight}
                name={&quot;view-gallery-outline&quot;}
                onPress={imageSelectorHandler}
                size={30}
                text=&quot;Gallery&quot;
            /&gt;
            {/* &lt;AccentBtn text=&quot;Gallery&quot; onPress={imageSelectorHandler} /&gt; */}
        &lt;/View&gt;
        {showDurationErr &amp;&amp; (
            &lt;Text className=&quot;text-center text-bone&quot;&gt;
               Something went wrong, if video is longer than allotment of 2.5 minutes, please trim
                first.
            &lt;/Text&gt;
        )}
    &lt;/ScrollView&gt;
)
</code></pre>
<p>}</p>

