Title: My input always returns 0 when using the .target.innerHTML.
Body: <p>I am currently creating a UI for my Rock, Paper, Scissors game program in JavaScript. While changing pieces of my code, I found out that my variable <code>playerChoice</code>'s value will always end up as 0 when running the function <code>playRound(playerChoice, getComputerChoice())</code>. However, when inputting similar plain strings such as <code>ROCK, PAPER, or SCISSORS</code>, the code/game runs fine.</p>
<p>I tried following the path where it's being passed unto so I used console.log:</p>
<ul>
<li>Under Line 51 as <code>console.log(typeof playerChoice)</code> it's string</li>
<li>Under Line 26 as <code>console.log(typeof playerChecker)</code> it's string</li>
</ul>
<p>So far so good because it remains as the same data type. Now It's entering my function <code>inputConverter()</code> because of the variable <code>let playerChoice</code>. But when I use console.log:</p>
<ul>
<li>Under Line 29 as <code>console.log(playerChoice)</code>, it WILL ALWAYS end up as 0. But the variable chosen by the computer doesn't. Why is this?</li>
</ul>
<p>I've tried using debugging tools and all, but in the end it doesn't show up because it's a logical error. I thought it would be because I used <code>e.target.innerHTML</code>, but I'm unsure if that's truly the case.</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>function getComputerChoice() {
  // 2 is for Scissors, 1 is for Rock, 0 is for Paper
  const compChoice = Math.floor(Math.random() * 3);
  if (compChoice === 2) {
    return "Scissors";
  } else if (compChoice === 1) {
    return "Rock";
  } else
    return "Paper";
}

function inputConverter(gamerInput) {
  if (gamerInput === "ROCK") {
    return 2;
  } else if (gamerInput === "PAPER") {
    return 1;
  } else
    return 0;
}

function playRound(playerSelection, computerSelection) {
  let playerChecker = playerSelection.toUpperCase();
  let computerChecker = computerSelection.toUpperCase();

  let playerChoice = inputConverter(playerChecker);
  let computerChoice = inputConverter(computerChecker);

  if (playerChoice === computerChoice) {
    return "Draw! " + playerChecker + " is the same as " + computerChecker;
  } else if (playerChoice === 2 &amp;&amp; computerChoice === 0 ||
    playerChoice === 1 &amp;&amp; computerChoice === 2 ||
    playerChoice === 0 &amp;&amp; computerChoice === 1) {
    return "You Win! " + playerChecker + " beats " + computerChecker;
  } else {
    return "You Lose! " + computerChecker + " beats " + playerChecker;
  }
}

let buttonChoices = document.querySelectorAll("button");

buttonChoices.forEach(i =&gt; {
  i.addEventListener("click", (e) =&gt; {
    let playerChoice = e.target.innerHTML;
    console.log(playRound(playerChoice, getComputerChoice()));
  })
})</code></pre>
<pre class="snippet-code-html lang-html prettyprint-override"><code>&lt;div id="choiceContainer"&gt;
  &lt;button id="btn"&gt; Rock &lt;/button&gt;
  &lt;button id="btn"&gt; Paper &lt;/button&gt;
  &lt;button id="btn"&gt; Scissors &lt;/button&gt;
&lt;/div&gt;</code></pre>
</div>
</div>
</p>

