Title: How can I modify formData before sending it?.
Body: <p>How to modify the code so that after submitting the image changes to base64 code and so that I can use the formData from the form in the subpage component.</p>
<p>At the moment the <code>AddForm</code> look like this:</p>
<pre><code>import { Form, useNavigation } from 'react-router-dom';
import classes from './AuthForm.module.css';

function AddForm() {
  const navigation = useNavigation() 
  const isSubmitting =navigation.state === 'submitting'

  function fileToBase64(file) {
    return new Promise((resolve, reject) =&gt; {
      const reader = new FileReader();
      reader.readAsDataURL(file);

      reader.onload = () =&gt; {
        const base64 = reader.result;
        resolve(base64);
      };

      reader.onerror = (error) =&gt; {
        reject(error);
      };
    });
  }

  function handleFileInputChange(event) {
    const file = event.target.files[0];

    fileToBase64(file)
      .then((base64) =&gt; {
        console.log(base64);
      })
      .catch((error) =&gt; {
        console.error(error);
      });
  }

  return (
    &lt;&gt;
      &lt;Form method=&quot;post&quot; className={classes.form}&gt;
      &lt;div&gt;
        &lt;label htmlFor=&quot;title&quot;&gt;Tytuł:&lt;/label&gt;
        &lt;input
          type=&quot;text&quot;
          id=&quot;title&quot;
          name='title'
        /&gt;
      &lt;/div&gt;
      &lt;div&gt;
        &lt;label htmlFor=&quot;file&quot;&gt;Wybierz plik:&lt;/label&gt;
        &lt;input
          type=&quot;file&quot;
          id=&quot;file&quot;
          name='title'
          onChange={handleFileInputChange}
        /&gt;
      &lt;/div&gt;
      &lt;button disabled={isSubmitting}&gt;{isSubmitting ? 'Adding...' : 'Add'}&lt;/button&gt;
      &lt;/Form&gt;
      &lt;/&gt;
  );
}

export default AddForm;
