    std::vector&lt;std::unique_ptr&lt;Test::A&gt;&gt; v;

    v.emplace_back(std::make_unique&lt;Test::A&gt;());
    v.emplace_back(std::make_unique&lt;Test::A&gt;());

    g(v);

    return 0;
}
</code></pre>
<p>When I try to compile the code I get the following error:</p>
