Title: Destructor is not being invoked.
Body: <p>I have written the following code to implement a stack.</p>
<pre><code>#include&lt;iostream&gt;
using namespace std;

class stack
{
    public:
        int *top;
        int  size, capacity;

    stack(int c):capacity(c){
        size = 0;
        top = new int[capacity];
        capacity = capacity - 1;
    }

    ~stack() // deleting the stack at the end of program
    {
        delete[] top;
        top = NULL;
        cout &lt;&lt; &quot;deleted the stack&quot; &lt;&lt; endl;
    }

    void push(int data)
    {
        // Is there is a space
        if(is_stackFull())
        {
            cout &lt;&lt; &quot;stack is full&quot; &lt;&lt; endl;
            return;
        }

        // populate the data
        *top   = data;

        // updating the stack variables
         top  += 1;
         size += 1;
        return;
    }

    void pop()
    {
        // is stack empty
        if(is_stackEmpty())
        {
            cout &lt;&lt; &quot;stack is empty&quot; &lt;&lt; endl;
            return; 
        }

        // update the stack variables
        top  -= 1;
        size -= 1;

        return;
    }

    bool is_stackFull()
    {
        return (size == capacity);
    }

    bool is_stackEmpty()
    {
        return (size == 0);
    }
};


int main()
{
    stack s(10);
    s.push(15);
    //s.pop(); // what happens to the output when i comment out this code?

    return 0;
}

</code></pre>
<p>In the code, the destructor is not being invoked when I commented the s.pop() method.</p>
<p>Can any one explain the tech reason behind such behavior?</p>
<p>I tried understanding the ways to invoke the destructor in a C++ class.</p>

Title: Can I pop elements from the stack depending on whether they are used in a subroutine in Perl?.
Body: <p>edit:
included my perl script</p>
<p>Is there a way to call a subroutine by providing the parameters as pop(@stack) and the values only to be poped from the stack if they are used in the subroutine.
In the following example I would like:
the &quot;printok&quot; subroutine to pop 0 elements from the stack.
the &quot;check&quot; subroutine to pop 1 element from the stack.
the &quot;compare&quot; subroutine to pop 2 elements from the stack.</p>
<pre><code>
sub compare{
    my ($v1,$v2) = @_;
    if ($v1 &lt; $v2){
        return $v1;
    }
    else{
        return $v2;
    }
}

sub check{
    my $v = $_[0];
    if ($v &gt; 0){
        return &quot;ckeck done\n&quot;;
    }
    else{
        exit;
    }
}

sub printok{
    return &quot;ok\n&quot;;
}

print printok(pop(@stack),pop(@stack)),&quot;\n&quot;;
print check(pop(@stack),pop(@stack)),&quot;\n&quot;;
print compare(pop(@stack),pop(@stack)),&quot;\n&quot;;

print join(&quot; &quot;,@stack), &quot;\n&quot;;

</code></pre>
<p>My actual use case is in a program where operation names are in a hash and some operations require more arguments than others. I want to be able to call the functions depending on the operation codes listed in the hash.</p>
<p><strong>I do not want to work with the stack from inside of subroutines.</strong></p>
<p><strong>I wish to be able to call each subroutine with a single line.</strong> (or use as little conditional statements as possible)</p>
<p><code>$opcodes{$op}-&gt;(pop(@stack),pop(@stack),$n);</code></p>
<p>Some subroutines require only one element from the stack, other require 2, other require an additional integer.</p>
<p>My script:</p>
<pre><code>#!/usr/bin/perl
use strict;
use warnings;

#regex for numbers
my $regN = qr/[-+]?(?:\d+(?:\.\d+)?|\.\d+)(?:[eE][-+]?\d+)?/;
#creating the stack
my @stack;
#creating the hash table for the opcodes
my %opcodes = (
    '+'    =&gt; \&amp;add,
    '-'    =&gt; \&amp;subtract,
    '*'    =&gt; \&amp;multi,
    '/'    =&gt; \&amp;divide,
    'neg'  =&gt; \&amp;negate,
    'conj' =&gt; \&amp;conjugate,
    'abs'  =&gt; \&amp;absolute,
    'sqrt' =&gt; \&amp;squarert,
    'drop' =&gt; \&amp;drop,
    'dup'  =&gt; \&amp;dup,
    'swap' =&gt; \&amp;swap,
    'rot'  =&gt; \&amp;rot,
);

#declaration of the n variable used in the rot N function
my $n;

#realisation of the + function
sub add{
    die &quot;Error: The + function requires at least 2 elements in the stack&quot; 
    if 2 &gt; scalar @stack;

    my @q;
    my ($q2, $q1) = (pop(@stack),pop(@stack));

    #adding the elements of the quaternions
    @q[0] = @$q1[0] + @$q2[0];
    @q[1] = @$q1[1] + @$q2[1];
    @q[2] = @$q1[2] + @$q2[2];
    @q[3] = @$q1[3] + @$q2[3];
    push(@stack,[$q[0], $q[1], $q[2], $q[3]]);
};

#realisation of the - function
sub subtract{
    die &quot;Error: The - function requires at least 2 elements in the stack&quot; 
    if 2 &gt; scalar @stack;

    my @q;
    my ($q2, $q1) = (pop(@stack),pop(@stack));

    #subtracting the elements of the quaternions
    @q[0] = @$q1[0] - @$q2[0];
    @q[1] = @$q1[1] - @$q2[1];
    @q[2] = @$q1[2] - @$q2[2];
    @q[3] = @$q1[3] - @$q2[3];
    push(@stack,[$q[0], $q[1], $q[2], $q[3]]);
};

#realisation of the * function
sub multi{
    die &quot;Error: The * function requires at least 2 elements in the stack&quot; 
    if 2 &gt; scalar @stack;

    my @q;
    my ($q2, $q1) = (pop(@stack),pop(@stack));

    #https://www.euclideanspace.com/maths/algebra/
    #realNormedAlgebra/quaternions/arithmetic/
    @q[0] = (@$q1[0] * @$q2[0] - @$q1[1] * @$q2[1] - 
    @$q1[2] * @$q2[2] - @$q1[3] * @$q2[3]);
    @q[1] = (@$q1[1] * @$q2[0] + @$q1[0] * @$q2[1] + 
    @$q1[2] * @$q2[3] - @$q1[3] * @$q2[2]);
    @q[2] = (@$q1[0] * @$q2[2] - @$q1[1] * @$q2[3] + 
    @$q1[2] * @$q2[0] + @$q1[3] * @$q2[1]);
    @q[3] = (@$q1[0] * @$q2[3] + @$q1[1] * @$q2[2] - 
    @$q1[2] * @$q2[1] + @$q1[3] * @$q2[0]);
    push(@stack,[$q[0], $q[1], $q[2], $q[3]]);
};

#realisation of the / function
sub divide{
    die &quot;Error: The / function requires at least 2 elements in the stack&quot; 
    if 2 &gt; scalar @stack;

    my @q;
    my ($q2, $q1) = (pop(@stack),pop(@stack));

    #https://www.mathworks.com/help/aeroblks/quaterniondivision.html
    @q[0] = (@$q1[0] * @$q2[0] + @$q1[1] * @$q2[1] + 
    @$q1[2] * @$q2[2] + @$q1[3] * @$q2[3])/
    (@$q1[0]**2 + @$q1[1]**2 + @$q1[2]**2 + @$q1[3]**2);
    @q[1] = (@$q1[0] * @$q2[1] - @$q1[1] * @$q2[0] - 
    @$q1[2] * @$q2[3] + @$q1[3] * @$q2[2])/
    (@$q1[0]**2 + @$q1[1]**2 + @$q1[2]**2 + @$q1[3]**2);
    @q[2] = (@$q1[0] * @$q2[2] + @$q1[1] * @$q2[3] - 
    @$q1[2] * @$q2[0] - @$q1[3] * @$q2[1])/
    (@$q1[0]**2 + @$q1[1]**2 + @$q1[2]**2 + @$q1[3]**2);
    @q[3] = (@$q1[0] * @$q2[3] - @$q1[1] * @$q2[2] + 
    @$q1[2] * @$q2[1] - @$q1[3] * @$q2[0])/
    (@$q1[0]**2 + @$q1[1]**2 + @$q1[2]**2 + @$q1[3]**2);
    push(@stack,[$q[0], $q[1], $q[2], $q[3]]);
}

#realisation of the neg function
sub negate{
    die &quot;Error: The neg function requires at least 1 elements in the stack&quot; 
    if 0 == scalar @stack;

    my @q;
    my $q1 = pop(@stack);

    @q[0] = @$q1[0] * -1;
    @q[1] = @$q1[1] * -1;
    @q[2] = @$q1[2] * -1;
    @q[3] = @$q1[3] * -1;
    push(@stack,[$q[0], $q[1], $q[2], $q[3]]);
}

#realisation of the conj function
sub conjugate{
    die &quot;Error: The conj function requires at least 1 element in the stack&quot; 
    if 0 == scalar @stack;

    my @q;
    my $q1 = pop(@stack);
    @q[0] = @$q1[0];
    @q[1] = @$q1[1] * -1;
    @q[2] = @$q1[2] * -1;
    @q[3] = @$q1[3] * -1;
    push(@stack,[$q[0], $q[1], $q[2], $q[3]]);
}

#realisation of the abs function
sub absolute{
    die &quot;Error: The abs function requires at least 1 element in the stack&quot; 
    if 0 == scalar @stack;

    my @q;
    my $q1 = pop(@stack);
    #finding absolute values of each individual component
    @q[0] = abs(@$q1[0]);
    @q[1] = abs(@$q1[1]);
    @q[2] = abs(@$q1[2]);
    @q[3] = abs(@$q1[3]);
    push(@stack,[$q[0], $q[1], $q[2], $q[3]]);
}

#realisation of the sqrt function
sub squarert{
    die &quot;Error: The sqrt function requires at least 1 element in the stack&quot; 
    if 0 == scalar @stack;

    my @q;
    my $q1 = pop(@stack);
    #https://www.johndcook.com/blog/2021/01/06/quaternion-square-roots/
    #finding the magnitude of the quaternion
    my $magnitude = sqrt(@$q1[0]**2 + @$q1[1]**2 + @$q1[2]**2 + @$q1[3]**2);
    my $theta = atan2(sqrt(1 - (@$q1[0] / $magnitude)**2), @$q1[0] / $magnitude);
    @q[0] = cos($theta/2);
    @q[1] = sin($theta/2) * (@$q1[1] / $magnitude);
    @q[2] = sin($theta/2) * (@$q1[2] / $magnitude);
    @q[3] = sin($theta/2) * (@$q1[3] / $magnitude);
    push(@stack,[$q[0], $q[1], $q[2], $q[3]]);
    push(@stack,[$q[0], $q[1], $q[2], $q[3]]);
    conjugate();
}

#realisation of the exp function
sub drop{
    die &quot;Error: The drop function requires at least 1 element in the stack&quot; 
    if 0 == scalar @stack;

    pop(@stack);
}

#realisation of the dup function
sub dup{
    die &quot;Error: The dup function requires at least 1 element in the stack&quot; 
    if 0 == scalar @stack;

    my @q;
    my $q1 = pop(@stack);
    @q = @$q1;
    push(@stack,[$q[0], $q[1], $q[2], $q[3]]);
    push(@stack,[$q[0], $q[1], $q[2], $q[3]]);
}

#realisation of the swap function
sub swap{
    die &quot;Error: The swap function requires at least 2 elements in the stack&quot; 
    if 2 &gt; scalar @stack;

