};

double sol[5] = 
{
  -180.041874,
  -0.041874,
  -0.041874,
  -0.041874,
  -0.209372,
};
</code></pre>
<p>I expect to get (and ran this system of equations through Wolfram Alpha) the following for my unknowns:</p>
<pre><code>double T_expected[5] = 
{
  198.298282,
  196.616925,
  194.965693,
  193.373744,
  192.046373,
};
</code></pre>
<p>However, running the equations through my function, I get these values instead.</p>
<pre><code>double T[5] = 
{
  199.674915,
  199.257945,
  198.676137,
  197.711841,
  196.277411,
};
</code></pre>
<p>Here is my function:</p>
<pre><code>#define EPSILON 1e-06
double *runGaussSeidel(double **matrix, double *sol, int n)
{
    int i, j, converged, m = n - 1;
    double sum1 = 0.0, sum2 = 0.0, temp = 0.0;
    double *T = malloc(sizeof(double) * m);

    // Initial guess.
    for (i = 0; i &lt; m; i++)
        T[i] = 0.0;

    do {   
        converged = 1; 
        for (i = 0; i &lt; m; i++)
        {
            sum1 = sum2 = 0.0;
            for (j = 0; j &lt; i; j++)
            {
                sum1 += matrix[i][j] * T[j];
            }   
            for (j = i + 1; j &lt; m; j++)
            {
                sum2 += matrix[i][j] * T[i];
            }

            double temp = T[i];

            T[i] = (sol[i] - sum1 - sum2) / matrix[i][i];                                                                   


            if (T[i] - temp &gt;= EPSILON)
            {
                converged = 0;
            }                    
        }                                                                      
    } while (!converged); 

    return T;
}
</code></pre>

