                            byte[] data = new byte[datagramPacket.getLength() - headerLen];

                            for (int i = 0; i &lt; headerLen; i++){
                                    header[i] = datagramPacket.getData()[i];
                            }
                            for (int i = headerLen; i &lt; datagramPacket.getLength(); i++){
                                    data[i - headerLen] = datagramPacket.getData()[i];
                            }

        }
    }  catch (SocketException e) {
                    e.printStackTrace();
    } catch (IOException e) {
                    e.printStackTrace();
    }    
}
</code></pre>

Title: Nodemailer - DeprecationWarning: The `punycode` module is deprecated.
Body: <p>I need to create a script that send a mail once a day using a gmail account. I've used nodemailer and I have this simple test code</p>
<pre class="lang-js prettyprint-override"><code>const fs = require('fs');
const path = require('path');
const nodemailer = require('nodemailer');

const transport = nodemailer.createTransport({
    host: 'smtp.gmail.com',
    //secure: true,
    //port: 465,
    auth: {
        user: 'myuser@companyworkspace.com',
        pass: 'mypassword'
    }
})

let mailOptions = {
    from: 'bruno.paolillo@ohspa.it', // sender address
    to: 'bruno.paolillo@ohspa.it', // list of receivers
    subject: 'Test email', // Subject line
    text: 'this is some text', //, // plaintext body
    html: '&lt;b&gt;Hello world &lt;/b&gt;' // You can choose to send an HTML body instead
}

transport.sendMail(mailOptions, (error, info) =&gt; {
    if( error ) {
        return false;
    } else {
        console.log('Message sent: ' + info.response);
        return true;
    };
});
</code></pre>
<p>I've noticed that I will always get this error when I try to run the script using <code>node index.js</code></p>
<pre><code>(node:20496) [DEP0040] DeprecationWarning: The `punycode` module is deprecated. Please use a userland alternative instead.
(Use `node --trace-deprecation ...` to show where the warning was created)
</code></pre>
<p>Is there any problem into the code or it's a nodemailer bug?Is there any alternative?</p>

Title: Receiving 400 - Mail service not enabled when calling Gmail API.
Body: <p>I am using OAuth 2.0 Client ID while working with Gmail API.</p>
<p>For one customer when calling <code>gmail_v1.Gmail.users.messages.list({userId: 'me'})</code> endpoint (or any other endpoint), I am receiving a &quot;Mail service not enabled&quot; 400 error without any further explanation of what happened. Gmail API documentation does not include such an error definition.</p>
<p>The customer has access to Gmail. The email they are trying to connect is part of another Google organisation. Other customers inside and outside our Google organisation can use the endpoint successfully.</p>
<p>Full response from Gmail API:</p>
<pre><code>{
    &quot;error&quot;: {
        &quot;code&quot;: 400,
        &quot;message&quot;: &quot;Mail service not enabled&quot;,
        &quot;errors&quot;: [
            {
                &quot;message&quot;: &quot;Mail service not enabled&quot;,
                &quot;domain&quot;: &quot;global&quot;,
                &quot;reason&quot;: &quot;failedPrecondition&quot;
            }
        ],
        &quot;status&quot;: &quot;FAILED_PRECONDITION&quot;
    }
}
</code></pre>
<p>Does anyone know a setting in their Google admin organisation which could enable Gmail API?</p>

Title: Adding Label to Gmail sent from Nodemailer with GmailAPI.
Body: <p>I am using Gmail API, with nodemailer to send an automated email to unread threads. I want to add a label of AutoResponse in Gamil so that the replied mails appear with that labels.</p>
<p>Here is the code for sending the mail</p>
<pre><code>const checkForNewMessages = () =&gt; {
    //get message details
  gmail.users.messages.list(
    {
      userId: &quot;me&quot;,
      q: `is:unread`,
    },
    async (err, res) =&gt; {
      if (err) return console.log(&quot;The API returned an error: &quot; + err);

      const messages = res.data.messages;

      if (messages?.length) {
        console.log(&quot;New message received!&quot;);

        //checking if message unread
        for (const message of messages) {
          const messageDetails = await gmail.users.messages.get({
            userId: &quot;me&quot;,
            id: message.id,
          });
          const threadId = messageDetails.data.threadId;
          const threadDetails = await gmail.users.threads.get({
            userId: &quot;me&quot;,
            id: threadId,
          });

          const addLabelToThread = await gmail.users.threads.modify({
            userId: &quot;me&quot;,
            id: threadId,
            resource: {
              addLabelIds: [&quot;AutoResponse&quot;],
              removeLabelIds: [&quot;INBOX&quot;],
            },
          });

          if (
            !threadDetails.data.messages.some(
              (msg) =&gt;
                msg.labelIds.includes(&quot;SENT&quot;) &amp;&amp;
                msg.payload.headers.find(
                  (header) =&gt;
                    header.name === &quot;From&quot; &amp;&amp;
                    header.value.includes(&quot;mymail@gmail.com&quot;)
                )
            )
          ) {
            console.log(
              `New email thread with subject &quot;${
                messageDetails.data.payload.headers.find(
                  (header) =&gt; header.name === &quot;Subject&quot;
                ).value
              }&quot; and thread ID ${threadId} received!`
            );

            // Sending a response to new unread Threads
            const transporter = nodemailer.createTransport({
              service: &quot;gmail&quot;,
              auth: {
                type: &quot;OAuth2&quot;,
                user: &quot;mymail@gmail.com&quot;,
                clientId: process.env.CLIENT_ID,
                clientSecret: process.env.CLIENT_SECRET,
                refreshToken: process.env.REFRESH_TOKEN,
                accessToken: oAuth2Client.getAccessToken(),
              },
            });

            const mailOptions = {
              from: &quot;mymail@gmail.com&quot;,
              to: messageDetails.data.payload.headers.find(
                (header) =&gt; header.name === &quot;From&quot;
              ).value,
              subject:
                &quot;Re: &quot; +
                messageDetails.data.payload.headers.find(
                  (header) =&gt; header.name === &quot;Subject&quot;
                ).value,
              text: &quot;Thank you for your message. I will respond as soon as I am available&quot;,
            };

            transporter.sendMail(mailOptions, async (err, info) =&gt; {
              if (err) {
                console.log(err);
              } else {
                console.log(
                  `Automatic response sent to ${
                    messageDetails.data.payload.headers.find(
                      (header) =&gt; header.name === &quot;From&quot;
                    ).value
                  }: ${info.response}`
                );
                addLabelToThread();
              }
            });

          } else {
            console.log(
              `Email thread with thread ID ${threadId} already has a reply from you.`
            );
          }
        }
      } else {
        console.log(&quot;No new messages.&quot;);
      }
    }
  );
};
</code></pre>
<p>I tried the addLabelToThread function, but doesn't seem to work.
Giving this error to be specific</p>
<pre><code> error: {
        code: 400,
        message: 'Invalid label: SENT',
        errors: [
          {
            message: 'Invalid label: SENT',
            domain: 'global',
            reason: 'invalidArgument'
          }
        ],
        status: 'INVALID_ARGUMENT'
      }
</code></pre>

Title: Ggmail API Golang: Precondition check failed.
Body: <p>I am trying to access my gmail api with the scope of:</p>
<pre><code>https://www.googleapis.com/auth/gmail.modify
</code></pre>
<p>But I am getting a Precondition check failed error.</p>
<p>The below is the code that I am using to connect to my gmail and use to send a message out:</p>
<pre><code>func ConnectToGmailAPI() *gmail.Service {
