        log.Fatalf(&quot;Unable to connect to service %v&quot;, err)
    }

    return srv
}

func SendEmail(srv *gmail.Service, subj, msg, to string) (*gmail.Message, error) {
    message, err := gmail.NewUsersMessagesService(srv).Send(
        &quot;me&quot;,
        prepMessage(subj, msg, to),
    ).Do()

    if err != nil {
        return &amp;gmail.Message{}, err
    }

    return message, nil

}

func prepMessage(subj, msg, to string) *gmail.Message {
    header := make(map[string]string)
    header[&quot;To&quot;] = to
    header[&quot;Subject&quot;] = subj
    header[&quot;Content-Type&quot;] = &quot;text/plain; charset=utf-8&quot;

    var headers []*gmail.MessagePartHeader
    for k, v := range header {
        headers = append(headers, &amp;gmail.MessagePartHeader{Name: k, Value: v})
    }

    messagePart := &amp;gmail.MessagePart{
        Body: &amp;gmail.MessagePartBody{
            Data: base64.URLEncoding.EncodeToString([]byte(msg)),
        },
        Headers: headers,
    }

    message := gmail.Message{
        Payload: messagePart,
    }

    return &amp;message
}

</code></pre>
<p>The below is the actual test I am running:</p>
<pre><code>srv := ConnectToGmailAPI()
    msg, err := SendEmail(srv, &quot;Test&quot;, &quot;This is a test sending&quot;, &quot;REDACTED@gmail.com&quot;)
    if err != nil {
        t.Error(err)
    }
</code></pre>
<p>Through research I have found that domain wide delegation is needed which I haved ensured is configured with the same scope I am using as evident of the Domain wide Delegation page screen shot below showing the same scope for the service account that was created:</p>
<p><a href="https://i.stack.imgur.com/V6a8L.png" rel="nofollow noreferrer"><img src="https://i.stack.imgur.com/V6a8L.png" alt="enter image description here" /></a></p>
<p>Furthermore, I know that my <code>ConnectToGmailAPI()</code> function should work because I used the same service account, same environmental variables, and the same config file to set up for a sheets api call which still works. The only thing that I changed between the two implimintations was the scopes in the <code>jwt.Config{}</code> to be <code>gmail.modify</code>. To my understanding the rest of the information should be the same because the service account that I am using is the same.</p>
