Title: How can I make the data inside of my Cart become persistent?.
Body: <p>I have a NextJS application that is using the ShopifyBuy SDK. I have been successfully able to implement a solution where I am able to fetch the products from Store and display them to the User. The user is also able to go to a product page and add the product to the cart.</p>
<p>However, when the user refreshes the page, the cart is reset, and the data does not persist. The code is below:</p>
<p><strong>context/cart.js:</strong></p>
<pre><code>import { createContext, useContext, useEffect, useReducer } from &quot;react&quot;;
import client from &quot;../lib/client&quot;;
import Cookies from &quot;js-cookie&quot;;

const CartStateContext = createContext();
const CartDispatchContext = createContext();

const SET_CART = &quot;SET_CART&quot;;

const initalState = {
  lineItems: [],
  totalPrice: 0,
  webUrl: &quot;&quot;,
  id: &quot;&quot;,
};

const reducer = (state, action) =&gt; {
  switch (action.type) {
    case SET_CART:
      return { ...state, ...action.payload };
    default:
      throw new Error(`Unknown action: ${action.type}`);
  }
};

export const CartProvider = ({ children }) =&gt; {
  const savedState = Cookies.get(&quot;cartState&quot;);
  const [state, dispatch] = useReducer(reducer, savedState || initalState);

  useEffect(() =&gt; {
    Cookies.set(&quot;cartState&quot;, state, { expires: 7 });
  }, [state]);

  useEffect(() =&gt; {
    getCart();
  }, []);

  const setCart = (payload) =&gt; dispatch({ type: SET_CART, payload });

  const getCart = async () =&gt; {
    try {
      const cart = await client.checkout.create();
      setCart(cart);
    } catch (err) {
      console.log(err);
    }
  };

  return (
    &lt;CartDispatchContext.Provider value={{ setCart }}&gt;
      &lt;CartStateContext.Provider value={{ state }}&gt;
        {children}
      &lt;/CartStateContext.Provider&gt;
    &lt;/CartDispatchContext.Provider&gt;
  );
};

export const useCartState = () =&gt; useContext(CartStateContext);
export const useCartDispatch = () =&gt; useContext(CartDispatchContext);
</code></pre>
