Title: Search if a string contains a substring in Javascript (partial search).
Body: <p>Yes I know we can use indexOf and includes or a regular expression to find weather a string is present in another string.</p>
<p>But we have a different requirement. We would like indexOf or includes function to return true even if partial string is matched not the whole world. Let me provide an example.</p>
<p>Let's say my username is &quot;Animation&quot;. The string the I am entering is &quot;sssrtAnimyt5678&quot;. Now as the string &quot;sssrtAnimyt5678&quot; contains &quot;Anim&quot; which is present in &quot;Animation&quot; we want the function to return true.</p>
<p>The problem with indexOf, includes and regular expression is it tries to find the whole word &quot;Animation&quot; but not the partial word &quot;Anim&quot;. I even used KMP Algorithm and found out that even KMP searches for &quot;Animation&quot; not &quot;Anim&quot;. Below is the implementation of KMP in Javascript.</p>
<pre><code>    var makeKMPTable = function(word) {
    if(Object.prototype.toString.call(word) == '[object String]' ) {
        word = word.split('');
    }
    var results = [];
    var pos = 2;
    var cnd = 0;

    results[0] = -1;
    results[1] = 0;
    while (pos &lt; word.length) {
        if (word[pos - 1] == word[cnd]) {
            cnd++;
            results[pos] = cnd;
            pos++;
        } else if (cnd &gt; 0) {
            cnd = results[cnd];
        } else {
            results[pos] = 0;
            pos++;
        }
    }
    return results;
};

var KMPSearch = function(string, word) {
    if(Object.prototype.toString.call(string) == '[object String]' ) {
        string = string.split('');
    }
    if(Object.prototype.toString.call(word) == '[object String]' ) {
        word = word.split('');
    }

    var index = -1;
    var m = 0;
    var i = 0;
    var T = makeKMPTable(word);

    while (m + i &lt; string.length) {
        if (word[i] == string[m + i]) {
            if (i == word.length - 1) {
                return m;
            }
            i++;
        } else {
            m = m + i - T[i];
            if (T[i] &gt; -1) {
                i = T[i];
            } else {
                i = 0;
            }
        }
    }
    return index;
};
console.log(KMPSearch(&quot;sssrtAnimyt5678&quot;, &quot;Animation&quot;)); // returns -1
</code></pre>
<p>So I would like to know if such kind of partial search is possible and if anybody can point me to such implementation details or algorithm it would be helpful.</p>
<p>Thanks in Advance.</p>

