        for (int j = 0; j &lt; width; j++)
        {
            if (j == 0 || j == width - 1)
                printf(&quot;#&quot;);
            else
            {
                if (i == fruitY &amp;&amp; j == fruitX)
                    printf(&quot;f&quot;);
                else
                    if (i == y &amp;&amp; j == x)
                        printf(&quot;o&quot;);
                    else
                    {

                        bool print = false;
                        for (int k = 0; k &lt; ctail; k++)
                        {

                            if (i == taily[k] &amp;&amp; j == tailx[k])
