    {

        printf(&quot;#&quot;);
    }
    printf(&quot;\n x is %d y is %d&quot;, fruitX, fruitY);
    printf(&quot;\n\n the score is %d\n\n&quot;,score);






}
void input()
{
    if(_kbhit())
        switch (_getch())
        {
