        }
}
void logic()
{
    int prevx = tailx[0];
    int prevy = taily[0];
    tailx[0] = x;
    taily[0] = y;
    int prev2x, prev2y;
    for (int i = 1; i &lt; ctail; i++)
    {
        prev2x = tailx[i];
        prev2y = taily[i];
        tailx[i] = prevx;
        taily[i] = prevy;
        prevx = prev2x;
        prevy = prev2y;

    }


    switch (dir)
    {
    case UP:y--;
        break;
    case DOWN:y++;
        break;
    case LEFT:x--;
        break;
    case RIGHT:x++;
        break;
    default:break;
    }
    if (x&lt;0 || x&gt;width )
