window.addEventListener(&quot;keyup&quot;, keyup)

function keyup() {
  keypressed = false;
};

window.addEventListener(&quot;touchstart&quot;, () =&gt; {
  keypressed = true;
});

window.addEventListener(&quot;touchend&quot;, () =&gt; {
