  let wrapper;
  let vuetify;

  beforeEach(() =&gt; {
    vuetify = createVuetify();
  });

  describe('dialog tests', () =&gt; {
    beforeEach(() =&gt; {
      wrapper = mount(HelloDialog, {
        global: {
          plugins: [vuetify],
        },
      });
    });

    test('test dialog', async () =&gt; {
      expect(wrapper.find('.dialog-content').exists()).toBeFalsy();
      await wrapper.find('.open-dialog-btn').trigger('click');
      console.log(wrapper.html());
      expect(wrapper.find('.dialog-content').exists()).toBeTruthy();
    });
  });
});
</code></pre>
<p>the last line in unit test is not working - dialog content is not displayed. Here is an output from wrapper.html() after button is clicked:</p>
<pre><code>&lt;div&gt;&lt;button type=&quot;button&quot; class=&quot;v-btn v-btn--elevated v-theme--light v-btn--density-default v-btn--size-default v-btn--variant-elevated open-dialog-btn&quot;&gt;&lt;span class=&quot;v-btn__overlay&quot;&gt;&lt;/span&gt;&lt;span class=&quot;v-btn__underlay&quot;&gt;&lt;/span&gt;
    &lt;!----&gt;&lt;span class=&quot;v-btn__content&quot; data-no-activator=&quot;&quot;&gt;click me please&lt;/span&gt;
    &lt;!----&gt;
    &lt;!----&gt;
  &lt;/button&gt;
  &lt;!----&gt;
  &lt;!--teleport start--&gt;
  &lt;!--teleport end--&gt;
&lt;/div&gt;

AssertionError: expected false to be truthy
    at ....../HelloDialog.spec.js:27:56
</code></pre>
<p>here is test section from <strong>vite.config.js</strong>:</p>
<pre><code>  test: {
    // https://vitest.dev/config/
    globals:true,
    environment: 'happy-dom',
    setupFiles: &quot;vuetify.config.js&quot;,
    deps: {
      inline: [&quot;vuetify&quot;],
    },
  },
</code></pre>
<p>and here is <strong>vuetify.config.js</strong>:</p>
<pre><code>global.CSS = { supports: () =&gt; false };
</code></pre>
<p>here some versions from <strong>package.json</strong>:</p>
<pre><code>  &quot;dependencies&quot;: {
    &quot;@mdi/font&quot;: &quot;7.1.96&quot;,
    &quot;@pinia/testing&quot;: &quot;^0.0.14&quot;,
    &quot;axios&quot;: &quot;^1.2.0&quot;,
    &quot;dotenv&quot;: &quot;^16.0.3&quot;,
    &quot;happy-dom&quot;: &quot;^8.1.1&quot;,
    &quot;jsdom&quot;: &quot;^20.0.3&quot;,
    &quot;lodash&quot;: &quot;^4.17.21&quot;,
