Title: Table keeps jumping back to top after assigning custom scroll position.
Body: <p>I'm using Vue 3 with a Vuetify table and whenever I modify data I have to fetch everything again. If you modify a cell inside row 123 and column 456 reconstructing the whole grid is annoying because the table scrollbars jump back to the start. I think a good solution for this would be to</p>
<ul>
<li>store the current scroll position</li>
<li>perform the write action</li>
<li>reassign the stored scroll position</li>
</ul>
<p>( any better suggestions are highly appreciated )</p>
<p>As a sidenote: Since Vuetify requires a fixed table height for fixed table headers I'm, calculating the height dynamically ( table should fill the rest of the page ).</p>
<p>I created the following example ( <a href="https://play.vuetifyjs.com/#" rel="nofollow noreferrer">Playground link</a> )</p>
<pre><code>&lt;script setup lang=&quot;ts&quot;&gt;
import { ref, nextTick, onMounted, watch } from &quot;vue&quot;;  

const mainContainerComponent = ref&lt;VMain&gt;();
const tableComponent = ref&lt;VTable&gt;();
const tableHeight: Ref&lt;number | undefined&gt; = ref(undefined);
const tableMatrix = ref([[]]);

onMounted(async () =&gt; {
  // we only want to scroll inside the table
  document.documentElement.classList.add(&quot;overflow-y-hidden&quot;);

  await loadData();
});

watch(tableMatrix, async () =&gt; {
  // Unset table height and wait for it to rerender
  tableHeight.value = undefined;

  await nextTick();

  if (!tableComponent.value) {
    return;
  }

  const mainContainerComponentRectangle = mainContainerComponent.value.$el.getBoundingClientRect();
  const tableRectangle = tableComponent.value.$el.getBoundingClientRect();
  const topOffset = tableRectangle.top;
  const bottomOffset = mainContainerComponentRectangle.bottom - tableRectangle.bottom;

  tableHeight.value = window.innerHeight - bottomOffset - topOffset;
});

async function loadData() {
  // destroy table
  tableMatrix.value = [];

  await nextTick();

  // fetch data
  const fetchedData = new Array(Math.floor(Math.random() * 300) + 50).fill(&quot;data&quot;);

  // calculate table matrix
  tableMatrix.value = [...fetchedData.map(x =&gt; [x])];
}

async function performWriteAction() {
  // send modify request here

  const { scrollLeft, scrollTop } = getTableScrollPosition();

  await loadData();

  // wait for the DOM to finish
  await nextTick();

  // try to restore the previous scroll position
  setTableScrollPosition(scrollLeft, scrollTop);
}

function getTableDOMElement() {
  return tableComponent.value?.$el.querySelector(&quot;.v-table__wrapper&quot;);
}

function getTableScrollPosition() {
  const { scrollLeft, scrollTop } = getTableDOMElement();

  console.log(`current scroll position =&gt; x: ${scrollLeft} | y: ${scrollTop}`);

  return { scrollLeft, scrollTop };
}

function setTableScrollPosition(scrollLeft: number, scrollTop: number) {
  const tableElement = getTableDOMElement();

  console.log(`scroll to =&gt; x: ${scrollLeft} | y: ${scrollTop}`);

  tableElement.scrollLeft = scrollLeft;
  tableElement.scrollTop = scrollTop;
}
&lt;/script&gt;

&lt;template&gt;
  &lt;v-app&gt;
    &lt;v-main ref=&quot;mainContainerComponent&quot;&gt;
      &lt;v-container&gt;
        &lt;v-btn @click=&quot;performWriteAction&quot;&gt;Modify data&lt;/v-btn&gt;
      &lt;/v-container&gt;

      &lt;v-table
        ref=&quot;tableComponent&quot;
        density=&quot;compact&quot;
        fixed-header
        :height=&quot;tableHeight&quot;
      &gt;
        &lt;thead&gt;
          &lt;tr&gt;
            &lt;th&gt;Col&lt;/th&gt;
          &lt;/tr&gt;
        &lt;/thead&gt;
        &lt;tbody&gt;
          &lt;tr v-for=&quot;(row, rowIndex) in tableMatrix&quot; :key=&quot;rowIndex&quot;&gt;
            &lt;template v-for=&quot;(cell, columnIndex) in row&quot; :key=&quot;columnIndex&quot;&gt;
              &lt;td&gt;{{ rowIndex }}&lt;/td&gt;
            &lt;/template&gt;
          &lt;/tr&gt;
        &lt;/tbody&gt;
      &lt;/v-table&gt;
    &lt;/v-main&gt;
  &lt;/v-app&gt;
&lt;/template&gt;
</code></pre>
<p>The problem with this code is that the table always jumps back to the start. If you scroll down to the center of the table and modify some data the scroll position is still wrong.</p>
<p>Do you have any ideas what's wrong or missing?</p>

Title: v-date-picker date format to DD-MM-YYYY vuetify.
Body: <p>I have a <strong>Vuetify</strong> date picker that loops through and I need to format the display date to <em>DD-MM-YYYY</em>. I tried with <strong>dayjs</strong> but it wasn't working.</p>
<p>The template:</p>
<pre><code>&lt;div v-for=&quot;(shareholder, i) in shareholders&quot;&gt;
  &lt;v-menu
    :ref=&quot;'dob'&quot;
    v-model=&quot;modals[i]&quot;
    :close-on-content-click=&quot;false&quot;
    :return-value.sync=&quot;shareholder.dateOfBirth&quot;
    transition=&quot;scale-transition&quot;
    offset-y
    &gt;
    &lt;template v-slot:activator=&quot;{ on, attrs }&quot;&gt;
      &lt;v-text-field
        v-model=&quot;shareholder.dateOfBirth&quot;
        v-bind=&quot;attrs&quot;
        v-on=&quot;on&quot;
        &gt;&lt;/v-text-field&gt;
    &lt;/template&gt;
    &lt;v-date-picker
      v-model=&quot;shareholders.origDate&quot;
      @input=&quot;$refs.dob[i].save(formatDate(shareholder.origDate))&quot;
      first-day-of-week=&quot;1&quot;
      &gt;&lt;/v-date-picker&gt;
  &lt;/v-menu&gt;
&lt;/div&gt;
</code></pre>
<pre><code>mounted: {
    this.shareholders.map((item) =&gt; {
    // save original date
    item.origDate = item.dateOfBirth
    // modify date of birth
    item.dateOfBirth = this.formatDate(item.dateOfBirth)
    })
} ,
methods: {
    formatDate(date) {
    if (!date) {
    return null
    }
    const [year, month, day] = date.split('-')
    return `${day}-${month}-${year}`
    }
} 
</code></pre>
<p>If I use <code>shareholders[i].dateOfBirth</code> in the template it works fine but the date format will be <em>YYYY-MM-DD</em>.</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false">
<div class="snippet-code">
<pre class="snippet-code-html lang-html prettyprint-override"><code>&lt;script src="https://cdnjs.cloudflare.com/ajax/libs/vue/2.5.17/vue.js"&gt;&lt;/script&gt;

&lt;div v-for="(shareholder, i) in shareholders"&gt;
  &lt;v-menu
    :ref="'dob'"
    v-model="modals[i]"
    :close-on-content-click="false"
    :return-value.sync="shareholder.dateOfBirth"
    transition="scale-transition"
    offset-y
    &gt;
    &lt;template v-slot:activator="{ on, attrs }"&gt;
      &lt;v-text-field
        v-model="shareholder.dateOfBirth"
        v-bind="attrs"
        v-on="on"
        &gt;&lt;/v-text-field&gt;
    &lt;/template&gt;
    &lt;v-date-picker
      v-model="shareholders.origDate"
      @input="$refs.dob[i].save(formatDate(shareholder.origDate))"
      first-day-of-week="1"
      &gt;&lt;/v-date-picker&gt;
  &lt;/v-menu&gt;
&lt;/div&gt;

&lt;script&gt;
 export default {
 data(){
  return {
    shareholders: [
      {dateOfBirth: '2011-04-12'},
      {dateOfBirth: '2023-02-10'}
    ]
  }
},
mounted: {
    this.shareholders.map((item) =&gt; {
    // save original date
    item.origDate = item.dateOfBirth
    // modify date of birth
    item.dateOfBirth = this.formatDate(item.dateOfBirth)
    })
} ,
methods: {
    formatDate(date) {
    if (!date) {
    return null
    }
    const [year, month, day] = date.split('-')
    return `${day}-${month}-${year}`
    }
}
 }
&lt;/script&gt;</code></pre>
</div>
</div>
</p>

