    cout &lt;&lt; name &lt;&lt; &quot; wrong at &quot; &lt;&lt; i &lt;&lt; &quot; &quot; &lt;&lt; original[i] &lt;&lt; &quot; &quot; &lt;&lt; decoded[i] &lt;&lt; &quot;\n&quot;;
