  memset(original, 0, n_msg * 8);
  memset(decoded, 0, n_msg * 8);
  memset(dummy_array, 0, N_DUMMY * 8);

  int n_test = 10;
  constexpr int L = 4;
  string names[L] = {&quot;original&quot;, &quot;soonts&quot;, &quot;aqrit&quot;, &quot;leb&quot;};
  int64_t total_costs[L] = {0, 0, 0, 0};

  for (int t = 0; t &lt; n_test; t++) {    
    gen_data();
    double ratio_original = encode_all(0);
    int64_t costs[L];

    costs[0] = test(decode_original, names[0]);
    costs[1] = test(decode_soonts, names[1]);

    double ratio_aqrit = encode_all(1);
    costs[2] = test(decode_aqrit, names[2]);

    double ratio_leb = encode_all(2);
    costs[3] = test(decode_leb, names[3]);

    if (t == 0) {
      cout &lt;&lt; &quot;Compression ratios: &quot; &lt;&lt; ratio_original &lt;&lt; &quot; &quot; &lt;&lt; ratio_aqrit &lt;&lt; &quot; &quot; &lt;&lt; ratio_leb &lt;&lt; &quot;\n&quot;;
    }

    cout &lt;&lt; t &lt;&lt; &quot;: &quot;;
    for (int i = 0; i &lt; L; i++) {
      cout &lt;&lt; (double(costs[i]) / 1'000'000) &lt;&lt; &quot; &quot;;
      total_costs[i] += costs[i];
    }
    cout &lt;&lt; &quot;\n&quot;;
  }

  vector&lt;string&gt; headers = {&quot;name&quot;, &quot;cost (ms)&quot;, &quot;cost/int64 (ns)&quot;, &quot;cost/byte (ns)&quot;};
  printTableRow(headers, 15);
  for (int i = 0; i &lt; L; i++) {    
    double average_cost_ms = double(total_costs[i]) / n_test / 1'000'000;
    double cost_int64 = double(total_costs[i]) / (n_msg * n_test);
    double cost_byte = cost_int64 / 8;

    vector&lt;string&gt; row;
    row.push_back(names[i]);
    row.push_back(to_string(average_cost_ms));
    row.push_back(to_string(cost_int64));
    row.push_back(to_string(cost_byte));
    printTableRow(row, 15);
  }

  return 0;
}
</code></pre>
<p><strong>Edit:</strong> I've just found out that someone discovered <a href="https://github.com/lemire/streamvbyte/tree/master#format-specification" rel="nofollow noreferrer">pretty much the same encode/decode format</a> (but for int32) in 2017. What a fun coincidence, where 2 people independently &quot;invent&quot; the same thing at 2 different times :D</p>
<p>2nd version of Soonts' answer (<code>func</code>, <code>inl func</code>, <code>vpgather</code>) code <a href="https://gist.github.com/Const-me/e897e4565b2c6a2e69d8b5d2c1457730" rel="nofollow noreferrer">here</a>. It looks cleaner, and doesn't read past the end of input buffer, but measurably slower, so I'm keeping the 1st version.</p>
<ul>
<li><code>func</code>: this version doesn't require a decoder object. <code>force_inline = 0, use_gather = 0</code></li>
<li><code>inl func</code>: <code>force_inline = 1, use_gather = 0</code></li>
<li><code>vpgather</code>: <code>force_inline = 0, use_gather = 1</code></li>
</ul>
<p>Compile command: <code>g++ -o main test.cpp -std=c+=17 -O3 -mavx2 -mlzcnt -march=native</code></p>
<p>Benchmark on . <code>-march=native</code> gives measurable performance boost (~8% best case)</p>
