Title: What is the problem with my code(bandwidth limitation)?.
Body: <p>I'm now making a broadcasting web using socket.io and webRTC. I can successly broadcast the video stream from the broadcaster to the viewers. However, I want to limit the bandwidth of the viewers/broadcasters so that if more viewers/broadcaster join the server, the quality of the video can be reduced to allow more users. It seems that I cannot change the videoWidth and videoHeight as they are read-only so I cannot directly change the resolution of the video. So I wonder if I can setBitrate to limit the performance of the video.</p>
<p>server.js</p>
<pre><code>const express = require(&quot;express&quot;);
const app = express();

let broadcaster;
const port = 4000;

const http = require(&quot;http&quot;);
const server = http.createServer(app);

const io = require(&quot;socket.io&quot;)(server);
app.use(express.static(__dirname + &quot;/public&quot;));

io.sockets.on(&quot;error&quot;, e =&gt; console.log(e));
io.sockets.on(&quot;connection&quot;, socket =&gt; {
  socket.on(&quot;broadcaster&quot;, () =&gt; {
    broadcaster = socket.id;
    socket.broadcast.emit(&quot;broadcaster&quot;);
  });
  socket.on(&quot;watcher&quot;, () =&gt; {
    socket.to(broadcaster).emit(&quot;watcher&quot;, socket.id);
  });
  socket.on(&quot;offer&quot;, (id, message) =&gt; {
    socket.to(id).emit(&quot;offer&quot;, socket.id, message);
  });
  socket.on(&quot;answer&quot;, (id, message) =&gt; {
    socket.to(id).emit(&quot;answer&quot;, socket.id, message);
  });
  socket.on(&quot;candidate&quot;, (id, message) =&gt; {
    socket.to(id).emit(&quot;candidate&quot;, socket.id, message);
  });
  socket.on(&quot;disconnect&quot;, () =&gt; {

    if (socket.id === broadcaster) {

      socket.broadcast.emit(&quot;disconnectServer&quot;);
    }

    socket.broadcast.emit(&quot;disconnectPeer&quot;, socket.id);
  });
});
server.listen(port, () =&gt; console.log(`Server is running on port ${port}`));
</code></pre>
<p>broadcast.js</p>
<pre><code>const peerConnections = {};
const config = {
  iceServers: [
    {
      &quot;urls&quot;: &quot;stun:stun.l.google.com:19302&quot;
    }
  ],
  sdpSemantics: &quot;plan-b&quot;
};

function setBitrate(sdp, bitrate) {
  return sdp.replace(/a=mid:(audio|video)\r\n/g, `a=mid:$1\r\nb=AS:${bitrate}\r\n`);
}



const socket = io.connect(window.location.origin);
