Title: Unix Domain Sockets mismatch in the messages sent and received.
Body: <p>I have created pretty basic client and server programs that use Unix-domain sockets to send messages from the server and the messages are captured by the client</p>
<p>The problem that I am receiving is that I am not able to capture all the messages sent from the server on the client-side</p>
<p>This is my server-side code</p>
<pre><code>#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;string.h&gt;
#include &lt;sys/types.h&gt;
#include &lt;sys/socket.h&gt;
#include &lt;sys/un.h&gt;
#include &lt;unistd.h&gt;
#include &lt;arpa/inet.h&gt;
#include &lt;time.h&gt;
#include &lt;sys/time.h&gt;

#define NAME &quot;uds_socket&quot;
#define DATA &quot;Test Message&quot;
char buf[1024];

int createAndBindSocket() {
    int server_socket;
    struct sockaddr_un server_address;

    unlink(NAME);

    server_socket = socket(AF_UNIX, SOCK_STREAM, 0);
    if (server_socket == -1) {
        perror(&quot;Socket creation failed&quot;);
        exit(EXIT_FAILURE);
    }
    else printf(&quot;Socket creation successful\n&quot;);

    int reuse = 1;
    if (setsockopt(server_socket, SOL_SOCKET, SO_REUSEADDR, &amp;reuse, sizeof(reuse)) == -1) perror(&quot;Error : &quot;);
    else printf(&quot;Socket options set\n&quot;);

    server_address.sun_family = AF_UNIX;
    strcpy(server_address.sun_path, NAME);

    if (bind(server_socket, (struct sockaddr*)&amp;server_address, sizeof(server_address)) == -1) {
        perror(&quot;Binding failed&quot;);
        close(server_socket);
        exit(EXIT_FAILURE);
    }
    else {
        printf(&quot;Socket binding successful with name %s\n&quot;, server_address.sun_path);
    }

    if (listen(server_socket, 5) == -1) {
        perror(&quot;Listening failed&quot;);
        close(server_socket);
        exit(EXIT_FAILURE);
    }
    else printf(&quot;Listening ...\n&quot;);

    return server_socket;
}

int handleClientRequest(int server_socket) {
    int client_socket;
    client_socket = accept(server_socket, 0, 0);
    if(client_socket == -1) {
        perror(&quot;Accepting failed&quot;);
        close(server_socket);
        exit(EXIT_FAILURE);
    }
    else {
        printf(&quot;Connected to client\n&quot;);
    }
    return client_socket;
}

void sendMessage(int client_socket) {
    char* buf = malloc(12);
    for(int i=0; i&lt;5; i++) {
        snprintf(buf, 12, &quot;Hello %d&quot;, i);
        if (send(client_socket, buf, sizeof(buf), 0) &lt; 0) {
            perror(&quot;writing on stream socket&quot;);
            break;
        }
        else {
            printf(&quot;Sending message ...\n&quot;);
        }
    }
}

int main(int argc, char* argv[]) { 
    int server_socket = createAndBindSocket();
    while(1) {
        int client_socket = handleClientRequest(server_socket);
        sendMessage(client_socket);
        close(client_socket);
    }
    unlink(NAME);
    close(server_socket);

    return 0;
}
</code></pre>
<p>And this is my client-side code</p>
<pre><code>#include &lt;sys/types.h&gt;
#include &lt;sys/socket.h&gt;
#include &lt;sys/un.h&gt;
#include &lt;stdio.h&gt;
#include &lt;string.h&gt;
#include &lt;unistd.h&gt;
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;

#define DATA &quot;Test Message&quot;
char buf[1024];

int main(int argc, char* argv[]) {
    int client_socket;
    struct sockaddr_un server_address;
    char buf[1024];

    client_socket = socket(AF_UNIX, SOCK_STREAM, 0);
    if (client_socket == -1) {
        perror(&quot;Socket creation failed&quot;);
        exit(EXIT_FAILURE);
    }
    server_address.sun_family = AF_UNIX;
