Title: How to replicate the frowNow function in moment.js in native js Date?.
Body: <p>Trying to replicate the fromNow function in moment.js with native JS Date object but getting a date that is one day behind. I'm passing the value as unix it gives the right output when i use moment but giving a wrong date when i use Native JS date</p>
<pre><code>const fromNow = targetUnixTimestampInSeconds =&gt; {
  const now = new Date();
  const nowInSeconds = Math.floor(now.getTime()/1000);

  // Convert the target Unix timestamp to local time in seconds
  const targetDate = new Date(targetUnixTimestampInSeconds);
  const targetOffsetInSeconds = targetDate.getTimezoneOffset() * 60;
  const targetInSeconds =
    Math.floor(targetDate.getTime() / 1000) + targetOffsetInSeconds;

  const diffInSeconds = nowInSeconds - targetInSeconds;
  if (diffInSeconds &lt; 60) {
    return `${diffInSeconds} second${diffInSeconds === 1 ? &quot;&quot; : &quot;s&quot;} ago`;
  } else if (diffInSeconds &lt; 3600) {
    const minutes = Math.floor(diffInSeconds / 60);
    return `${minutes} minute${minutes === 1 ? &quot;&quot; : &quot;s&quot;} ago`;
  } else if (diffInSeconds &lt; 86400) {
    const hours = Math.floor(diffInSeconds / 3600);
    return `${hours} hour${hours === 1 ? &quot;&quot; : &quot;s&quot;} ago`;
  } else if (diffInSeconds &lt; 2592000) {
    const days = Math.floor(diffInSeconds / 86400);
    return `${days} day${days === 1 ? &quot;&quot; : &quot;s&quot;} ago`;
  } else if (diffInSeconds &lt; 31536000) {
    const months = Math.floor(diffInSeconds / 2592000);
    return `${months} month${months === 1 ? &quot;&quot; : &quot;s&quot;} ago`;
  } else {
    const years = Math.floor(diffInSeconds / 31536000);
    return `${years} year${years === 1 ? &quot;&quot; : &quot;s&quot;} ago`;
  }
};
</code></pre>
<p>this is the function that I have written,</p>
<pre><code>const targetUnixTimestampInSeconds = 1689875101441 / 1000; // Convert to seconds
console.log(fromNow(targetUnixTimestampInSeconds)); //this gives 2 days ago
console.log(moment(1689875101441).fromNow()); // this gives 3 days ago
</code></pre>
<p>I'm expecting the function to give the same output as moment js</p>

