import { PassportStrategy } from &quot;@nestjs/passport&quot;;
import { Inject, Injectable, UnauthorizedException } from &quot;@nestjs/common&quot;;
import { RidersService } from &quot;../riders/riders.service&quot;;
import { DriversService } from &quot;../drivers/drivers.service&quot;;

@Injectable()
export class JwtStrategy extends PassportStrategy(Strategy) {
  constructor(
    private readonly riderService: RidersService,
    private readonly driverService: DriversService,
    @Inject(ConfigService) config: ConfigService,
  ) {
    super({
      jwtFromRequest: ExtractJwt.fromAuthHeaderAsBearerToken(),
      ignoreExpiration: false,
      secretOrKey: config.get(&quot;JWT_SECRET&quot;),
    });
  }

  async validate(payload: {
    role: string;
    iat: number;
    exp: number;
    phone: string;
  }) {
    if (!payload) {
      throw new UnauthorizedException();
    }

    const service = {
      rider: this.riderService,
      driver: this.driverService,
    };

    const user = await service[payload.role].findByAny(payload.phone);
    if (!user) {
      throw new UnauthorizedException();
    }

    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    const { iat, exp, ...rest } = payload;

    return rest;
  }
}

</code></pre>
<p>Now here is my AuthService stripped off</p>
<pre><code>import { InjectModel } from &quot;@nestjs/mongoose&quot;;
import { Injectable, Logger, HttpException } from &quot;@nestjs/common&quot;;
import { JwtService } from &quot;@nestjs/jwt&quot;;
