Title: What would the new way of passport deserialization look like?.
Body: <p>In am following a simple MVC tutorial <a href="https://blog.logrocket.com/building-structuring-node-js-mvc-application/" rel="nofollow noreferrer">https://blog.logrocket.com/building-structuring-node-js-mvc-application/</a> to build a login authentication system.</p>
<p>Till a few days back, I had a working serialize and deserialize section in my code</p>
<pre><code>passport.serializeUser((user, done) =&gt; {
    done(null, user.id);
  });

  passport.deserializeUser(async (id, done) =&gt; {

    User.findById(id, (error, user) =&gt; {
      done(error, user);
    });

  });
</code></pre>
<p>Recently running the code, I started getting the error <code>Model.findById() no longer accepts a callback</code>
Now I understand that the new way would be using write async and await. However, I couldn't find a sample online that guides me towards how to come about writing the code. Could I please be helped here?</p>

Title: Problem having multiple user sessions in express-session.
Body: <p>I have a problem for a few days and I could not find a solution, I have searched forums, documentation and nothing.I have a website developed in nodejs, using express-session and passport for session management and user authentication.</p>
<p>My problem is that having two different users connected to my website and do an action simultaneously, the website is loaded but with the session of the last user who has performed the action. In other words, it uses a session for the rest of the users who have performed the action simultaneously.</p>
<p>This is my base configuration of my website</p>
<pre><code>const express = require('express');
const morgan = require('morgan');
const path = require('path');
const exphbs = require('express-handlebars');
const session = require('express-session');
const validator = require('express-validator');
const passport = require('passport');
const flash = require('connect-flash');
const MySQLStore = require('express-mysql-session')(session);
const bodyParser = require('body-parser');
var cookieParser = require('cookie-parser');
const helmet = require(&quot;helmet&quot;);

const { database } = require('./keys');

// Intializations
const app = express();
require('./lib/passport');

// Settings
app.set('port', process.env.PORT || 4000);
app.set('views', path.join(__dirname, 'views'));
app.engine('.hbs', exphbs({
  defaultLayout: 'main',
  layoutsDir: path.join(app.get('views'), 'layouts'),
  partialsDir: path.join(app.get('views'), 'partials'),
  extname: '.hbs',
  helpers: require('./lib/handlebars')
}))
app.set('view engine', '.hbs');

// Middlewares
app.use(morgan('dev'));
app.use(bodyParser.json());
app.use(bodyParser.urlencoded({extended: false}));
app.use(cookieParser());
app.use(session({
  secret: '1234567789',
  key: &quot;namecookie&quot;,
  resave: true,
  saveUninitialized: true,
  store: new MySQLStore(database),
  cookie: {
    secure: false,
    maxAge: 150000,
    httpOnly: false
  }
}));

app.use(function (req, res, next) {
  res.locals.session = req.session;
  next();
});

app.use(flash());
app.use(passport.initialize());
app.use(passport.session());
app.use(validator());

// Global variables
app.use((req, res, next) =&gt; {
  app.locals.message = req.flash('message');
  app.locals.success = req.flash('success');
  app.locals.user = req.user;
  next();
});

// Routes
app.use(require('./routes/index'));
app.use(require('./routes/authentication'));
app.use('/links', require('./routes/links'));

// Public
app.use(express.static(path.join(__dirname, 'public')));
app.use(helmet());

// Starting
app.listen(app.get('port'), () =&gt; {
  console.log('Server is in port', app.get('port'));
});
</code></pre>

