  if (req.method !== &quot;POST&quot;) {
    return res.status(405).end();
  }
  try {
    const { email, name, password } = req.body;
    const existingUser = await prismadb.user.findUnique({ where: { email } });
    if (existingUser) {
      return res
        .status(422)
        .json({ error: &quot;Email is already taken&quot;, cause: &quot;email&quot; });
    }

    const hashedPassword = await bcrypt.hash(password, 12);
    const user = await prismadb.user.create({
      data: {
        email,
        name,
        hashedPassword,
        image: &quot;&quot;,
        emailVerified: new Date(),
        recentSearches: [],
        liked: {},
        playlists: { create: [] },
      },
    });

    return res.status(200).json(user);
  } catch (error) {
    console.log(error);
    return res.status(400).json(error);
  }
}
</code></pre>
<p>I tried using create and createMany attribute but nothing worked, I realized that if i use Json[] instead of Playlist[] it works but i want to have Playlists[] as a type.
I expect to create a user with empty array of playlists field in database.</p>
<p>The way i want then update my playlists field</p>
<pre><code>const createdPlaylist = await prismadb.playlist.create({
      data: { name: playlistName, tracks: [], userId: user.id },
    });

const result = await prismadb.user.update({
    where: { id: user.id },
    data: { playlists: { connect: { id: createdPlaylist.id } } },
});
</code></pre>

