in vec2 v_texcoord;
in float v_texindex;

uniform sampler2DArray u_textures;

out vec4 color;

void main()
{
        color = texture(u_textures, vec3(v_texcoord.xy, v_texindex));
}
</code></pre>
<p>Where the Shader class, which is not shown simply parses the shader file with both, vertex and fragment part. Now both textures are distinguished via last attrib pointer, one float 0.0f for first texture, 1.0f for second one. But in the output, I only see 2 black squares (which should have the textures in it), so how to use the <code>GL_TEXTURE_2D_ARRAY</code> to load both textures (and thus calling 2 times <code>Bind2DArrayTexture</code>, since that is the target, I have no way how to make an actual array of both textures).</p>
<p>Now please do not mark this as duplicate to the referenced answer (provided at the beginning of this question). Because there is only shown the usage of the shader (which I did), but no actual usage of C++ side (using the <code>GL_TEXTURE_2D_ARRAY</code> for 2 distinct textures). So it won't answer my question and thus my question cannot be duplicate</p>
<p>PS: for completness, here is the shader class:</p>
<p><em>header</em>:</p>
<pre><code>#ifndef TEST_SHADER_HPP
#define TEST_SHADER_HPP

#include &lt;string&gt;

#include &lt;glm/glm.hpp&gt;

class Shader {
public:
    explicit Shader(const std::string&amp; filepath);

    void Bind() const;

    void SetInt(const std::string&amp; name, int value) const;

    void SetIntArray(const std::string&amp; name, int *values, int count);

    void SetFloat(const std::string&amp; name, float value) const;

    void SetVec3(const std::string&amp; name, const glm::vec3&amp; vec) const;

    void SetVec4(const std::string&amp; name, const glm::vec4&amp; vec) const;

    void SetMat4(const std::string&amp; name, const glm::mat4&amp; mat) const;

private:
    static void CheckCompileErrors(uint32_t shader_id, const std::string&amp; type, const std::string&amp; filepath);

    uint32_t id_;
};

#endif //TEST_SHADER_HP
</code></pre>
<p><em>source</em>:</p>
<pre><code>#include &lt;test/main/shader.hpp&gt;

#include &lt;iostream&gt;
#include &lt;fstream&gt;
#include &lt;sstream&gt;

#include &lt;glad/glad.h&gt;

void Shader::CheckCompileErrors(uint32_t shader_id, const std::string&amp; type, const std::string&amp; filepath) {
    int success;
    char infoLog[1024];
    if (type != &quot;PROGRAM&quot;) {
        glGetShaderiv(shader_id, GL_COMPILE_STATUS, &amp;success);
        if (!success) {
            glGetShaderInfoLog(shader_id, 1024, nullptr, infoLog);
            std::cout &lt;&lt; &quot;ERROR::SHADER::COMPILATION_ERROR of type: &quot; &lt;&lt; type &lt;&lt; &quot;\n&quot; &lt;&lt; infoLog &lt;&lt; &quot;filepath: &quot;
                      &lt;&lt; filepath;
        }
    } else {
        glGetProgramiv(shader_id, GL_LINK_STATUS, &amp;success);
        if (!success) {
            glGetProgramInfoLog(shader_id, 1024, nullptr, infoLog);
            std::cout &lt;&lt; &quot;ERROR::PROGRAM_LINKING_ERROR of type: &quot; &lt;&lt; type &lt;&lt; &quot;\n&quot; &lt;&lt; infoLog &lt;&lt; &quot;filepath: &quot;
                      &lt;&lt; filepath;
        }
    }
}

Shader::Shader(const std::string&amp; filepath) {
    // 1. divide vertex and fragment part
    enum class ShaderType {
        NONE = -1, VERTEX = 0, FRAGMENT = 1
    };
    std::ifstream stream(filepath);
    std::string line;
    std::stringstream ss[2];
    ShaderType type = ShaderType::NONE;
    while (getline(stream, line)) {
        if (line.find(&quot;#type&quot;) != std::string::npos) {
            if (line.find(&quot;vertex&quot;) != std::string::npos) {
                type = ShaderType::VERTEX;
            } else if (line.find(&quot;fragment&quot;) != std::string::npos) {
                type = ShaderType::FRAGMENT;
            } else {
                std::cout &lt;&lt; &quot;Unknown shader: &quot; &lt;&lt; line &lt;&lt; '\n';
            }
        } else {
            if (type == ShaderType::NONE) {
                std::cout &lt;&lt; &quot;No shader defined&quot; &lt;&lt; '\n';
            } else {
                ss[(int) type] &lt;&lt; line &lt;&lt; '\n';
            }
        }
    }
    std::string vertex_code = ss[(int) ShaderType::VERTEX].str();
    std::string fragment_code = ss[(int) ShaderType::FRAGMENT].str();

    // 2. convert, compile and link sources to shader program
    // 2.1 convert string to c str
    const char *vertex_str = vertex_code.c_str();
    const char *fragment_str = fragment_code.c_str();
    // 2.2.1 vertex shader
    uint32_t vertex_id = glCreateShader(GL_VERTEX_SHADER);
    glShaderSource(vertex_id, 1, &amp;vertex_str, nullptr);
    glCompileShader(vertex_id);
    CheckCompileErrors(vertex_id, &quot;VERTEX&quot;, filepath);
    // 2.2.2 fragment shader
    uint32_t fragment_id = glCreateShader(GL_FRAGMENT_SHADER);
    glShaderSource(fragment_id, 1, &amp;fragment_str, nullptr);
    glCompileShader(fragment_id);
    CheckCompileErrors(fragment_id, &quot;FRAGMENT&quot;, filepath);
    // 2.3 shader program
    id_ = glCreateProgram();
    glAttachShader(id_, vertex_id);
    glAttachShader(id_, fragment_id);
    glLinkProgram(id_);
    CheckCompileErrors(id_, &quot;PROGRAM&quot;, filepath);
    // 2.4 delete the shaders as they're linked into program and no longer necessary
    glDeleteShader(vertex_id);
    glDeleteShader(fragment_id);
}

void Shader::Bind() const {
    glUseProgram(id_);
}

void Shader::SetInt(const std::string&amp; name, int value) const {
    glUniform1i(glGetUniformLocation(id_, name.c_str()), value);
}

void Shader::SetIntArray(const std::string&amp; name, int *values, int count) {
    glUniform1iv(glGetUniformLocation(id_, name.c_str()), count, values);
}

void Shader::SetFloat(const std::string&amp; name, float value) const {
    glUniform1f(glGetUniformLocation(id_, name.c_str()), value);
}

void Shader::SetVec4(const std::string&amp; name, const glm::vec4&amp; vec) const {
    glUniform4f(glGetUniformLocation(id_, name.c_str()), vec.x, vec.y, vec.z, vec.w);
}

void Shader::SetVec3(const std::string&amp; name, const glm::vec3&amp; vec) const {
    glUniform3f(glGetUniformLocation(id_, name.c_str()), vec.x, vec.y, vec.z);
}

void Shader::SetMat4(const std::string&amp; name, const glm::mat4&amp; mat) const {
    glUniformMatrix4fv(glGetUniformLocation(id_, name.c_str()), 1, GL_FALSE, &amp;mat[0][0]);
}
</code></pre>

Title: Why do fragment shader colors an image based on the fragment coordinate as a saturated color?.
Body: <p>The following code colors a image based on its fragment positions:</p>
<p>Vertex shader:</p>
<pre><code>varying vec2 vXY;   
void main(void) {
    vXY = position.xy;
    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}
</code></pre>
<p>Fragment shader:</p>
<pre><code>precision mediump float;
varying vec2 vXY;       
void main(void) {   
    vec4 color = vec4(0.0, 0.0, 0.0, 1.0);
    color.x = vXY.x;
    color.y = vXY.y;            
    gl_FragColor = color;
}
</code></pre>
<p>It separates the image into 4 squares of colors, as the picture bellow:</p>
<p><a href="https://i.stack.imgur.com/egOdz.png" rel="nofollow noreferrer"><img src="https://i.stack.imgur.com/egOdz.png" alt="enter image description here" /></a></p>
<p>From this, I can clearly see the cartesian coordinate system, which is fine, but what I don't understand is: why is the brightness of the colors as if it were constant 1.0?</p>
<p>From my understanding, since the range of the (x, y) coordinates is from -1 to 1 in the real numbers domain, then each square of color should get gradually brighter as the position changes, but this does not happen. Why?</p>

Title: How to make a frosted glass effect on SceneKit.
Body: <p>On my SceneKit node, I want to apply a frosted glass effect like this:</p>
<p><a href="https://www.shadertoy.com/view/WdSGz1" rel="nofollow noreferrer">https://www.shadertoy.com/view/WdSGz1</a></p>
<p>This shader takes a texture as input and outputs a &quot;blurry&quot; version of the texture. What I want is to create a SCNProgram() and apply it to the material of one my node so that it takes this frosted glass texture.</p>
<p>I tried reproducing this with a metal shader but I am not very familiar with how it works. This is what I wrote:</p>
<pre><code>#include &lt;metal_stdlib&gt;
using namespace metal;
#include &lt;SceneKit/scn_metal&gt;

struct NodeBuffer {
    float4x4 modelTransform;
    float4x4 modelViewProjectionTransform;
    float4x4 modelViewTransform;
    float4x4 normalTransform;
    float2x3 boundingBox;
};

struct MyNodeBuffer {
    float4x4 modelTransform;
    float4x4 inverseModelTransform;
    float4x4 modelViewTransform;
    float4x4 inverseModelViewTransform;
    float4x4 normalTransform;
    float4x4 modelViewProjectionTransform;
    float4x4 inverseModelViewProjectionTransform;
};

struct VertexInput {
    float3 position  [[attribute(SCNVertexSemanticPosition)]];
    float2 uv [[attribute(SCNVertexSemanticTexcoord0)]];
};

struct VertexOut {
    float4 position [[position]];
    float2 uv;
};

vertex VertexOut vertexFunction(VertexInput in [[ stage_in ]], constant NodeBuffer&amp; scn_node [[buffer(1)]]) {
    VertexOut out;
    out.position = scn_node.modelViewProjectionTransform * float4(in.position, 1.0);
    out.uv = in.uv;
    return out;
};

float stepfun(float x) {
    return (sign(x) + 1.0) / 2.0;
}

float square(float2 pos) {
    return (stepfun(pos.x + 1.0) * stepfun(1.0 - pos.x)) *
        (stepfun(pos.y + 1.0) * stepfun(1.0 - pos.y));
};

constexpr sampler textureSampler(coord::normalized, filter::linear, address::repeat);

float2 dist(float2 pos, texture2d&lt;float,access::sample&gt; texture [[ texture(0) ]])
{
    float2 offset = pos;
    return pos + square((offset - 0.5) * 3.0) * texture.sample(textureSampler, (offset - 0.5) * 5.0).xy * 0.05;
}

fragment float4 fragmentFunction(VertexOut out [[ stage_in ]],
                            texture2d&lt;float, access::sample&gt; texture [[ texture(0) ]],
                            device float3 *resolution [[ buffer(0) ]])
{
    float2 uv = out.uv / resolution[0].xy;
    float4 tex = texture.sample(textureSampler, dist(uv, texture));
    tex.a = 0.5;
    return tex;
}
</code></pre>
<p>However, I need to give a texture as input to my fragmentFunction and I don't know what this is supposed to be. I would like it to be the texture my node would have without the shader.</p>

