Title: React component keeps re-rendering whenever screen is minimized or another tab is opened.
Body: <p>I have a component in my portfolio website that creates a diagonally moving circle every couple of seconds. The problem is that when I minimize the screen or change the tab and come back after a minute, many circles will be created at the same time and the screen gets filled with them. I am not sure why this happens.</p>
<p>You can see the effect live in my website: <a href="https://khaledalhariri.com" rel="nofollow noreferrer">https://khaledalhariri.com</a></p>
<p>Currently I have it set to have 6 circles at most in the screen. So when I minimize the window and open it after a minute, 6 circles are created at the same time which is an issue.. if I didnt set that limit of 6 circles then countless circles would have been created at the same time.</p>
<p>Code:</p>
<pre><code>import { useEffect, useRef } from 'react';
import './banner-skills.component.css';
import SKILLS_DATA, { Skill } from '../../data/skills';

const BannerSkills = () =&gt; {
  const CREATE_CIRCLE_MS = 4500;
  const CREATE_CIRCLE_MS_MOBILE = 7000;
  const ARRAY_OF_SKILLS: Skill[] = [];
  const isFirstRender = useRef(true);

  useEffect(() =&gt; {
    const skillsContainer = document.getElementsByClassName('banner-skills-container')[0];
    let minScreenSize = window.screen.width * 0.08;
    let maxScreenSize = window.screen.width * 0.85;
    let maxCircles = 6;
    let prevInitPos = Math.floor(Math.random() * maxScreenSize) - minScreenSize;

    const createDiagonalCircle = () =&gt; {
      if(window.screen.width &lt;= 500) {
        minScreenSize = window.screen.width * 0.8;
        maxCircles = 4;
      }
      else {
        minScreenSize = window.screen.width * 0.08;
        maxCircles = 6;
      }

      if(ARRAY_OF_SKILLS.length &gt;= maxCircles) {
        return;
      }

      const circle = document.createElement('div');
      circle.classList.add('skill-circle');
      skillsContainer.appendChild(circle);
      const logo = document.createElement('img');
      let randomSkill = SKILLS_DATA[Math.floor(Math.random() * SKILLS_DATA.length)];

      while(ARRAY_OF_SKILLS.indexOf(randomSkill) &gt;= 0) {
        randomSkill = SKILLS_DATA[Math.floor(Math.random() * SKILLS_DATA.length)];
      }

      logo.src = randomSkill.img;
      ARRAY_OF_SKILLS.push(randomSkill);
      circle.appendChild(logo);

      let size = Math.floor(Math.random() * 70) + 70;
      circle.style.width = size + 'px';
      circle.style.height = size + 'px';

      let posTop = -150;
      let posLeft = Math.floor(Math.random() * maxScreenSize) - minScreenSize;

      while(Math.abs(posLeft - prevInitPos) &lt; (window.screen.width * 0.13)) {
        posLeft = Math.floor(Math.random() * maxScreenSize) - minScreenSize;
      }

      prevInitPos = posLeft;
      let moveCirclesInterval = setInterval(frame, size - (size * 0.65));

      function frame() {
        if (posTop === 500) {
          skillsContainer.removeChild(circle);
          ARRAY_OF_SKILLS.splice(ARRAY_OF_SKILLS.indexOf(randomSkill), 1);
          clearInterval(moveCirclesInterval);
        } else {
          posTop++;
          posLeft++;
          circle.style.top = posTop + 'px';
          circle.style.left = posLeft + 'px';
          circle.style.visibility = 'visible';
        }
      }
      isFirstRender.current = false;
    }

    if(isFirstRender.current === true) {
      createDiagonalCircle();
      if(window.screen.width &lt;= 500) {
        let spawnCirclesInterval = setInterval(createDiagonalCircle, CREATE_CIRCLE_MS_MOBILE);
        return () =&gt; clearInterval(spawnCirclesInterval); 
      }
      else {
        let spawnCirclesInterval = setInterval(createDiagonalCircle, CREATE_CIRCLE_MS);
        return () =&gt; clearInterval(spawnCirclesInterval); 
      } 
    }
  }, [])

  return (
    &lt;div className=&quot;banner-skills-container&quot;&gt;&lt;/div&gt;
  )
}

export default BannerSkills
</code></pre>
<p>The circles are created in the useEffect and I have tried to find out if the page is being re-redenderd or not to stop it but I didn't find anything to work.</p>

Title: how to adjust canvas filter blur depending on device size.
Body: <p>I am trying to apply a blur to a canvas and I am trying to apply it with the same strength on every device.</p>
<pre class="lang-js prettyprint-override"><code>    // this.#blur is usually 7
    const ctx = this.#canvas.getContext(&quot;2d&quot;);
    ctx.filter = &quot;blur(&quot; + this.#blur + &quot;px)&quot;;
    const draw_2DCanvas = () =&gt; {
        ctx.clearRect(0, 0, width, height);
        ctx.drawImage(this.#video, width_diff, height_diff, width, height);
        requestAnimationFrame(draw_2DCanvas);
    };
    draw_2DCanvas();
</code></pre>
<p>But with just this the blur strength changes depending on the device, possibly because the canvas size differs.<br />
The blur applies as intended on pc devices, but is too strong on mobile devices.<br />
So I tried to spice things a little and change the blur in accordance to the current canvas style width (the canvas and video size is 360x270 but the html style size is responsive).</p>
<pre class="lang-js prettyprint-override"><code>    // this.#blur is usually 7
    const ctx = this.#canvas.getContext(&quot;2d&quot;);
    const draw_2DCanvas = () =&gt; {
        const blur =  Math.ceil(this.#blur * this.#canvas.clientWidth / 360);
        ctx.filter = &quot;blur(&quot; + blur + &quot;px)&quot;;
        ctx.clearRect(0, 0, width, height);
        ctx.drawImage(this.#video, width_diff, height_diff, width, height);
        requestAnimationFrame(draw_2DCanvas);
    };
    draw_2DCanvas();
</code></pre>
<p>But this time the blur is too strong on pc devices and a little too weak on mobile devices.<br />
What is the correct way to make the canvas blur consistent on every device?</p>

Title: ReactJS partially renders the old state after page refresh instead of rendering the updated and persisted state causing old and new states to show up.
Body: <p>Overall, this react app seems to function as expected. <strong>However, when the page is refreshed, only part of the changed state is persisted and correctly re-rendered</strong>, while the other part is reset back to the default state.</p>
<blockquote>
<p>If I go back to VS code and make any irrelevant changes (e.g. Add a comment), save, then go back to the browser, that default state would then gets updated and rendered again correctly.</p>
</blockquote>
<p><strong>So it seems like the reflection of the new state is delayed by 1 step</strong>, but I'm not sure what exactly is causing this weird behaviour.</p>
<p>Data is fetched using <code>react-query</code> v.5</p>
<p>Here is the code in the component:</p>
<pre><code>const tempU = [
        {
            id: 0,
            name: 'metric',
            symbol: 'C'
        },
        {
            id: 1,
            name: 'imperial',
            symbol: 'F'
        },
        {
            id: 2,
            name: 'standard',
            symbol: 'K'
        },
    ]



const WeatherDisplay = () =&gt; {


    const [currentPosition] = useAtom(currentPositionAtom)
    const [, clearCoordinates] = useAtom(clearCoordinatesAtom)
    const [tempUnitID, setTempUnitID] = useAtom(tempUnitIDAtom)


    const selectedTempUnitName = tempU[tempUnitID] &amp;&amp; tempU[tempUnitID].name

    // This logs the state correctly everytime 
    console.log('selectedTempUnitName: ', selectedTempUnitName)



    const { data: weatherData, refetch } = useGetCurrentWeather({ 
        currentPosition, 
        selectedTempUnitName
    })


    return (
        &lt;div className={`${style['WeatherDisplay']}`}&gt;
            &lt;h1 className={`${style['temperature']}`}&gt;
                &lt;span onClick={setTemperatureUnitHandler}&gt;


       // This shows old state after a page reload: (State persisted, but delayed by 1 step)
                    {weatherData?.main &amp;&amp; Math.round(weatherData?.main.temp)}


                    // This always shows up correctly
                    °{tempU[tempUnitID].symbol}
                &lt;/span&gt;
            &lt;/h1&gt;
        &lt;/div&gt;
    );
};

export default WeatherDisplay;
</code></pre>
<p>Here is what it looks like on the browswer:</p>
<p>Directly after page refreshed. Notice console logs the default state in the first log before the latest state follows. The state from API is not immediately re-rendered for some reason.</p>
<p><a href="https://i.stack.imgur.com/9ia6Y.png" rel="nofollow noreferrer"><img src="https://i.stack.imgur.com/9ia6Y.png" alt="Directly after page refreshed" /></a></p>
<p>After an irrelevant change made to code (e.g. Add a comment) and editor is saved, only then the latest state is correctly reflected in the browser. <strong>This delay is unexpected and shouldn't happen.</strong> Notice the log in the console still shows the correct state.
<a href="https://i.stack.imgur.com/5xSQ4.png" rel="nofollow noreferrer"><img src="https://i.stack.imgur.com/5xSQ4.png" alt="After irrelevant changes made to code and saved, the latest state is reflected" /></a></p>
<p>Here is the link to the repo: <a href="https://github.com/iceyisaak/weatherapp/blob/tanstack-query/src/components/WeatherDisplay/index.tsx#L86" rel="nofollow noreferrer">https://github.com/iceyisaak/weatherapp/blob/tanstack-query/src/components/WeatherDisplay/index.tsx#L86</a></p>
<p>Any help is very much appreciated :))</p>

Title: How to fix flickering/jittering of Skia-rendered canvas objects during GLFW window resizing?.
Body: <p>I've been working on a project that involves Skia and GLFW for rendering. When I attempt to resize a GLFW window containing a basic rectangle object rendered using Skia, the object experiences flickering / jittering. Here's the source code for reference:</p>
<pre><code>#include &lt;GLFW/glfw3.h&gt;
#include &lt;iostream&gt;
#include &quot;include/core/SkCanvas.h&quot;
#include &quot;include/core/SkPaint.h&quot;
#include &quot;include/core/SkRect.h&quot;
#include &quot;include/core/SkSurface.h&quot;
#include &quot;include/gpu/GrDirectContext.h&quot;

SkCanvas* canvas;
SkImageInfo info;
int width, height;
GLFWwindow* window;
sk_sp&lt;SkSurface&gt; surface;

SkPaint getPaint(SkColor s) { SkPaint paint; paint.setColor(s); return paint; }

void SetSurfaceAndCanvas() {
    info = SkImageInfo::Make(width, height, SkColorType::kRGBA_8888_SkColorType, SkAlphaType::kPremul_SkAlphaType);
    surface = SkSurfaces::Raster(info);
    canvas = surface-&gt;getCanvas();
    canvas-&gt;translate(0.0f, height);
    canvas-&gt;scale(1.0f, -1.0f);
}
void Draw() {

    canvas-&gt;drawRect(SkRect::MakeXYWH(0, 0, width, height), getPaint(SK_ColorWHITE));
    canvas-&gt;drawRect(SkRect::MakeXYWH(0, 0, 250, 250), getPaint(SK_ColorRED));

    if (auto dContext = GrAsDirectContext(canvas-&gt;recordingContext())) { dContext-&gt;flushAndSubmit(); }
    std::vector&lt;uint32_t&gt; pixels(width * height * 4);
    surface-&gt;readPixels(info, pixels.data(), width * sizeof(uint32_t), 0, 0);
    glDrawPixels(width, height, GL_RGBA, GL_UNSIGNED_BYTE, pixels.data());
    glfwSwapBuffers(window);
}

void frame_buffer_size_callback(GLFWwindow* fwindow, int w, int h) {
    width = w; height = h;
    SetSurfaceAndCanvas();
    Draw();
}

int main() {
    glfwInit();
    window = glfwCreateWindow(500, 500, &quot;Skia Test&quot;, nullptr, nullptr);
    glfwMakeContextCurrent(window);
    glfwGetFramebufferSize(window, &amp;(width), &amp;(height));
    glfwSetFramebufferSizeCallback(window, frame_buffer_size_callback);

    SetSurfaceAndCanvas();

    while (!glfwWindowShouldClose(window)) { 
        Draw();
        glfwPollEvents();
    }
    glfwDestroyWindow(window);
    glfwTerminate();
    return 0;
}
</code></pre>
<p><a href="https://i.stack.imgur.com/ge3cI.gif" rel="nofollow noreferrer">Here's a gif of the object flickering</a></p>
<p>System Details: Apple M1 Pro, Ventura 13.5.1</p>
<p>Command used to run the code:</p>
