Title: Metamask not returning &quot;code 4001 User rejected the request.&quot; when closing login popup in Chrome, but works in Edge.
Body: <p>I am trying to connect to the Metamask extension on Chrome by having a button that initiates the log in process on click. However in the event the user closes the log in pop up after clicking the button, no code 4001 exception is thrown in Chrome, the console log is completely empty. After that when I click the button again, it will no longer bring up the log in pop up but instead throw <strong>&quot;RPC Error: Already processing eth_requestAccounts. Please wait.&quot;</strong>
<a href="https://i.stack.imgur.com/ADMpR.png" rel="nofollow noreferrer"><img src="https://i.stack.imgur.com/ADMpR.png" alt="enter image description here" /></a></p>
<p>But when I tried in Edge, it throws just fine in the console (this is the expected result):
<a href="https://i.stack.imgur.com/kzyEj.png" rel="nofollow noreferrer"><img src="https://i.stack.imgur.com/kzyEj.png" alt="enter image description here" /></a></p>
<p>Refreshing the Chrome page does not help, I have to close and reopen the entire browser to reset it.</p>
<p>Looking into the extension icon, I noticed that in Edge, whenever I close the login button, the blue &quot;1&quot; notification which signifies pending transactions will be gone:</p>
<p><a href="https://i.stack.imgur.com/lQaQK.png" rel="nofollow noreferrer"><img src="https://i.stack.imgur.com/lQaQK.png" alt="enter image description here" /></a></p>
<p>However in Chrome that is not the case, the blue &quot;1&quot; notification remains:</p>
<p><a href="https://i.stack.imgur.com/qTXjw.png" rel="nofollow noreferrer"><img src="https://i.stack.imgur.com/qTXjw.png" alt="enter image description here" /></a></p>
<p>Here is the relevant code for the button if it helps. Any assistance is greatly appreciated:</p>
<pre><code>import { Card, CardContent, Button, Grid } from '@material-ui/core'
import React, { useEffect, useState } from &quot;react&quot;;
import MetaMaskOnboarding from '@metamask/onboarding';

function MetaMaskConnectButton(props) {    
    const forwarderOrigin = 'http://localhost:3000';    
    const onboarding = new MetaMaskOnboarding({ forwarderOrigin });    
    const { ethereum } = window;    
    const [buttonText, setButtonText] = useState('Connect MetaMask')    
    const [isButtonDisabled, setIsButtonDisabled] = useState(false)    
    const [mmAccounts, setMmAccounts] = useState('')    

    useEffect(() =&gt; {        
        if (!isMetaMaskInstalled()) {            
            setButtonText('Click here to install MetaMask!')        
        }
    }, [])    

    useEffect(() =&gt; {        
        if (mmAccounts == null || mmAccounts.length === 0)
            setIsButtonDisabled(false)       
        else            
            setIsButtonDisabled(true)    
    }, [mmAccounts])    

    async function metaMaskClientCheck() {        
        if (!isMetaMaskInstalled()) {            
            await metamaskInstall()            
            setIsButtonDisabled(true)        
        } 
        else {            
            await metamaskConnect()            
            setIsButtonDisabled(false)        
        }    
    }    

    //Function checks if the MetaMask extension is installed    
    const isMetaMaskInstalled = () =&gt; {        
        //Have to check the ethereum binding on the window object to see if it's installed
          return Boolean(ethereum &amp;&amp; ethereum.isMetaMask);    
    }    

    const metamaskInstall = async () =&gt; {        
        setButtonText('Onboarding in progress...')        
        setIsButtonDisabled(true)        
        onboarding.startOnboarding();    
    }    

    const metamaskConnect = async () =&gt; {        
        setIsButtonDisabled(true)        
        setButtonText('Connecting to MetaMask...')        
        try {            
            // Will open the MetaMask UI            
            let accounts = await ethereum.request({ method: 'eth_requestAccounts' }) 
            console.log('Ethereum Request over')            
            let account = accounts[0]            
            setMmAccounts(account)            
            setButtonText('MetaMask Connected')        
        } catch (error) {            
            console.error(error);            
            setIsButtonDisabled(false)            
            setButtonText('Connect MetaMask')        
        }    
    };    

    return (        
        &lt;Grid container xs={12} sm={12}&gt;
            &lt;Grid container xs={6} sm={6} justify='flex-start'&gt;
                &lt;Button                    
                    disabled={isButtonDisabled}                    
                    variant='contained'                    
                    color='secondary'
                    className='button-blue originalText'
                    onClick={() =&gt; {
                        metaMaskClientCheck()
                    }}
                    classes={{ root: 'ng-button-filled-secondary' }}
                &gt;
                    {buttonText}
                &lt;/Button&gt;
            &lt;/Grid&gt;
        &lt;/Grid&gt;
    )}
export default MetaMaskConnectButton
</code></pre>

