                    }}
                    classes={{ root: 'ng-button-filled-secondary' }}
                &gt;
                    {buttonText}
                &lt;/Button&gt;
            &lt;/Grid&gt;
        &lt;/Grid&gt;
    )}
export default MetaMaskConnectButton
