Title: How to property create and reference dynamic variable names in script.
Body: <p>I have a piece of code which works manually, but I am trying to make more reusable for growth.
In the function's current state, it sets a large list of manually created arrays. Then does a DB call for weekly snapshot numbers, and runs them through a foreach sort with a switch/case which pushes those values into the correct array. During that process it also puts together a list of all the workweeks recorded, then removes duplicates, transforms those workweeks into a string and pushes them to their own array.
Then it runs queries for live data, and pushes the results to the existing arrays. After that it returns the built object.</p>
<p>The code looks like this:</p>
<pre><code>globalCap: async function (req, res) {
        try {
            let af = [], workweeks = [], bf = [], ca = [], da = [], fr = [], gl = [], ch = [];
            let snapshots = await Snapshot.find().sort('createdTS ASC');
            snapshots.forEach(element =&gt; {
                switch (element.parentLocation) {
                    case 'AF':
                        af.push(element.totalSpaces);
                        break;
                    case 'BF':
                        bf.push(element.totalSpaces);
                        break;
                    case 'CA':
                        ca.push(element.totalSpaces);
                        break;
                    case 'DA':
                        da.push(element.totalSpaces);
                        break;
                    case 'FR':
                        fr.push(element.totalSpaces);
                        break;
                    case 'CH':
                        ch.push(element.totalSpaces);
                        break;
                    default:
                        break;
                }
                workweeks.push(element.workweek);
            });

            let uniqueWW = [...new Set(workweeks)];
            uniqueWW.forEach(element =&gt; {
                i = 'WW' + element;
                gl.push(i);
            });

            let afLive = await Location.count({
                parentLocationID: 1
            });
            af.push(afLive);
            let bfLive = await Location.count({
                parentLocationID: 2
            });
            bf.push(bfLive);
            let caLive = await Location.count({
                parentLocationID: 3
            });
            ca.push(caLive);
            let daLive = await Location.count({
                parentLocationID: 4
            });
            da.push(daLive);
            let frLive = await Location.count({
                parentLocationID: 5
            });
            fr.push(frLive);
            let chLive = await Location.count({
                parentLocationID: 6
            });
            ch.push(chLive);
            ww = 'WW' + workweek();
            gl.push(ww);
            return res.ok({
                'AF': af,
                'BF': bf,
                'CA': ca,
                'DA': da,
                'FR': fr,
                'CH': ch,
                'ww': gl,
            });
        }
        catch (error) {
            console.error(error);
        }
    },
</code></pre>
<p>And outputs this for use on some charts on the frontend:</p>
<pre><code>    {
        &quot;AF&quot;: [80,80,80],
        &quot;BF&quot;: [131,131,131],
        &quot;CA&quot;: [0,0,0],
        &quot;DA&quot;: [78,78,78],
        &quot;FR&quot;: [0,0,0],
        &quot;CH&quot;: [0,171,171],
        &quot;ww&quot;: [&quot;WW1&quot;,&quot;WW2&quot;,&quot;WW3&quot;]
      }
</code></pre>
<p>However, as this grows, I'd like to have the arrays created dynamically, based off the results of a query.</p>
<p>So I added a siteInfo query to the start which pulls and maps into the 2 componants I need, campusCode and id:</p>
<pre><code>    const siteInfo = await ParentLocation.find();
    const sites = siteInfo.map(obj =&gt; ({
        campusCode: obj.campusCode,
        id: obj.id
    }));
</code></pre>
<p>Which gives this output:</p>
<pre><code>  [
    { campusCode: 'AF', id: 1 },
    { campusCode: 'BF', id: 2 },
    { campusCode: 'CA', id: 3 },
    { campusCode: 'DA', id: 4 },
    { campusCode: 'FR', id: 5 },
    { campusCode: 'CH', id: 6 }
  ]
</code></pre>
<p>What would be the best way to sort and push the snapshot data into arrays, then reference them again to push the &quot;live&quot; data onto the end of each array based on the parentLocationID query? I feel like there is an easier way to do this, but I'm getting further and further into the weeds on it.</p>

Title: getting batch request from gmail api.
Body: <p>messageList we are sending message ids</p>
<pre><code>function getGmailMessagesBatch(oauth2Client, messagesList) {
    var batchBody = \ [\];
    var indReq = '';
    if (oauth2Client &amp;&amp; oauth2Client.credentials &amp;&amp; oauth2Client.credentials.access_token) {
        /*Generating the request body for the batch request
        according to gmail api docs for batching multiple api calls into one request
        each request should a part of the request body, so doing that below
        refer to gmail api docs for details info*/
        \
        _.each(messagesList, function(eachMessage) {
            indReq = '';
            indReq = &quot;--request_boundary\\n&quot; +
                &quot;Authoriz
            ation: Bearer &quot;+oauth2Client.credentials.access_token+&quot;\\
            n &quot;+
            &quot;Content-Type: application/http\\n\\n&quot; +
            &quot;GET /gmail/v1/users/&quot; + data.userEmail + &quot;/messages/&quot; + eachMessage.id + &quot;\\n&quot;;
            batchBody.push(indReq);
        })
        batchBody.push(&quot;--request_boundary--\\n&quot;);
        batchBody = batchBody.join('\\n');
        //Sending the batch request
        rp({
                uri: 'https://www.googleapis.com/batch/gmail/v1',
                method: 'POST',
                headers: {
                    &quot;content-type&quot;: &quot;multipart/mixed; boundary=request_boundary&quot;
                },
                body: batchBody,
                resolveWithFullResponse: true
            })
            .then(function(response) {
                /*The response is stringified &amp; the response to each of the api calls present
                in the batch request is seperated by a boundary which is present in the content
                type header of the response,therefore we need to parse the response to
                obtain the actual data*/
                var parsedResponse = parseBatchResponse(response);
                return cb(null, parsedResponse);
            })
            .catch(function(error) {
                sails.log.error('Error in getting messages async in eachseries', error, data);
                return cb('Unexpected error!');
            })
    } else {
        sails.log.error('Access token missing to sync emails using gmail api', data);
        return cb('Authorization failure!');
    }
}
</code></pre>
