Title: How to program a malloc() implementation with correct pointer alignment in C.
Body: <p>I'm currently trying to recode my own implementation of <code>malloc()</code> in C language. I followed several tutorials but each time the pointer alignment was inccorect (aligned to a power of 4) but according to the ABI it is necessary for <code>malloc()</code> to return a pointer aligned to a power of 8. So I re-adapted one. I recoded <code>malloc()</code>, <code>free()</code>, <code>calloc()</code>, <code>realloc()</code>, <code>reallocf()</code>.</p>
<p>When testing <code>malloc()</code> I get silent errors with valgrind. When testing further (multiple calls to <code>malloc()</code>, <code>realloc()</code>, <code>free()</code>) I get a segfault.</p>
<p>Here's the code:</p>
<pre class="lang-c prettyprint-override"><code>#include &lt;stdio.h&gt;
#include &lt;unistd.h&gt;
#include &lt;stdint.h&gt;
#include &lt;string.h&gt;

typedef struct block_s *block_t;

    struct block_s {
        size_t size;
        block_t next;
        block_t prev;
        int free;
        void *ptr;
        char data[1];
    };


#define BLOCK_SIZE 36

#define align8(x) (((((x) - 1) &gt;&gt; 3) &lt;&lt; 3) + 8)

void *base = NULL;

block_t get_block(void *p)
{
    char *tmp;
    tmp = p;
    return (p = tmp -= BLOCK_SIZE);
}

int valid_addr(void *p)
{
    if (base) {
        if (p &gt; base &amp;&amp; p &lt; sbrk(0))
            return (p == (get_block(p))-&gt;ptr);
    }
    return (0);
}

block_t fusion(block_t b)
{
    if (b-&gt;next &amp;&amp; b-&gt;next-&gt;free) {
        b-&gt;size += BLOCK_SIZE + b-&gt;next-&gt;size;
        b-&gt;next = b-&gt;next-&gt;next;
        if (b-&gt;next)
            b-&gt;next-&gt;prev = b;
    }
    return (b);
}

void split_block(block_t b, size_t s)
{
    block_t new;
    new = (block_t) b-&gt;data + s;
    new-&gt;size = b-&gt;size - s - BLOCK_SIZE;
    new-&gt;next = b-&gt;next;
    new-&gt;prev = b;
    new-&gt;free = 1;
    new-&gt;ptr = new-&gt;data;
    b-&gt;size = s;
    b-&gt;next = new;
    if (new-&gt;next)
        new-&gt;next-&gt;prev = new;
}

block_t find_block(block_t *last, size_t size)
{
    block_t b = sbrk(0);
    while (b &amp;&amp; !(b-&gt;free &amp;&amp; b-&gt;size &gt;= size))
    {
        *last = b;
        b = b-&gt;next;
    }
    return (b);
}

block_t extend_heap(block_t last, size_t s)
{
    int64_t sb;
    block_t b;
    b = sbrk(0);
    sb = (size_t) sbrk(BLOCK_SIZE + s);
    if (sb &lt; 0)
        return (NULL);
    b-&gt;size = s;
    b-&gt;next = NULL;
    b-&gt;prev = last;
    b-&gt;ptr = b-&gt;data;
    if (last) {
        last-&gt;next = b;
    }
    b-&gt;free = 0;
    return (b);
}

void copy_block(block_t src, block_t dest)
{
    size_t *sdata, *ddata;
    size_t i;
    sdata = src-&gt;ptr;
    ddata = dest-&gt;ptr;
    for (i = 0; (i * 8) &lt; src-&gt;size &amp;&amp; (i * 8) &lt; dest-&gt;size; i++)
        ddata[i] = sdata[i];
}

void my_free(void *p)
{
    block_t b;
    if (valid_addr(p)) {
        b = get_block(p);
        b-&gt;free = 1;
        if (b-&gt;prev &amp;&amp; b-&gt;prev-&gt;free) {
            b = fusion(b-&gt;prev);
        }
        if (b-&gt;next) {
            fusion(b);
        } else {
            if (b-&gt;prev)
                b-&gt;prev-&gt;next = NULL;
            else
                base = NULL;
            brk(b);
        }
    }
}

void *my_malloc(size_t size)
{
    block_t b, last;
    size_t s;
    s = align8(size);
    if (base) {
        last = base;
        b = find_block(&amp;last, s);
        if (b) {
            if ((b-&gt;size - s) &gt;= (BLOCK_SIZE + 8))
                split_block(b, s);
            b-&gt;free = 0;
        } else {
            b = extend_heap(last, s);
            if (!b)
                return (NULL);
        }
    } else {
        b = extend_heap(NULL, s);
        if (!b)
            return (NULL);
        base = b;
    }
    return (b-&gt;data);
}

void *my_calloc(size_t number, size_t size)
{
    size_t *new, s8, i;
    new = my_malloc(number * size);
    if (new) {
        s8 = align8(number * size) &lt;&lt; 3;
        for (i = 0; i &lt; s8; i++)
            new[i] = 0;
    }
    return (new);
}

void *my_realloc(void *p, size_t size)
{
    size_t s;
    block_t b, new;
    void *newp;
    if (!p) {
        return (my_malloc(size));
    }
    if (valid_addr(p)) {
        s = align8(size);
        b = get_block(p);
        if (b-&gt;size &gt;= s) {
            if (b-&gt;size - s &gt;= (BLOCK_SIZE + 8)) {
                split_block(b, s);
            }
        } else {
            if (b-&gt;next &amp;&amp; b-&gt;next-&gt;free &amp;&amp; (b-&gt;size + BLOCK_SIZE + b-&gt;next-&gt;size) &gt;= 5) {
                fusion(b);
                if (b-&gt;size - s &gt;= (BLOCK_SIZE + 8)) {
                    split_block(b, s);
                }
            } else {
                newp = my_malloc(s);
                if (!newp) {
                    return (NULL);
                }
                new = get_block(newp);
                copy_block(b, new);
                my_free(p);
                return (newp);
            }
        }
        return (p);
    }
    return (NULL);
}

void *my_reallocf(void *p, size_t size)
{
    void *newp;
    newp = my_realloc(p, size);
    if (!newp)
        my_free(p);
    return (newp);
}
</code></pre>
<p>Here is the malloc's test code :</p>
<pre class="lang-c prettyprint-override"><code>int main(void)
{
    char *str = my_malloc(15 * sizeof(char));
    str = strcpy(str, &quot;Hello World!\0&quot;);
    printf(&quot;# Malloc test\nString %p = %s\n&quot;, str, str);
    my_free(str);
}
</code></pre>
<p>And here's the valgrind report:</p>
<pre class="lang-bash prettyprint-override"><code>==56698== Memcheck, a memory error detector
==56698== Copyright (C) 2002-2022, and GNU GPL'd, by Julian Seward et al.
==56698== Using Valgrind-3.21.0 and LibVEX; rerun with -h for copyright info
==56698== Command: ./build/my_malloc
==56698== 
==56698== Invalid write of size 8
==56698==    at 0x1098B3: main (my_malloc.c:214)
==56698==  Address 0x403502d is in the brk data segment 0x4035000-0x4035033
==56698== 
==56698== Invalid read of size 1
==56698==    at 0x4847ED4: strlen (vg_replace_strmem.c:501)
==56698==    by 0x48E36E8: __printf_buffer (vfprintf-process-arg.c:435)
==56698==    by 0x48E3E51: __vfprintf_internal (vfprintf-internal.c:1523)
==56698==    by 0x48D92FE: printf (printf.c:33)
