function mix_max_step_desc_quick_edit_fields( $column_name, $post_type ) {

    switch( $column_name ) {
        case 'min': {
            ?&gt;
            &lt;fieldset class=&quot;inline-edit-col-left&quot;&gt;
            &lt;div class=&quot;inline-edit-col&quot;&gt;
                &lt;label&gt;
                    &lt;span class=&quot;title&quot;&gt;Min&lt;/span&gt;
                    &lt;input type=&quot;text&quot; name=&quot;min&quot;&gt;
                &lt;/label&gt;
            &lt;/div&gt;
            &lt;?php
