Title: NextJS Facebook SDK - FB.login not working.
Body: <p>I have a NextJS 13 project I am trying to add social login to.</p>
<p>I just can't seem to get FB.login to respond.</p>
<p>All of the examples I can find are for JavaScript or React, not NextJS which may do things a little differently.</p>
<p>My code:</p>
<pre><code>    import Script from 'next/script';

    const LoginPage = () =&gt; {


        const facebookLoginButton = async (event) =&gt; {

            console.log(&quot;Facebook button!&quot;)

            setLoading(true);

            window.fbAsyncInit = function() {
                FB.init({
                    appId      : MY_FACEBOOK_APP_ID,
                    status     : true, 
                    cookie     : true,
                    xfbml      : true,
                    version    : 'v16.0'
                });
            };

            const { authResponse } = await new Promise(() =&gt; {window.FB.login}); &lt;---Hangs here

            console.log(`login.js - Facebook Auth response was: `, authResponse)

        }

        return(

                &lt;div&gt;
                    &lt;p&gt;Login With:&lt;/p&gt;
                    &lt;Image src=&quot;facebooklogin-button.png&quot; width=&quot;300&quot; height=&quot;46&quot; onClick={facebookLoginButton} alt=&quot;Login&quot;&gt;&lt;/Image&gt;
                &lt;/div&gt;

                &lt;Script src=&quot;https://connect.facebook.net/en_US/sdk.js&quot; strategy=&quot;beforeInteractive&quot;&gt;&lt;/Script&gt;

        )

    }
    export default LoginPage;
</code></pre>
<p>Notice I am using the NextJS script tag to load the Facebook SDK, I have also tried this method but same result:</p>
<pre><code>import { useEffect } from 'react'

     useEffect(() =&gt; {
        window.fbAsyncInit = function() {
          window.FB.init({
            appId            : 'MY_FACEBOOK_APP_ID',
            autoLogAppEvents : true,
            xfbml            : true,
            version          : 'v16.0'
          });
        };

        (function(d, s, id) {
          let js, fjs = d.getElementsByTagName(s)[0];
          if (d.getElementById(id)) return;
          js = d.createElement(s); js.id = id;
          js.src = &quot;https://connect.facebook.net/en_US/sdk.js&quot;;
          fjs.parentNode.insertBefore(js, fjs);
        }(document, 'script', 'facebook-jssdk'));
      }, []);
      }
</code></pre>
<p>How can I get a response from FB.login ? I need to get the accessToken to pass to my back end.</p>
<p>I have thought about using the npm package &quot;react-facebook-login&quot; but it was last updated 5 years ago so I'd rather stay away. I also see that Next-Auth has a faceboook social login, but I don't think that can provide the accessToken, it just does everything for you.</p>
<p>Any help appreciated!</p>

Title: Laravel-Echo Not Listening.
Body: <p>Im using laravel 9.</p>
<p>Im trying to create real-time chat in my project. But the laravel-echo does not listen to my event. The event does trigger and appear when Im runs <code>queue:work</code> in command.</p>
<p>Im using database to run my queue jobs.</p>
<p>This is my ChatEvent.php</p>
<pre><code>class ChatEvent implements ShouldBroadcast
{
    use Dispatchable, InteractsWithSockets, SerializesModels;

    public $data;

    /**
     * Create a new event instance.
     *
     * @return void
     */
    public function __construct($data)
    {
        $this-&gt;data = $data;
    }

    /**
     * Get the channels the event should broadcast on.
     *
     * @return \Illuminate\Broadcasting\Channel|array
     */
    public function broadcastOn(): Channel
    {
        return new Channel('chat.1');
    }

    public function broadcastAs(): string
    {
        return 'chat-event';
    }
}
</code></pre>
<p>This is my channels.php</p>
<pre><code>Broadcast::channel('chat.1', function () {
    return true;
});
</code></pre>
<p>This is my ChatController.php</p>
<pre><code>class ChatController extends Controller
{
    public function sendMessage(Request $request)
    {        
        $data = $this-&gt;storeMessage($request);
        event(new ChatEvent($data));

        return response()-&gt;json(['success' =&gt; true, 'message'=&gt;$data-&gt;contents, 'created_by'=&gt; carbon($data-&gt;created_by)-&gt;format('g:i A')]);
    }
}
</code></pre>
