Title: Problem using Riverpod Code Generation in Dart (addListener).
Body: <p>I am doing a project with riverpod with annotations after I did the same project without annotations. I have tried to adapt all the providers that I have in the first project, but I am having a problem when accessing the _authNotifier.addListener since it tells me that it is not defined.</p>
<p>I'm not sure what is going on, so it will be helpful y you can help me!</p>
<h1>This is my first project's code and it works perfect</h1>
<p><code>**auth_provider.dart**</code></p>
<pre class="lang-dart prettyprint-override"><code>final authProvider = StateNotifierProvider&lt;AuthNotifier, AuthState&gt;((ref) {
  final authRepository = AuthRepositoryImpl();
  final keyValueStorageService = KeyValueStorageServiceImpl();

  return AuthNotifier(
    authRepository: authRepository,
    keyValueStorageService: keyValueStorageService,
  );
});

class AuthNotifier extends StateNotifier&lt;AuthState&gt; {
  final AuthRepository authRepository;
  final KeyValueStorageService keyValueStorageService;

  AuthNotifier({
    required this.authRepository,
    required this.keyValueStorageService,
  }) : super(AuthState()) {
    checkAuthStatus();
  }

  Future&lt;void&gt; loginUser(String email, String password) async {
    try {
      final user = await authRepository.login(email, password);
      _setLoggedUser(user);
    } on CustomError catch (e) {
      logout(e.message);
    } catch (e) {
      logout('Error no controlado');
    }
  }

  void registerUser(String email, String password, String fullName) async {}

  void checkAuthStatus() async {
    final token = await keyValueStorageService.getKeyValue&lt;String&gt;('token');
    if (token == null) return logout();

    try {
      final user = await authRepository.checkAuthStatus(token);
      _setLoggedUser(user);
    } catch (e) {
      logout();
    }
  }

  _setLoggedUser(User user) async {
    await keyValueStorageService.setKeyValue('token', user.token);

    state = state.copyWith(
      user: user,
      authStatus: AuthStatus.authenticated,
      errorMessage: '',
    );
  }

  Future&lt;void&gt; logout([String? errorMessage]) async {
    await keyValueStorageService.removeKey('token');

    state = state.copyWith(
      authStatus: AuthStatus.unauthenticated,
      user: null,
      errorMessage: errorMessage,
    );
  }
}

enum AuthStatus { checking, authenticated, unauthenticated }

class AuthState {
  final AuthStatus authStatus;
  final User? user;
  final String errorMessage;

  AuthState({
    this.authStatus = AuthStatus.checking,
    this.user,
    this.errorMessage = '',
  });

  AuthState copyWith({
    AuthStatus? authStatus,
    User? user,
    String? errorMessage,
  }) =&gt;
      AuthState(
        authStatus: authStatus ?? this.authStatus,
        user: user ?? this.user,
        errorMessage: errorMessage ?? this.errorMessage,
      );
}
</code></pre>
<p><code>**app_router_notifier.dart**</code></p>
<pre class="lang-dart prettyprint-override"><code>final goRouterNotifierProvider = Provider((ref) {
  final authNotifier = ref.read(authProvider.notifier);
  return GoRouterNotifier(authNotifier);
});

class GoRouterNotifier extends ChangeNotifier {
  final AuthNotifier _authNotifier;

  AuthStatus _authStatus = AuthStatus.checking;

  GoRouterNotifier(this._authNotifier) {
    _authNotifier.addListener((state) {
      authStatus = state.authStatus;
    });
  }

  AuthStatus get authStatus =&gt; _authStatus;

  set authStatus(AuthStatus value) {
    _authStatus = value;
    notifyListeners();
  }
}
</code></pre>
<h1>Now this is my second project using annotations (Here is the problem)</h1>
<p><code>**auth_provider.dart**</code></p>
<pre class="lang-dart prettyprint-override"><code>part 'auth_provider.g.dart';

@Riverpod(keepAlive: true)
class Auth extends _$Auth {
  final authRepository = AuthRepositoryImpl();
  final keyValueStorageService = KeyValueStorageServiceImpl();

  @override
  AuthState build() {
    checkAuthStatus();
    return AuthState();
  } 

  Future&lt;void&gt; loginUser(String email, String password) async {
    try {
      final user = await authRepository.login(email, password);

      _setLoggedUser(user);
    } on CustomError catch (e) {
      logout(e.message);
    } catch (e) {
      logout('Error no controlado');
    }
  }

  void registerUser(String email, String password, String username) async {}

  void checkAuthStatus() async {
    final token = await keyValueStorageService.getKeyValue&lt;String&gt;('token');
    if (token == null) return logout();

    try {
      final user = await authRepository.checkAuthStatus(token);
      _setLoggedUser(user);
    } catch (e) {
      logout();
    }
  }

  _setLoggedUser(User user) async {
    await keyValueStorageService.setKeyValue('token', user.token);

    state = state.copyWith(
      user: user,
      authStatus: AuthStatus.authenticated,
      errorMessage: '',
    );
  }

  Future&lt;void&gt; logout([String? errorMessage]) async {
    await keyValueStorageService.removeKey('token');

    state = state.copyWith(
      authStatus: AuthStatus.unauthenticated,
      user: null,
      errorMessage: errorMessage,
    );
  }
}

enum AuthStatus { checking, authenticated, unauthenticated }

class AuthState {
  final AuthStatus authStatus;
  final User? user;
  final String errorMessage;

  AuthState({
    this.authStatus = AuthStatus.checking,
    this.user,
    this.errorMessage = '',
  });

  AuthState copyWith({
    AuthStatus? authStatus,
    User? user,
    String? errorMessage,
  }) =&gt;
      AuthState(
        authStatus: authStatus ?? this.authStatus,
        user: user ?? this.user,
        errorMessage: errorMessage ?? this.errorMessage,
      );
}
</code></pre>
<p><code>**app_router_notifier.dart**</code></p>
<pre class="lang-dart prettyprint-override"><code>part 'app_router_notifier.g.dart';

@Riverpod(keepAlive: true)
GoRouterNotifier goRouterNotifier(Ref ref) {
  final authNotifier = ref.read(authProvider.notifier);

  return GoRouterNotifier(authNotifier);
}

class GoRouterNotifier extends ChangeNotifier {
  final Auth _authNotifier;

  AuthStatus _authStatus = AuthStatus.checking;

  GoRouterNotifier(this._authNotifier) {
   _authNotifier.addListener((state) {
      authStatus = state.authStatus;
    });
  }

  AuthStatus get authStatus =&gt; _authStatus;

  set authStatus(AuthStatus value) {
    _authStatus = value;
    notifyListeners();
  }
}
</code></pre>
<h1>So what is the problem?</h1>
<p>As you can see I'm trying to do the exact same thing, but in <code>app_router_notifier.dart</code> in this line:</p>
<pre class="lang-dart prettyprint-override"><code>_authNotifier.addListener((state) {
      authStatus = state.authStatus;
    });
</code></pre>
<p><strong>I'm getting this error:</strong> The method 'addListener' isn't defined for the type 'Auth'.
Try correcting the name to the name of an existing method, or defining a method named 'addListener'.</p>
<p>I've tried different solutions even with AI and nothing. I think that there's something wrong in my auth_provider.dart but I'm not sure what it is. I believe that the <code>.addListener</code> is in the <code>StateNotifier</code> but it isn't in the NotifierProvider that generates Riverpod.</p>
<pre class="lang-dart prettyprint-override"><code>// GENERATED CODE - DO NOT MODIFY BY HAND

part of 'auth_provider.dart';

// **************************************************************************
// RiverpodGenerator
// **************************************************************************

String _$authHash() =&gt; r'baf96bdb5085978702d0e2b04c3a2e56893b8a41';

/// See also [Auth].
@ProviderFor(Auth)
final authProvider = NotifierProvider&lt;Auth, AuthState&gt;.internal(
  Auth.new,
  name: r'authProvider',
  debugGetCreateSourceHash:
      const bool.fromEnvironment('dart.vm.product') ? null : _$authHash,
  dependencies: null,
  allTransitiveDependencies: null,
);

typedef _$Auth = Notifier&lt;AuthState&gt;;
// ignore_for_file: type=lint
// ignore_for_file: subtype_of_sealed_class, invalid_use_of_internal_member, invalid_use_of_visible_for_testing_member, inference_failure_on_uninitialized_variable, inference_failure_on_function_return_type, inference_failure_on_untyped_parameter
</code></pre>
<p>There are other &quot;solutions&quot; that didn't work for me:</p>
<pre class="lang-dart prettyprint-override"><code>_authNotifier.listen&lt;AuthStatus&gt;((state) {
      authStatus = state.authStatus;
    });
</code></pre>
<pre class="lang-dart prettyprint-override"><code>_authNotifier.ref.listen(authProvider.notifier, (_, currentState) {
      authStatus = currentState.state.authStatus;
    });
</code></pre>
<pre class="lang-dart prettyprint-override"><code> _authNotifier.addListener((state) {
      final authState = _authNotifier.build();
      authStatus = authState.authStatus;
    });
</code></pre>
<h1>A little bit of context of the application</h1>
<p>I'm using Flutter, Dart, Riverpod and Go Router to do a login and signup in my backend (NestJS + GraphQL), in the following file I'm trying to redirect the user if doesn't have a valid token. Here is where I'm using the goRouterNotifier so it can listen when the state changes and redirect the user.</p>
<pre class="lang-dart prettyprint-override"><code>part 'app_router.g.dart';

@Riverpod(keepAlive: false)
GoRouter goRouter(GoRouterRef ref) {
  final goRouterNotifier = ref.read(goRouterNotifierProvider);

  return GoRouter(
    initialLocation: '/login',
    refreshListenable: goRouterNotifier,
    routes: [
      //* First Route
      GoRoute(
        path: '/checking',
        builder: (context, state) =&gt; const CheckAuthStatusScreen(),
      ),

      //* Shared Routes
      GoRoute(
          path: '/main/:page',
          builder: (context, state) {
            final pageIndex = state.pathParameters['page'] ?? '0';
            return MainScreen(pageIndex: int.parse(pageIndex));
          }),

      GoRoute(
        path: '/settings',
        builder: (context, state) =&gt; const SettingdScreen(),
      ),

      //* Auth Routes
      GoRoute(
        path: '/login',
        builder: (context, state) =&gt; const LoginScreen(),
      ),
      GoRoute(
        path: '/signup',
        builder: (context, state) =&gt; const SignUpScreen(),
      ),

      //* Home Routes
    ],
    redirect: (context, state) {
      // print(state.matchedLocation);
      final isGoingTo = state.matchedLocation;
      final authStatus = goRouterNotifier.authStatus;

      if (isGoingTo == '/checking' &amp;&amp; authStatus == AuthStatus.checking) {
        return null;
      }

      if (authStatus == AuthStatus.unauthenticated) {
        if (isGoingTo == '/login' || isGoingTo == '/signup') return null;

        return '/login';
      }

      if (authStatus == AuthStatus.authenticated) {
        if (isGoingTo == '/login' ||
            isGoingTo == '/signup' ||
            isGoingTo == '/checking') return '/main/0';
      }

      return null;
    },
  );
}
</code></pre>

Title: Handle exceptions in Laravel Event Listener.
Body: <p>I want to handle Exceptions in my Listener exactly in <code>handle()</code> method</p>
<pre class="lang-php prettyprint-override"><code>/**
 * Handle the event.
 *
 * @param DocumentGenerated $event
 * @return void
 */
public function handle(DocumentGenerated $event)
{
    $data = $event-&gt;data;
    $this-&gt;generateDoc($data);
}
</code></pre>
<p>After I read the documentation I found that the handle() method of the listener should return false to stop the event propagation.</p>
<p>I changed the return type of the handle() method from void to boolean and tried returning false but it didn't stop the event propagation.</p>

Title: MediaPlayer not looping a raw resource MP3 file (Kotlin).
