import androidx.lifecycle.ViewModelStore
import androidx.lifecycle.ViewModelStoreOwner
import androidx.lifecycle.ViewTreeLifecycleOwner
import androidx.lifecycle.ViewTreeViewModelStoreOwner
import androidx.savedstate.SavedStateRegistry
import androidx.savedstate.SavedStateRegistryController
import androidx.savedstate.SavedStateRegistryOwner
import androidx.savedstate.setViewTreeSavedStateRegistryOwner
import com.soloftech.keyboard.data.keyboard_layout.Key
import com.soloftech.keyboard.presentation.layout.CustomKeyboard


class CustomImeService : InputMethodService(), LifecycleOwner, ViewModelStoreOwner,
    SavedStateRegistryOwner {

    companion object {
        var isCapsEnabled = false
    }

    private var isBackspaceKeyPressed = false
    private val handler = Handler(Looper.getMainLooper())
    private var deleteCharacterRunnable = object : Runnable {
        override fun run() {
            val inputConnection = currentInputConnection

            if (inputConnection != null &amp;&amp; isBackspaceKeyPressed) {
                val selectedText: CharSequence? = inputConnection.getSelectedText(0)

                if (selectedText != null &amp;&amp; !TextUtils.isEmpty(selectedText)) {
                    // There is selected text, so delete it
                    inputConnection.commitText(&quot;&quot;, 1)
                } else {
                    // No selected text, delete the character to the left
                    inputConnection.deleteSurroundingText(1, 0)
                }

                // Schedule the next deletion after 100 ms
                handler.postDelayed(this, 100)
            }
        }
    }

    override fun onCreateInputView(): View {
        val view = ComposeKeyboardView(this)

        window!!.window!!.decorView.let { decorView -&gt;
            ViewTreeLifecycleOwner.set(decorView, this)
            ViewTreeViewModelStoreOwner.set(decorView, this)
            view.setViewTreeSavedStateRegistryOwner(this)
        }
        view.let {
            ViewTreeLifecycleOwner.set(it, this)
            ViewTreeViewModelStoreOwner.set(it, this)
            it.setViewTreeSavedStateRegistryOwner(this)
        }
        return view
    }


    fun doSomethingWith(
        key: Key,
        isLongPressed: Boolean
    ) {
        when (key.label) {
            &quot;Space&quot; -&gt; {
                if (isLongPressed) {
                    val imm = getSystemService(INPUT_METHOD_SERVICE) as InputMethodManager
                    imm.showInputMethodPicker()
                } else {
                    currentInputConnection.commitText(&quot; &quot;, 1)
                }
            }

            &quot;CAPS&quot; -&gt; {
                isCapsEnabled = !isCapsEnabled
            }

            &quot;Done&quot; -&gt; {
                currentInputConnection.sendKeyEvent(
                    KeyEvent(
                        KeyEvent.ACTION_DOWN,
                        KeyEvent.KEYCODE_ENTER
                    )
                )
            }

            &quot;Delete&quot; -&gt; {
                if (isLongPressed) {
                    // Start character deletions when the key is long-pressed
                    if (!isBackspaceKeyPressed) {
                        isBackspaceKeyPressed = true
                        deleteCharacterRunnable.run()
                    }
                } else {
                    val inputConnection = currentInputConnection

                    if (inputConnection != null) {
                        val selectedText: CharSequence? = inputConnection.getSelectedText(0)

                        if (selectedText != null &amp;&amp; !TextUtils.isEmpty(selectedText)) {
                            // There is selected text, so delete it
                            inputConnection.commitText(&quot;&quot;, 1)
                        } else {
                            // No selected text, delete the character to the left
                            inputConnection.deleteSurroundingText(1, 0)
                        }
                    }
                }
            }

            else -&gt; {
                val inputConnection = currentInputConnection
                if (inputConnection != null) {
                    val label = key.label
                    val uppercaseValue = if (isCapsEnabled) label.uppercase() else label
                    inputConnection.commitText(uppercaseValue, 1)
                }
            }

        }
    }

    fun longPressedStops() {
        // Stop character deletions when the key is released
        isBackspaceKeyPressed = false
        handler.removeCallbacks(deleteCharacterRunnable)
    }

    //SaveStateRegistry Methods
    private val savedStateRegistryVar = SavedStateRegistryController.create(this)

    override val savedStateRegistry: SavedStateRegistry
        get() = savedStateRegistryVar.savedStateRegistry

    //Lifecycle Methods
    private var lifecycleRegistry: LifecycleRegistry = LifecycleRegistry(this)

    override fun getLifecycle(): Lifecycle {
        return lifecycleRegistry
    }

    private fun handleLifecycleEvent(event: Lifecycle.Event) =
        lifecycleRegistry.handleLifecycleEvent(event)

    override fun onCreate() {
        super.onCreate()
        savedStateRegistryVar.performRestore(null)
        lifecycleRegistry.handleLifecycleEvent(Lifecycle.Event.ON_RESUME)
    }


    override fun onDestroy() {
        super.onDestroy()
        handleLifecycleEvent(Lifecycle.Event.ON_DESTROY)
    }

    //ViewModelStore Methods
    private val store = ViewModelStore()

    override fun getViewModelStore(): ViewModelStore = store

}

@SuppressLint(&quot;ViewConstructor&quot;)
class ComposeKeyboardView(private val imeService: CustomImeService) :
    AbstractComposeView(imeService) {

    @Composable
    override fun Content() {
        CustomKeyboard(
            imeService = imeService,
            vibrator = vibrator,
            context = context
        )
    }

    private val vibrator: Vibrator by lazy {
        if (Build.VERSION.SDK_INT &gt;= Build.VERSION_CODES.S) {
            val vibratorManager = getSystemService(context, VibratorManager::class.java)
            vibratorManager?.defaultVibrator ?: getSystemService(context, Vibrator::class.java)
        } else {
            getSystemService(context, Vibrator::class.java)
        } as Vibrator
    }

}


</code></pre>
