            // ... rest of object
          },
        ],
      },
    ],
  },
  // ... rest of objects
]
</code></pre>
<p>I cant wrap my head around how to recursively loop from the bottom of the array, then back up.</p>
<p>My code that sorts array under children looks like this:</p>
<pre><code>function addChild(obj) {
    // get children and further retrieve its children with map recursively
    let children = menuItems.filter(a =&gt; a.parentFolderId == obj.id).map(addChild)

    // if children are found then add childs in object ALso check if item is in shop
